-- GENERATED by `wfj generate` from data/quest/quest-0001.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [1001] = { nil, "Raccogli 3 Thresher Eye dai Darkshore Thresher nelle acque profonde di ⟦Darkshore=Rivafosca⟧, vicino al Buzzbox 411.", "Una vocina gracchia dal profondo della macchina.\n\n\"Qui Wizbang! Il prossimo Buzzbox è a nord di Auberdine, sulla spiaggia\n\nDunque, quel Buzzbox è il numero 411 e per le riparazioni gli servono 3 Thresher Eye. Sono appena al largo della costa! I darkshore thresher... *Hic*... Scusa...\n\nCome l'ultima volta, quando darai la roba al Buzzbox, lui sputerà fuori la tua ricompensa. *Hic*... Cosa? No, sto benissimo!\"", "Lo sportello della macchina è aperto e sembra attendere che ci vengano messi dentro 3 Thresher Eye.", "Il Buzzbox si rianima ronzando poco dopo che hai messo dentro i Thresher Eye. C'è un attimo di scariche prima che tu senta una vocina familiare.\n\n\"Il vino di crawler è il migliore...\" *hic*\n\n\"Cosa? Oh, l'hai già aggiustato? Accidenti, shei proprio veloshe. Allora, ti va di aggiushtarne un altro?\"\n\nTi sembra di sentire un liquido versato in una tazza, seguito da rumorose sorsate.", 0xed386236, 0xe7f4d482, 0x03c10b82, 0x32d3a2c9, 0x37ad4bdf, "e...." },
  [1002] = { nil, "Raccogli 6 Moonstalker Fang e mettile nel Buzzbox 323.", "Il Buzzbox emette un crepitio di statica e senti Wizbang cominciare a parlare.\n\n\"Il proshimo Buzzbox è il numero 323. Shta a nord di Auberdine, ma... dov'è la birra? Eh? Ah, shta shulla shtrada, quindi non dovresti avere problemi a trovarlo vicino al ponte.\"\n\nWizbang borbotta qualcosa di incomprensibile, poi senti un rumoroso glu glu.\n\n\"Queshto vuole delle Moonstalker Fang... 6.\"", "Anche se non hai ancora messo dentro le 6 Moonstalker Fang, ti sembra di sentire provenire dall'interno crepitii di statica e incomprensibili farneticazioni di uno gnomo. Che qualcun altro abbia già riparato la macchina?", "All'improvviso il Buzzbox si rimette in funzione, e dall'interno senti il rumore inconfondibile di denti che vengono macinati fino a diventare polvere.\n\n\"Shhì, ce l'hai fatta! Quesht'è una notizia eshellente... Shhì... Perché non ti levi di torno? Oh! A meno che tu non voglia un altro lavoro!\"", 0xed381fb2, 0x81dea735, 0xb07e5e5e, 0x32946a73, 0xcd12f60d, "e...." },
  [1003] = { nil, "Raccogli 4 Grizzled Scalp dai Grizzled Thistle Bear a sud di Auberdine e mettili nel Buzzbox 525.", "Sopra i gorgoglii e i gocciolii che escono dalla macchina, senti la voce tremolante di Wizbang.\n\n\"Il proshimo è molto più a shud, lungo la shtrada. Non dovrebbe eshere difficile da trovare... appena di lato... vischino a uno shteccato. Credo di averlo nashcosto in qualche cesphuglio... Cesphugli. Ihihih... Shì, il Buzzbox 525 prende gli shcalpi ishpidi di quegli orshi dei cardi ishpidi. Accidenti, che shcioglilingua. Ishpidi... Ihihih...\"\n\nSenti altri rumori di deglutizione mentre la macchina si spegne. Poi, all'improvviso, si riaccende.\n\n\"4!\"", "Senti cantare dal Buzzbox 525.\n\n\"Il vino di crostasheo è dolsche, la birra di plesiosauro è fina, e il liquore di braccaluna è shublime. Ma niente è più caro di una birra d'orsho dei cardi, e presto ne avrò in cantina!\"\n\nIl portello è aperto e attende i 4 scalpi ispidi, mentre senti la canzone ripetersi all'infinito.", "\"Quindi gli shcalpi ce li hai messhi? Ma che bello... Eh? Beh, shì, shuppongo che tu abbia capito che posso parlarti anche shenza i materiali nella macchina. Ma dischevo la verità quando ho detto che erano rotti!\n\nVedi, oltre a eshere shtrumenti di comunicamazione, i Buzzbox fanno anche birra e dishtillano liquori pregiati. Shcusha per l'inganno, ma gli Elfi della Notte non apprezzamerano il mio commercio di liquori nelle loro città. Ho messo qualcosa di shpeciale in queshta shcatola per mostrarti la mia gratitudine per i tuoi shforzi. Goditela!\"", 0xed38a5c6, 0x456f18b8, 0x7c095433, 0x36f0523a, 0x8072af47, "e...." },
  [1005] = { "Ciò che si cela oltre", nil, nil, nil, nil, 0xe3c2cb6b, nil, nil, nil, nil, ".mmmm" },
  [1006] = { "Ciò che si cela oltre", nil, nil, nil, nil, 0x3af589ca, nil, nil, nil, nil, ".mmmm" },
  [1007] = { "La ⟦Ancient Statuette=Statuetta Antica⟧", "Porta la ⟦Ancient Statuette=Statuetta Antica⟧ a Talen, nel suo accampamento vicino alla ⟦Zoram Strand=Spiaggia di Zoram⟧.", "Vorrei affidarti un compito, {name}.\n\nEro sulla mia piccola imbarcazione e scivolavo sopra le rovine sommerse di Zoram, quando i naga mi hanno attaccato, sbucando dall'acqua e dilaniandomi con gli artigli! Sono fuggito, portando con me le provviste che potevo per allestire questo misero accampamento.\n\nMa quando ho raggiunto la riva e sono scappato... ho perso il mio bene più prezioso.\n\nTi prego, {name}, trova il luogo dell'imboscata, lungo la costa a nord, e cerca una statuetta antica. È per lei che ho sfidato i pericoli della ⟦Zoram Strand=Spiaggia di Zoram⟧.", "Hai trovato la statuetta, {name}?", "L'hai trovata! Grazie, {name}!\n\nL'antica città di Zoram custodisce molti segreti, e questa statuetta potrebbe essere la chiave di molti di essi.", 0x4f6fc8bc, 0x8d5ca3e4, 0xc4983d64, 0x4a9921c4, 0xad8649d6, "....." },
  [1008] = { "La ⟦The Zoram Strand=Spiaggia di Zoram⟧", "Porta 20 Wrathtail Head a Shindrell Swiftfire, ad Astranaar.", "Sulla nostra costa nord-occidentale, nota come ⟦Zoram Strand=Spiaggia di Zoram⟧, si annida il male.\n\nLì riposa la città perduta di Zoram, distrutta durante la Frattura e sommersa dai mari. Gli Elfi della Notte l'hanno perduta da secoli. Perduta, e quasi dimenticata.\n\nOra i naga sono tornati, e non sappiamo per quale motivo. Ma il motivo conta poco: dobbiamo uccidere questi demoni e ricacciarli negli abissi!\n\nTorna da me quando avrai portato a termine la tua missione.", "Non possiamo permettere che i naga invadano le nostre coste, {name}. È fondamentale che tu vada alla ⟦Zoram Strand=Spiaggia di Zoram⟧ e porti a termine la tua missione.", "Davvero ben fatto, {name}. Le tue azioni contro i naga sulla ⟦Zoram Strand=Spiaggia di Zoram⟧ sono encomiabili.\n\nSo che la tua impresa non è stata facile, perché la forza e l'astuzia dei naga sono ben note agli Elfi della Notte. Lo sappiamo perché condividiamo con loro una storia.\n\nUna storia che non ho alcun desiderio di ripetere.", 0x9cbacfd8, 0x9d25563d, 0x187db273, 0x72b741c0, 0xd6ba7f97, "....." },
  [1009] = { nil, "Porta l'⟦Ring of Zoram=Anello di Zoram⟧ a Talen, vicino alla ⟦Zoram Strand=Spiaggia di Zoram⟧.", "Temo che i segreti dell'antica statuetta resteranno nascosti per sempre, a meno che tu non trovi la chiave della sua antica serratura.\n\nQuella chiave è un anello, l'⟦Ring of Zoram=Anello di Zoram⟧. Apparteneva ai sovrani di questa città, prima che le onde della Separazione la sommergessero.\n\nPer anni l'anello è rimasto perduto, ma di recente l'hanno trovato i naga.\n\nIl loro capo, Ruuzel, dimora su un'isola al margine settentrionale di Zoram. Ti prego, {name}, recupera l'anello per me!", "Si dice che l'⟦Ring of Zoram=Anello di Zoram⟧ sia la chiave di qualunque serratura della città. Ce l'hai, {name}?", "Hai trovato l'anello! Grazie, {name}. Ti prego, accetta questo come compenso, e sappi che le tue gesta di oggi resteranno per sempre nella mia memoria.", 0xa5f22a9f, 0x9ce8fe4c, 0x90dfae10, 0xfa173a78, 0x281d1a0e, "e...." },
  [1010] = { "⟦Bathran's Hair=Capelli di Bathran⟧", "Porta 5 ⟦Bathran's Hair=Capelli di Bathran⟧ a Orendil Broadleaf, a ⟦Ashenvale=Valtetra⟧.", "Un tempo, tra le antiche rovine del ⟦Bathran's Haunt=Covo di Bathran⟧, a nord, cresceva una pianta. Si chiamava ⟦Bathran's Hair=Capelli di Bathran⟧ ed era nota per curare i mali dello spirito.\n\nNel villaggio c'è un bambino malato, e credo che non si tratti solo di una malattia del corpo. Andresti al ⟦Bathran's Haunt=Covo di Bathran⟧ a cercare i ⟦Bathran's Hair=Capelli di Bathran⟧? Potrebbero servirmi per curare il bambino come si deve.\n\nIl ⟦Bathran's Haunt=Covo di Bathran⟧ si trova a nord dell'⟦Maestra's Post=Accampamento di Maestra⟧, appena a sud del confine con ⟦Darkshore=Rivafosca⟧.", "Hai raccolto i ⟦Bathran's Hair=Capelli di Bathran⟧, {name}? La salute del bambino peggiora di ora in ora...", "Ah, hai i capelli! Ora preparerò una cura per il bambino, e pregherò che il mio intruglio funzioni.\n\nE... ci sono dei Reietti al ⟦Bathran's Haunt=Covo di Bathran⟧? Notizia molto preoccupante, questa. Davvero molto preoccupante...", 0x74a86ba6, 0xd56778b9, 0xaa6b3524, 0x340001ab, 0xbadaf9b1, "....." },
  [1011] = { "Le malattie dei Reietti", "Porta una ⟦Bottle of Disease=Bottiglia di Malanno⟧ a Kayneth Stillwind, a ⟦Forest Song=Cantaselva⟧.", "I Reietti, il braccio non morto dell'⟦Horde=Orda⟧, si sono insinuati a ⟦Ashenvale=Valtetra⟧ e si annidano tra le nostre rovine e i nostri tumuli. Crediamo che il loro scopo sia diffondere malattie nelle terre degli elfi della notte. Dobbiamo averne la conferma!\n\nI Reietti hanno un accampamento a sud di qui, vicino all'Eremo di Dor'danil, dove creano veleni e malattie e li mettono in bottiglia. Fatti strada combattendo fino all'accampamento e ruba una bottiglia di malattia. Torna con una di quelle bottiglie. La analizzerò e scoprirò a cosa serve.", "Hai trovato l'accampamento, {name}? Hai una bottiglia di malattia?", "Molto bene, {name}. Ora... analizzando il contenuto di questa bottiglia, scopriremo gli scopi dei Reietti!", 0x56f1d203, 0x2dc3785e, 0xb7d7e188, 0x4bef8879, 0x706dafea, "....." },
  [1013] = { "Il ⟦The Book of Ur=Libro di Ur⟧", "Porta il Libro di Ur al custode Bel'dugur, all'Apothecarium di ⟦Undercity=Sepulcra⟧.", "{name}, il ⟦Shadowfang Keep=Forte di Zannascura⟧ custodisce un libro, il Libro di Ur, che sarebbe un pezzo molto prezioso nella mia collezione. Ur era un grande mago di Dalaran prima dell'arrivo del Flagello; i suoi studi su altri mondi hanno molto valore per... certe fazioni tra i Reietti.\n\nEntra nel ⟦Shadowfang Keep=Forte di Zannascura⟧ e trova il libro. Portamelo e riferirò il tuo servizio alla nostra Dama Oscura...", "Hai trovato il libro, {name}?", "Molto bene. Questo libro arricchirà degnamente la mia raccolta delle opere di Ur. La sua sapienza era grande, ma la coscienza lo tenne lontano dal vero potere. E così, quando arrivò il Flagello e la sua forza fu messa alla prova, cedette.\n\nNoi Reietti non possiamo permetterci una simile debolezza, se vogliamo sopravvivere...\n\n...Se vogliamo conquistare.", 0x550d5dac, 0xa4439184, 0x27fdd02a, 0xfe172e90, 0x675a81e7, "....." },
  [1014] = { "Arugal deve morire", "Uccidi Arugal e porta la sua testa a Dalar Dawnweaver, alla ⟦Sepulcher=Mausolea⟧.", "Arugal risiede ancora nel ⟦Shadowfang Keep=Forte di Zannascura⟧. Non possiamo rivendicare ⟦Silverpine=Pinargento⟧ come roccaforte strategica per la Dama Oscura finché Arugal non sarà ucciso.\n\nMi assicurerò che la sua magia venga estirpata, {name}. Ma lascio nelle tue mani il compito di far sì che Arugal incontri la morte che tanto merita.\n\nRaggiungi il ⟦Shadowfang Keep=Forte di Zannascura⟧ e poni fine una volta per tutte ai turpi incantesimi di Arugal. Portami la testa di quel vile mago!", "Con la morte di Arugal potremo rafforzare la presa della Dama Oscura su Lordaeron.", "La ⟦Silverpine Forest=Selva Pinargento⟧ è finalmente libera dalla morsa di quel miserabile di Arugal. Hai reso un grande servizio alla Dama Oscura, {name}. La tua tenacia sarà ricompensata.", 0xa62d9f82, 0x2b1851cd, 0x5186e893, 0xbfc38023, 0xd0cbb456, "....." },
  [1016] = { "Bracciali elementali", "Raccogli 5 Intact Elemental Bracer e usa su di essi la ⟦Divining Scroll=Pergamena Divinatoria⟧. Poi porta la ⟦Divined Scroll=Pergamena della Profezia⟧ alla sentinella Velene Starstrike, al ⟦Silverwind Refuge=Rifugio Vento Argentato⟧.", "Prendi questa pergamena divinatoria: può rivelare chi ha creato questi elementali. Ma ti servirà qualcosa di loro da usare come reagente per concentrare la magia della pergamena: i loro bracciali dovrebbero andare benissimo.\n\nQualche bracciale intatto di queste creature dovrebbe bastare. Gli altri bracciali non ci serviranno a nulla, ma potrebbero valere qualcosa per un mercante, se vuoi venderli. Quando avrai i bracciali intatti, prova a usare la pergamena. Torna da me con i risultati e decideremo come procedere.", "Visto che per uccidere gli elementali devi distruggerne i bracciali, sarà probabilmente difficile trovare proprio quelli che contengono le informazioni di cui ha bisogno la pergamena divinatoria. Puoi scambiare bracciali con altri per ottenere quelli che ti servono, o forse hai già la pergamena della profezia?", "Ben fatto, {name}: questo dovrebbe darci le informazioni che ci servono per scoprire il colpevole. Che ne diresti di eliminare il mago che riempie le nostre pozze di elementali corrotti? La corruzione di ⟦Ashenvale=Valtetra⟧ e delle terre oltre mi rivolta già lo stomaco da sola; che uno stregone cerchi attivamente di distruggerla ancora di più mi disgusta oltre ogni limite. Gliela faremo pagare.", 0xb698effb, 0xdea3d96f, 0x737c6b17, 0x90279ef1, 0x7f18db5a, "....." },
  [1017] = { "Il Mago evocatore", "Uccidi Sarilus Foulborne e porta la sua testa alla sentinella Velene Starstrike al ⟦Silverwind Refuge=Rifugio Vento Argentato⟧.", "C'è un solo mago non morto nelle ⟦Barrens=Savane⟧ capace di profanare così tanti elementali dell'acqua. Ed è anche l'unico abbastanza stolto da provarci. Sarilus Foulborne se ne starà probabilmente in cima al ⟦Dreadmist Peak=Picco di Brumafunesta⟧, a ridere di me.\n\n{name}, devi entrare in territorio nemico e distruggere quel miserabile. Ne ho abbastanza della sua idiozia, e dobbiamo mostrargli cosa succede a chi infastidisce le ⟦Sentinels=Sentinelle⟧.\n\nDistruggilo e portami la sua testa. Ma sta' in guardia: l'⟦Horde=Orda⟧ potrebbe tenerti d'occhio.", "È fatta? Sarilus Foulborne è morto?", "Ora posso vedere quel sorriso ripugnante cancellato per sempre dalla sua faccia. Hai fatto un ottimo lavoro, {name}. Prendi questa, la ⟦Light of Elune=Luce di Elune⟧: bevila quando tutto sembra perduto e la morte è vicina. Potrebbe salvarti, se la Dea vorrà.", 0xd88bf407, 0x0a5ea9a8, 0xb383c3fe, 0xd734a9d3, 0x762bf18f, "....." },
  [1020] = { "⟦Orendil's Cure=Cura di Orendil⟧", "Porta la ⟦Orendil's Cure=Cura di Orendil⟧ a Pelturas Whitemoon, ad Astranaar.", "{name}, ho preparato una cura che credo aiuterà il bambino malato. Portala ad Astranaar e consegnala al genitore del bambino, Pelturas Whitemoon.\n\nPer raggiungere Astranaar, segui la strada verso sud, poi verso est.", "Devo scusarmi, ma non ho tempo per parlare. Mia figlia Relara è gravemente malata!", "Questa viene da Orendil?\n\nLa sua abilità con le erbe e la guarigione è grande. Questa cura mi dà speranza, quando prima ne avevo poca...", 0xb9c0e606, 0xb594b387, 0x15801dd7, 0xb4a8bb23, 0x6dfa2147, "....." },
  [1022] = { "La ⟦The Howling Vale=Valle Ululante⟧", "Va' alla Valle Ululante e studia il Tome of Mel'Thandris, poi torna dalla sentinella Melyria Frostshadow al Santuario di Aessina.", "Anche se abbiamo investito molte risorse e molti sforzi per scacciare i demoni rimasti nel ⟦Felwood=Vilbosco⟧, a nord, i nostri successi sono stati pochi. Siamo comunque riusciti a tenere gran parte della presenza demoniaca lontano da ⟦Ashenvale=Valtetra⟧.\n\nA nord, vicino al confine con il ⟦Felwood=Vilbosco⟧, il santuario in rovina di Mel'Thandris è stato invaso da misteriosi uomini lupo. I loro ululati agghiaccianti hanno fatto sì che la zona fosse chiamata Valle Ululante. Il tomo di Mel'Thandris custodito nel santuario potrebbe far luce sul perché questi uomini lupo siano arrivati.", "Il tomo del santuario è un oggetto misterioso. Non è un libro nel senso tradizionale. Le sue pagine sono state benedette da Mel'Thandris in persona e registrano gli eventi importanti.\n\nÈ difficile da spiegare. Se vai al santuario, capirai.", "Il tomo di Mel'Thandris agisce in modi strani. Gli eventi che registra, gli eventi che mostra... Nessuno capisce davvero perché faccia ciò che fa.\n\nCiononostante, è chiaro che ciò che la sacerdotessa Starsong ha ricevuto, questa Falce di Elune, merita ulteriori indagini.", 0x4a2cd655, 0xda6b6938, 0x9b613692, 0x9ace9f35, 0xa2144a21, "....." },
  [1023] = { "La purificazione di Raene", "Trova la ⟦Glowing Gem=Gemma Luminosa⟧ e torna da Raene Wolfrunner ad Astranaar con il ⟦Teronis' Journal=Diario di Teronis⟧.", "Frugando tra gli effetti personali di Teronis, trovi un diario ancora in buone condizioni.\n\nPrendi il diario e lasci il cadavere di Teronis com'è.\n\nNon resta che trovare la gemma che Teronis stava cercando. Raene ha detto che si trova in questa zona. Forse ce l'hanno i murloc...", "Ah, ben ritrovat<o/a>, {name}.", "È terribile, {name}. Teronis è morto?!\n\nVerrà il momento del lutto, ma per ora dobbiamo concentrare i nostri sforzi. Manderò alcune ⟦Sentinels=Sentinelle⟧ a recuperare il corpo di Teronis il prima possibile.\n\nHai il diario di Teronis e la gemma che stava cercando. Pensi di essere in grado di portare a termine il suo compito? Riposerei molto più tranquilla sapendo che la sua morte non è stata vana.", 0x30e3be54, 0x7f853c3d, 0xba0a18d8, 0x6c186150, 0x213bef75, "....." },
  [1024] = { "La purificazione di Raene", "Trova Shael'dryn al pozzo lunare a nord-est.", "Dovrai fare le ricerche da te, ma dagli appunti di Teronis sembra che la tua prossima mossa sia trovare gli altri pezzi della verga creata da Dartol. Io comincerei dal pozzo lunare a est dell'Iris Lake. Quando sei <pronto/pronta>, segui la strada e svolta a nord quando raggiungi una piccola area di sosta sulla sinistra.\n\nLì c'è una driade di nome Shael'dryn, più adatta a guidarti. Cercala.\n\nTieni la gemma con te: a Shael'dryn servirà, se dovrà aiutarti a ricreare la verga.", "Salve. Come stai?", "Oh, ti manda Raene? Dev'essere davvero una cosa seria. Come posso aiutarti?", 0x30e3be54, 0x870564ea, 0x74ecbe19, 0x8c397c59, 0xf0f35728, "....." },
  [1025] = { "Una difesa aggressiva", "Uccidi 1 Den Watcher, 2 Ursa, 10 Totemic e 12 Warrior della tribù Foulweald, poi torna da Raene Wolfrunner ad Astranaar.", "Prima che tu vada al pozzo lunare, ho un altro compito che aiuterà la gente di ⟦Ashenvale=Valtetra⟧, se vuoi mettere alla prova le tue capacità.\n\nLungo la strada verso est, prima del ⟦Falfarren River=Fiume Falfarren⟧, i mezzorsi attaccano i viandanti. Le loro menti tormentate si nutrono di paura e la loro fame si sazia col sangue degli innocenti.\n\nAiuta le ⟦Sentinels=Sentinelle⟧ a proteggere queste terre mostrando a quei mostri la stessa pietà che loro hanno mostrato alla nostra gente.\n\nCredo che i loro accampamenti siano a sud della strada... fai attenzione.", "I mezzorsi non sono sempre stati nostri nemici, {name}. Ma i tempi cambiano, e in questi boschi oscuri non è più tempo di pace.", "Hai fatto bene, {name}. Grazie.", 0xac8970c1, 0x61ad4540, 0xb29beaa2, 0xa6e6b187, 0x53926f7d, "....." },
  [1026] = { "La purificazione di Raene", "Trova la ⟦Wooden Key=Chiave di Legno⟧ e un pezzo della verga di Dartol, poi torna da Shael'dryn al pozzo lunare.", "Vorrei che portassi notizie migliori.\n\nRaene ha ragione, conosco la creazione di Dartol e i treant della zona... o almeno li conoscevo un tempo. Ora sono stati corrotti, la loro natura è distorta.\n\nSe il tuo obiettivo è trovare il prossimo pezzo della verga, dovrai trovare la chiave per aprire lo scrigno in cui si trova.\n\nLa chiave di legno ce l'ha uno dei treant a nord-est di qui, vicino a ⟦Felwood=Vilbosco⟧. Una volta presa, cerca una piccola radura a ovest della strada, vicino al confine con ⟦Felwood=Vilbosco⟧... lo scrigno dovrebbe essere nascosto da quelle parti.", "Mi addolora tanto che i treant siano stati corrotti. Vorrei poter fare di più per aiutarli.", "Sono felice di vedere che sei tornat<o/a>, {name}.", 0x30e3be54, 0x8ec36891, 0xbb4dd335, 0x2a083fa2, 0xee5a6576, "....." },
  [1027] = { "La purificazione di Raene", "Trova l'ultimo pezzo della verga di Dartol e torna da Shael'dryn al pozzo lunare.", "L'ultimo pezzo della verga fu affidato in custodia ai druidi di Dor'danil. Non ho idea di dove l'abbiano nascosto. Mi dispiace di non poterti aiutare più di così.\n\nPosso solo dirti di seguire la strada che porta verso le ⟦Barrens=Savane⟧. I druidi si erano rifugiati a est di quella strada, ma non ti saranno di grande aiuto: sono stati uccisi di recente... è una cosa a cui preferisco non pensare troppo.\n\nQuando trovi l'ultimo pezzo, portamelo e ti aiuterò a ricostruire la verga.", "Hai trovato l'ultimo pezzo della verga, {name}?", "Hai trovato l'ultimo pezzo? Magnifico per te... e per Raene.\n\nCredo che ora dovremo pensare a ripararla, no?", 0x30e3be54, 0x717478b4, 0x52aaaf37, 0xe95940f0, 0x5810af11, "....." },
  [1028] = { "La purificazione di Raene", "Trova il santuario nascosto e incanta di nuovo la verga di Dartol.", "Ecco la verga completa, {name}. Ricostruirla è stato semplice... la parte difficile sarà trovare il santuario che ha il potere di ricaricarla.\n\nCon un po' di concentrazione e impegno non dovrebbe essere troppo difficile per qualcuno come te, che ha già fatto così tanto.\n\nDirigiti a sud-est di qui (ci sono pochissimi sentieri, quindi fa' attenzione) e tieni gli occhi rivolti a nord. Il santuario è nascosto tra le montagne che circondano questa radura.\n\nUna volta lì, metti la verga nel santuario... il resto è magia. Ih ih.", "Percepisci una forza sottile ma potente nel santuario e negli alberi intorno.\n\nCominci a sistemare la verga nel santuario e un lieve ronzio si diffonde intorno a te, mentre il santuario inizia a risplendere...", "Quando il bagliore si spegne, vedi la verga di nuovo incantata nella vasca del santuario.", 0x30e3be54, 0xb46bc4dc, 0xba1c18cf, 0xbf739d88, 0x772d23ad, "....." },
  [1029] = { "La purificazione di Raene", "Torna da Raene Wolfrunner ad Astranaar.", "Ti suggerisco di trovare Raene e di farle sapere che la verga è pronta. Sono sicura che saprà quale sarà la tua prossima mossa.\n\nBuona fortuna, {name}.", nil, "Hai ricreato la verga che Teronis voleva trovare? È meraviglioso sentirlo.\n\nTeronis sarebbe orgoglioso di vedere che la sua missione continua anche dopo la sua tragica scomparsa.", 0x30e3be54, 0x03b8caf8, 0x075c1399, nil, 0x6da04e68, "...m." },
  [1030] = { "La purificazione di Raene", "Trova un mezzorso non corrotto e parlagli usando il potere della ⟦Dartol's Rod of Transformation=Verga della Trasformazione di Dartol⟧.", "Purtroppo non so con certezza cosa avesse in mente dopo.\n\nSe ciò che diceva sul potere della verga era vero, allora ti permetterà di assumere un'altra forma. Quale forma, non lo so.\n\nForse intendeva usarne i poteri per avvicinarsi ai mezzorsi contaminati, ma persino le creature non corrotte l'avrebbero massacrato se non fosse stato attento. Trasformato dalla verga, Dartol avrebbe dovuto parlare con un mezzorso al riparo dagli effetti del ⟦Fel Moss=Vilmuschio⟧.\n\nIo comincerei a cercare a sud-est del ⟦Mystral Lake=Lago Mystral⟧.", nil, "Sì, sì... sei uno della mia specie, ma ancora integro. Ancora puro.\n\nNon so come tu sia sfuggito alle atrocità che gli Elfi della Notte hanno inflitto al nostro popolo, ma sono felice di sapere che non sono più solo.\n\nLa corruzione ora scorre nelle vene della nostra gente, giovane, una corruzione che ci hanno portato gli orgogliosi Elfi della Notte. Sono loro che hanno fatto questo al nostro popolo... Sono loro che incolpo per essere stato cacciato dalla mia tribù.\n\nDi notte vedo ancora i fuochi dell'accampamento ardere nell'oscurità.", 0x30e3be54, 0x9860f324, 0x7bc02b85, nil, 0xcb923d4d, "...m." },
  [1033] = { "⟦Elune's Tear=Lacrima di Elune⟧", "Porta la ⟦Elune's Tear=Lacrima di Elune⟧ a Pelturas ad Astranaar.", "Speravo che la cura di Orendil salvasse Relara, ma temo che abbia solo rallentato la malattia che consuma mia figlia. Dobbiamo trovare una medicina più potente! Per fortuna Orendil mi ha parlato di altri rimedi da tentare se il primo non avesse funzionato.\n\nLa ⟦Elune's Tear=Lacrima di Elune⟧ è un tipo di pietra che si trova in un solo luogo: l'isola sull'Iris Lake, a est di Astranaar. Orendil dice che la pietra laverà via la corruzione... ti prego, {name}, portami la ⟦Elune's Tear=Lacrima di Elune⟧ e prega che metta fine alla malattia di mia figlia!", "{name}, hai trovato l'Iris Lake? Hai la Lacrima?", "Oh, l'hai trovata! Metterò la Lacrima in uno stufato e pregherò che la guarisca.\n\nGrazie! Grazie, {name}!", 0xae0d2497, 0xc2de57c8, 0x0451f462, 0xfd413dac, 0x3c6ec55f, "....." },
  [1034] = { "Le ⟦The Ruins of Stardust=Rovine della Polvere Stellare⟧", "Porta 5 Manciata di Polvere di Stelle a Pelturas, ad Astranaar.", "La ⟦Elune's Tear=Lacrima di Elune⟧ ha lavato via parte della malattia di mia figlia. I suoi incubi si sono attenuati e ringrazio la dea per la sua benedizione. Ma... la febbre infuria ancora dentro di lei.\n\nOrendil mi ha parlato di una polvere brinata che si trova tra le Rovine della Polvere Stellare. Forse calmerà la febbre di Relara. Raccogli un po' di quella polvere, poi torna da me, ti prego.\n\nLe Rovine della Polvere Stellare si trovano a sud, {name}. Che Elune renda rapido il tuo viaggio.", "Hai già la polvere di stelle, {name}?", "Hai raccolto la polvere! Ne farò un impiastro: dovrebbe far scendere la febbre di Relara.\n\nGrazie ancora, {name}. Senza il tuo aiuto, mia figlia morirebbe di certo.", 0xfba883e2, 0xdede75fb, 0x14b3b904, 0x2c3445f3, 0x8980ab64, "....." },
  [1035] = { "⟦Fallen Sky Lake=Lago Cielinfranto⟧", "Recupera una ⟦Fallen Moonstone=Pietraluna Rubata⟧ dallo Shadethicket Oracle, poi portala a Pelturas ad Astranaar.", "La febbre di Relara è passata, ma è ancora molto debole. Non credo che il tempo da solo le restituirà le forze che ha perso. Credo che servirà il potere di una pietraluna.\n\nUn tempo raccoglievamo le pietrelune al ⟦Fallen Sky Lake=Lago Cielinfranto⟧, a sud-est... finché non sono arrivati gli Shadethicket.\n\nIl loro capo, uno Shadethicket Oracle, ha raccolto tutte le pietrelune cadute e le tiene per sé. Ora devi recuperare una pietraluna dall'oracolo.\n\nE per farlo, temo che dovrai ucciderlo.", "Hai affrontato lo Shadethicket Oracle, {name}? Se è così, ti prego, dammi la pietraluna caduta. A Relara restano forze solo per pochi altri respiri!", "Oh, {name}, hai salvato mia figlia! So che il potere della pietraluna restituirà le forze a mia figlia!\n\nNon potrò mai ripagarti del tutto per l'aiuto che mi hai dato, ma... ti prego, prendi questo. Dopo Relara, è la cosa che mi è più cara.", 0x2fb85293, 0xa905bcf0, 0xa253d48e, 0xc1063bd4, 0x077c83f2, "....." },
  [1037] = { nil, "Parla con Thyn'tel Bladeweaver alla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧, a Darnassus.", "Velinde Starsong mi ha preceduta qui nella foresta di ⟦Ashenvale=Valtetra⟧. All'inizio sembrava che avesse sotto controllo la situazione nel ⟦Felwood=Vilbosco⟧, ma a poco a poco i suoi sforzi hanno vacillato. Un giorno è semplicemente scomparsa.\n\nSono stata mandata qui per continuare il suo lavoro. Temo però di non sapere nulla della sacerdotessa. Forse Thyn'tel Bladeweaver, una delle comandanti delle ⟦Sentinels=Sentinelle⟧, conosce dettagli sulla sua scomparsa di cui non sono stata messa al corrente.\n\nDi certo capirà l'importanza di simili informazioni.", nil, "Velinde Starsong? Che la sacerdotessa sia scomparsa tempo fa è quasi certamente cosa nota. Quanto ad altri dettagli sugli eventi legati alla sua partenza... mi servirebbe una buona ragione per rivelare simili informazioni.", 0xf7ead98e, 0x98606e25, 0x016b231b, nil, 0xe9e791ce, "e..m." },
  [1038] = { "Gli effetti personali di Velinde", "Cerca il diario di Velinde nel suo baule, poi riportalo, insieme alla chiave, a Thyn'tel Bladeweaver a Darnassus.", "Il tomo di Mel'Thandris ti ha mostrato questo? Suppongo che non ci sia nulla di male nel lasciarti esaminare le sue cose. Questa chiave ti permetterà di aprire il baule dove abbiamo riposto i suoi effetti nel dormitorio delle ⟦Sentinels=Sentinelle⟧. Teneva un diario dei suoi compiti: se c'è qualcosa da scoprire, lo scoprirai da quello.\n\nDevo dirti che le ⟦Sentinels=Sentinelle⟧ credono che avesse le sue ragioni per andarsene, e si aspettano che possa tornare da un momento all'altro. In passato la sacerdotessa ha fatto molto per guadagnarsi la nostra fiducia.", "Che cosa hai scoperto?", "Sembra che la scomparsa di Velinde sia più preoccupante di quanto apparisse all'inizio. Eppure non riesco a credere che abbia fatto una brutta fine. Forse sarebbe utile per noi metterci in contatto con lei.\n\n{name}, visto che hai mostrato un interesse sincero per questa faccenda, vorrei chiedere il tuo aiuto.", 0x74dbac02, 0x09fb9185, 0x7dde5963, 0x7a7fed9c, 0x7a510565, "....." },
  [1039] = { "Il porto delle ⟦The Barrens=Savane⟧", "Parla con il capomolo Dizzywig a ⟦Ratchet=Porto Paranco⟧.", "⟦Ratchet=Porto Paranco⟧ è l'unico porto delle ⟦Barrens=Savane⟧. Molto probabilmente Velinde ha trovato a ⟦Ratchet=Porto Paranco⟧ una nave mercantile che la portasse alla ⟦Blackwater Cove=Baia degli Acquanera⟧, ad Azeroth. Abbiamo avuto pochi rapporti con i goblin che gestiscono il porto, ma il capomolo dovrebbe avere informazioni sugli arrivi e le partenze dei passeggeri.\n\nSegui la strada verso sud-est attraverso ⟦Ashenvale=Valtetra⟧ e ti ritroverai nelle ⟦Barrens=Savane⟧. Fa' attenzione a dove metti i piedi, {name}: i guerrieri dell'⟦Horde=Orda⟧ pattugliano quelle terre. Al porto, però, sarai al sicuro.", nil, "{race}, eh? Devo ammettere che da queste parti non se ne vedono molti come te. Cerchi qualcuno, eh? Dammi solo un momento, sono sicuro di averlo scritto in uno dei miei registri.\n\nDi qui passa un sacco di gente, però, quindi dammi solo un momento.", 0xbce71855, 0x368d5e90, 0x984e6dd9, nil, 0xa9762f9c, "...m." },
  [1040] = { "Passaggio per la ⟦Booty Bay=Baia del Bottino⟧", "Prendi una nave per la ⟦Booty Bay=Baia del Bottino⟧ e parla con il carovaniere Ruzzgot.", "Ah, sì, finalmente l'ho trovato. Potevi dirmelo che era passata di qui così tanto tempo fa. Vediamo.\n\nVelinde. Ha prenotato un passaggio per la ⟦Booty Bay=Baia del Bottino⟧ sulla Black Osprey. Non ho niente qui che dica il contrario, quindi presumo che la nave sia arrivata in porto senza problemi.\n\nNon posso esserti di molto altro aiuto, ma mi ha chiesto dei viaggi via terra da quella parte del mondo, e le ho parlato di Ruzzgot, un carovaniere che ha base alla ⟦Booty Bay=Baia del Bottino⟧. Può darsi che questa Velinde abbia viaggiato con lui.\n\nE adesso circola. Non ho tutto il giorno da dedicarti.", nil, "Sì? Allora, non mi sembri il tipo con della merce da spedire, quindi o cerchi lavoro nella mia carovana (e adesso di lavoro non ce n'è), oppure probabilmente stai parlando con il goblin sbagliato.\n\nAllora, qual è delle due?", 0x23568846, 0x924d775e, 0x42b15a26, nil, 0x7012c387, "...m." },
  [1041] = { "La via delle carovane", "Parla con lo scrivano Daltry a ⟦Darkshire=Borgoscuro⟧.", "A quanto pare mi sbagliavo su di te, e non è una cosa che capita tutti i giorni.\n\nGuarda caso, mi ricordo di questa Velinde che stai cercando. Non capita tutti i giorni che una sacerdotessa elfa della notte voglia viaggiare con una carovana vecchia e sporca (ma ottima per le tue spedizioni!) come la mia.\n\nCi siamo separati sulla strada verso nord: lei era diretta a ⟦Darkshire=Borgoscuro⟧. Lo scrivano di lì tiene registri di ogni genere. Forse sa qualcosa di utile.\n\nAttenzione nella giungla: è un posto mortale anche nei momenti migliori.", nil, "Con tutti gli strani avvenimenti degli ultimi anni, tengo registri sui forestieri più accurati che posso. Non si sa mai quando possono tornare utili... anche se di solito, quando succede, non si tratta di faccende piacevoli. Non che voglia insinuare nulla su questa Velinde che stai cercando.", 0xdd9cc4a0, 0x03b1164f, 0x16629094, nil, 0xba9aab3a, "...m." },
  [1042] = { "La famiglia Carevin", "Parla con Jonathan Carevin a ⟦Darkshire=Borgoscuro⟧.", "No, non ho nessuna registrazione di una certa Velinde Starsong che abbia alloggiato a ⟦Darkshire=Borgoscuro⟧... anche se, se mi permetti, faccio fatica a immaginare una sacerdotessa elfa della notte che prende una stanza alla locanda, se capisci cosa intendo.\n\nDi questi uomini lupo di cui parli, invece, ho sentito dire qualcosa. Proprio l'altro giorno Calor è arrivato in città con una fila delle loro teste. Lavora con la famiglia Carevin. Cacciatori di demoni, non morti e altre mostruosità. Parla con Jonathan, è il capofamiglia.", nil, "Tempi bui, questi. Cattive notizie sussurrano da ogni ramo che ondeggia, e il male si nasconde sotto ogni sasso.\n\nE in tempi come questi uno sconosciuto entra in casa mia e chiede dei worgen... Non chiederò perdono per i miei sospetti, solo risposte.\n\nE le risposte, le avrò.", 0x5b4165bb, 0x260919bb, 0x60b610fd, nil, 0xa9084ff2, "...m." },
  [1043] = { "La Falce di Elune", "Cerca tracce della Falce di Elune, poi torna da Jonathan Carevin a ⟦Darkshire=Borgoscuro⟧.", "La tua storia suona sincera... Non capisco del tutto le tue ragioni, ma se i tuoi affari qui a ⟦Duskwood=Boscovespro⟧ comprendono liberare la foresta dai worgen, in qualunque numero, allora posso rinunciare a capire in cambio di risultati.\n\nC'è una miniera a sud che è stata invasa dai worgen... Sono comparsi dal nulla, ma da quanto sappiamo è lì che sono stati trovati per la prima volta.\n\nVa' per la tua strada, ma ti chiedo, se trovi qualcosa di importante, di condividerlo con me. Accetteremo qualsiasi aiuto nella nostra guerra contro il male.", "I boschi sono pericolosi per chi non è preparato. Tieni le armi a portata di mano e il cervello ancora di più, o il tuo prossimo viaggio nella foresta infestata potrebbe essere l'ultimo.", "È una storia interessante quella che racconti, {name}. Anche se l'influenza della famiglia Carevin non è abbastanza grande da permetterci di trovare la radice di questi problemi ed estirparli una volta per tutte, faremo il possibile per contenere il numero dei worgen a ⟦Duskwood=Boscovespro⟧.\n\nHo già incaricato Calor di farne la sua priorità.", 0x0767908c, 0x803b9a4e, 0x6cd0e968, 0x9f8262d0, 0x837fbc53, "....." },
  [1044] = { "Domande con risposta", "Torna da Thyn'tel Bladeweaver a Darnassus.", "Terremo a freno il problema dei worgen, non temere. Questo male che la tua amica ha portato nei nostri boschi sarà contenuto, e non le porto rancore per ciò che ha fatto. Strani eventi si stanno compiendo in questi tempi, {name}, e l'oscurità non conosce tregua.\n\nNon ti trattengo oltre. Sospetto che ci siano altri che dovrebbero sapere ciò che hai trovato nelle miniere di ⟦Duskwood=Boscovespro⟧.", nil, "Dunque è questo il destino di Velinde? L'alta sacerdotessa sarà delusa di saperlo: erano buone amiche prima della sua scomparsa. Eppure la Falce di Elune le era stata di certo concessa come dono dalla nostra dea, e mi turba che sia sfuggita dalle mani dei suoi servitori.\n\nMa questa è una faccenda per un'altra volta. Ti devo non poca gratitudine per ciò che hai compiuto.", 0x44407ecd, 0xb8c245b0, 0x8d9eb68f, nil, 0x9bb2d02d, "...m." },
  [1045] = { "La purificazione di Raene", "Uccidi 4 Bloodtooth Guard e recupera il ⟦Ran Bloodtooth's Skull=Teschio di Ran Zannarossa⟧ per Krolg, vicino al Lago Mystral.", "Gli Elfi della Notte sono antichi quanto il tempo, ma la loro arroganza distrugge il loro stesso mondo. E ora distrugge anche le nostre vite. Ma questo non si può più controllare...\n\nIncolpo gli elfi di molte cose, ma restiamo responsabili delle nostre azioni. Anche al di là della corruzione, siamo capaci di grandi malvagità.\n\nRan Bloodtooth è una di queste malvagità. Assetato di potere, bramoso... la corruzione l'ha solo reso più forte. Il mio odio per gli elfi brucia, ma non auguro il male ai loro figli, quindi dobbiamo fare giustizia tra i nostri.", "Hai già ucciso Ran, amico mio?\n\nNemmeno gli Elfi della Notte meritano davvero la sua furia. Il suo odio brucia ancora più forte del mio, ma la sua mente non gli appartiene più. È una minaccia per tutte le creature naturali di questa foresta.", "Hai fatto bene, amico mio.\n\nLa foresta è ancora contaminata, ma almeno sappiamo di aver fatto una piccola parte per restituirle l'antico splendore. Se vorrai tornare da me, mi farà piacere la compagnia di uno della mia specie.\n\nStammi bene. Forse le nostre tribù si incontreranno di nuovo in tempi meno violenti.", 0x30e3be54, 0x6e8f41fa, 0x326975a1, 0x15e560ac, 0x765c3955, "....." },
  [1046] = { "La purificazione di Raene", "Porta il ⟦Ran Bloodtooth's Skull=Teschio di Ran Zannarossa⟧ e la ⟦Dartol's Rod of Transformation=Verga della Trasformazione di Dartol⟧ a Raene Wolfrunner ad Astranaar.", "Torna dalla tua tribù e annuncia la tua vittoria.\n\nMostra loro il tuo trofeo e goditi la gloria...", "Le ⟦Sentinels=Sentinelle⟧ fanno ciò che possono qui a ⟦Ashenvale=Valtetra⟧, ma è grazie a {race} come te che abbiamo guadagnato il terreno che abbiamo.", "Dunque, questo è il teschio della più feroce minaccia mezzorso di ⟦Ashenvale=Valtetra⟧?\n\nSono più che soddisfatta delle tue capacità, {name}. Le ⟦Sentinels=Sentinelle⟧ non potranno mai ringraziarti abbastanza. Spero che potremo contare ancora su di te in futuro per aiutare il nostro popolo.\n\nMetterò questo teschio e la verga di Dartol in un luogo d'onore, perché tutti possano vederli.\n\nTeronis sarebbe orgoglioso. Grazie ancora.", 0x30e3be54, 0x331416f0, 0xe5eec590, 0x96cede1d, 0xdaa0c8c3, "....." },
  [1054] = { "Sfoltire la minaccia", "Porta Dal Bloodclaw's Skull a Raene Wolfrunner ad Astranaar.", "Subito a nord di Astranaar ci sono i mezzorsi Mantocardo. I miei esploratori riferiscono che negli ultimi mesi il loro numero è cresciuto molto. Se diventeranno troppi, potrebbero trovare il coraggio di attaccare Astranaar direttamente.\n\nUccidine quanti più puoi, ma portami il teschio del loro capo come prova che i loro sforzi sono stati soffocati... per ora.\n\nResterò qui ad Astranaar in attesa di tue notizie. Che Elune sia con te.", "La corruzione dei mezzorsi ha ridotto ⟦Ashenvale=Valtetra⟧ a una pallida ombra del suo antico splendore.", "Ben fatto, {name}.\n\nSiamo sotto la costante minaccia dei mezzorsi. Speriamo che questo li tenga a bada ancora per un po'.", 0xc9327026, 0x0cf5cd78, 0xbc890332, 0xc10729bc, 0x94c3bc40, "....." },
  [1055] = { "La purificazione di Raene", "Torna da Shael'dryn al pozzo lunare.", "La verga, ora completa, è nelle tue mani. Shael'dryn vorrà sapere del tuo successo.", nil, "Ce l'hai fatta, {name}! Ben fatto!", 0x30e3be54, 0xa7333bfb, 0x652f01d5, nil, 0x9327f633, "...m." },
  [1056] = { "Viaggio al ⟦Stonetalon Peak=Picco di Petrartiglio⟧", "Raggiungi il custode Albagorm al ⟦Stonetalon Peak=Picco di Petrartiglio⟧.", "Gli spiriti della foresta mi dicono che sei coraggios<o/a> e dispost<o/a> a viaggiare.\n\nA sud, non lontano dal ⟦Mystral Lake=Lago Mystral⟧, c'è una galleria chiamata ⟦The Talondeep Path=Sentiero di Graffiofondo⟧. Attraverso questa galleria arriverai in una zona nota come ⟦Windshear Crag=Landa di Tagliavento⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧. Una volta lì, prosegui verso sud-ovest oltre il ⟦Cragpool Lake=Lago di Altarupe⟧ e poi verso nord, su per il ripido pendio, finché non raggiungerai il ⟦Stonetalon Peak=Picco di Petrartiglio⟧.\n\nLì ti attende il custode Albagorm. Ascolta ciò che ti chiede, {race}.\n\nIl viaggio sarà pericoloso.", nil, "Finalmente sei arrivat<o/a>. Vedo che Faldreas ha ascoltato gli spiriti della foresta...", 0xb967664b, 0xecb8a211, 0xb0111aba, nil, 0x3ad69b06, "...m." },
  [1057] = { "La riconquista della ⟦Charred Vale=Valle Bruciata⟧", "Il custode Albagorm, sul ⟦Stonetalon Peak=Picco di Petrartiglio⟧, vuole che tu uccida 6 Bloodfury Harpy, 6 Bloodfury Ambusher, 6 Bloodfury Slayer e 6 Bloodfury Roguefeather.", "Da <protettore/protettrice> degli spiriti della foresta, puoi certo immaginare perché sono in allarme.\n\nHai attraversato queste montagne per raggiungere questo picco. Avrai sicuramente visto lo scempio che si è abbattuto su questa terra. L'avidità ha portato alla distruzione di queste colline sacre.\n\nLa ⟦Charred Vale=Valle Bruciata⟧, a sud, è stata data alle fiamme dall'avido esercito meccanizzato degli industriali. Peggio ancora, le Bloodfury che hanno invaso la terra ci negano il passaggio per cominciare a farla rinascere.\n\nScaccia quelle miserabili arpie, {name}!", "C'è molto lavoro da fare prima che la ⟦Charred Vale=Valle Bruciata⟧ possa tornare la foresta rigogliosa di un tempo.\n\nLibera la zona da quelle turpi minacce, {name}! Solo allora potremo cominciare a reclamare ciò che appartiene alla natura.", "Ora che le Bloodfury hanno subito una perdita così grave, forse può cominciare il vero lavoro di risanamento della terra...", 0x3dc3d0c0, 0xe2dfdbfc, 0x38e3847a, 0x64c961c6, 0x08e244c5, "....." },
  [1058] = { "La magia della foresta di Jin'Zil", "Il santone Jin'Zil, a Malaka'jin, vuole 5 porzioni di ⟦Stonetalon Sap=Linfa di Petrartiglio⟧, 5 Twilight Whisker, 30 Courser Eye e una ⟦Fey Dragon Scale=Scaglia di Drago Fatato⟧.", "Che emozione!\n\nTre gabbiette per tre elfetti! Ma cosa faremo dei nostri adorabili amici abbraccia-alberi? Ma certo, facciamogli assaggiare un po' di... come la chiamano... magia della foresta!\n\nMi serve una bella dose di linfa di ⟦Stonetalon=Petrartiglio⟧. Da quei felini orribili portami dei baffi del crepuscolo. Qui ci vogliono parecchi occhi di cervo cornuto, ovvio: gli occhi non bastano mai. Oh, e non dimentichiamo una preziosa scaglia di drago fatato.\n\nCorri al ⟦Stonetalon Peak=Picco di Petrartiglio⟧, {name}, così potrò preparare un po' di magia della foresta!", "Guarda i nostri poveri amichetti elfi. Tutti in gabbia, senza una foresta in cui scorrazzare!\n\nAllora, sei riuscit<o/a> a trovarmi un po' di linfa? E i baffi dei Twilight Runner? Non avrai per caso con te quella scaglia di drago fatato?\n\nE gli occhi! Mi servono tantissimi occhi! Non si può preparare un feroce intruglio di magia della foresta senza una bella porzione di occhi!", "Oh, come saranno felici queste ninfette dei boschi! Con questo intruglio speciale le faremo sentire proprio a casa!", 0xd3c89429, 0x92c3cbae, 0xe1ca5db1, 0x7327810a, 0x33e6fef9, "....." },
  [1059] = { "La riconquista della ⟦Charred Vale=Valle Bruciata⟧", "Raggiungi Falfindel Waywarder al confine tra ⟦Thousand Needles=Millepicchi⟧ e Feralas.", "Le Bloodfury sono state domate. Ma si riorganizzeranno presto se non si interviene.\n\nMolto a sud delle ⟦Barrens=Savane⟧ si trova una terra chiamata ⟦Thousand Needles=Millepicchi⟧. Se viaggi verso ovest attraverso ⟦Thousand Needles=Millepicchi⟧ fino al limite della rigogliosa foresta di Feralas, troverai un druido di nome Falfindel Waywarder.\n\nQuesto grande e saggio druido è in grado di evocare i grandi spiriti della foresta, che possono aiutare a riconquistare la ⟦Charred Vale=Valle Bruciata⟧.\n\nFagli sapere che abbiamo bisogno di lui! Cercalo subito!", nil, "Il custode Albagorm è stato saggio a mandarti con tanta urgenza.\n\nVediamo se riusciamo a chiamare in aiuto la grande foresta, perché raggiunga la ⟦Charred Vale=Valle Bruciata⟧ prima che sia troppo tardi.", 0x3dc3d0c0, 0x9d2cf9a3, 0xc8c5b4c2, nil, 0x1237db66, "...m." },
  [1060] = { "⟦Letter to Jin'Zil=Lettera per Jin'zil⟧", "Consegna la lettera di Darsok a Jin'Zil, nella sua caverna a Malaka'Jin, a ⟦Stonetalon=Petrartiglio⟧.", "Mi hai servito proprio bene, {name}. Sei un vero portafortuna, e c'è una cosa che voglio farti vedere.\n\nLe arpie non sono originarie delle ⟦Barrens=Savane⟧. Vengono da un posto chiamato ⟦Stonetalon=Petrartiglio⟧, molto a nord-ovest di qui. Anche se probabilmente per te è un posto pericoloso, ho bisogno che questa lettera arrivi a un mio vecchio amico che vive lì, uno stregone vudù di nome Jin'Zil.\n\nSarà felice di sapere che Serena Bloodfeather è morta, e credo che troverai ⟦Stonetalon=Petrartiglio⟧ un posto interessante.", "Hai l'aria di un tipo losco. Hai qualcosa da farmi vedere?", "Ahh, una lettera da Darsok. Non ho sue notizie da molti anni.\n\nDunque le ultime Piumarossa sono morte, eh? È una bella notizia. Mi ricordo di quando il mio amico Rokhan andò con quel pazzo mok'nathal a uccidere sua sorella maggiore. Ah, essere di nuovo giovani, come te.", 0x0a260107, 0xab583fdb, 0x4a63eb6f, 0x2660ed01, 0x0dff3a9f, "....." },
  [1061] = { "Gli spiriti di ⟦Stonetalon=Petrartiglio⟧", "Parla con Seereth Stonebreak nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "Gli spiriti delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ sono adirati, perché i goblin e i loro servi saccheggiano e bruciano la terra. Così la terra ha gridato, e coloro che ascoltano tali cose... hanno udito.\n\nSeereth Stonebreak, una promettente sciamana dell'⟦Horde=Orda⟧, è stata mandata a ⟦Stonetalon=Petrartiglio⟧. Riferisce di un disboscamento massiccio per mano dei goblin e chiede aiuto.\n\nRaggiungi Seereth a ⟦Stonetalon=Petrartiglio⟧. Per arrivare da lei, segui la strada a ovest del ⟦Crossroads=Crocevia⟧ delle ⟦Barrens=Savane⟧. È accampata vicino alla ⟦Greatwood Vale=Valle Grandalbero⟧.", nil, "Ah, un {class}. Molto bene. Ci serviranno le tue abilità per affrontare questi predoni!", 0x5fee63cf, 0x8e781950, 0xb39a0a24, nil, 0x1a8942fd, "...m." },
  [1062] = { "Invasori goblin", "Uccidi 15 Venture Co. Logger, poi torna da Seereth Stonebreak, al confine tra ⟦Stonetalon=Petrartiglio⟧ e le ⟦Barrens=Savane⟧.", "La ⟦Venture Company=S.P.R. & Co.⟧, gestita dai goblin, si è insediata nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧, abbattendo alberi e bruciando enormi distese di foresta. Gli spiriti di questo luogo sono quasi accecati dal dolore e dalla rabbia. Dobbiamo fermare la ⟦Venture Company=S.P.R. & Co.⟧!\n\nDirigiti a nord-ovest, oltre la ⟦Greatwood Vale=Valle Grandalbero⟧, fino alla ⟦Windshear Crag=Landa di Tagliavento⟧. Troverai i goblin e i loro servi al lavoro: mostra loro che l'⟦Horde=Orda⟧ non permetterà lo sfruttamento di ⟦Stonetalon=Petrartiglio⟧. Mostraglielo nella lingua che capiscono meglio...\n\nLa violenza.", "La ⟦Greatwood Vale=Valle Grandalbero⟧ si trova a nord-ovest, {name}. Va'. Semina il terrore tra chi vorrebbe saccheggiare questa terra!", "Hai agito con coraggio, {name}.\n\nAlla fine potremmo aver bisogno della saggezza degli anziani tauren per placare gli spiriti di ⟦Stonetalon=Petrartiglio⟧, ma...\n\nPrivare la ⟦Venture Company=S.P.R. & Co.⟧ del suo personale è una buona prima mossa contro di loro.", 0x644d74b8, 0x3cf1a755, 0x1fcadd3c, 0xc7a094ee, 0x3bf2b616, "....." },
  [1063] = { "La vecchia megera", "Parla con Magatha a ⟦Thunder Bluff=Picco del Tuono⟧.", "Per prenderci davvero cura degli spiriti di ⟦Stonetalon=Petrartiglio⟧ dobbiamo consultare gli anziani tauren.\n\nNon conosco i nomi di molti dei loro capi, ma di una ho sentito parlare: Magatha. Ho sentito dire che è molto vecchia e che sa molte cose. Se qualcuno può radunare l'aiuto spirituale dei tauren, è lei.\n\nMagatha risiede nella capitale dei tauren, ⟦Thunder Bluff=Picco del Tuono⟧, sull'⟦Elder Rise=Altura degli Anziani⟧, il picco nord-orientale della città. Parla con Magatha e raccontale del pericolo che minaccia le ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", nil, "Ti porgo il mio saluto. Sei qui in cerca di consiglio?", 0x0ddadd80, 0x5862420f, 0xdb16a13c, nil, 0x64075e6d, "...m." },
  [1064] = { "L'aiuto dei Reietti", "Parla con la speziale Zamah nelle Pools of Vision, a ⟦Thunder Bluff=Picco del Tuono⟧.", "I tauren hanno un legame con la terra, e mi addolora sentire della sorte di Petrartiglio. Ma temo che, per guarire la terra, dobbiamo prima estirpare la malattia che la affligge.\n\nNon è una fortuna, allora, che i Reietti siano nostri alleati? Sanno molto di malattie. Credo che possano aiutarci, e così facendo rafforzeranno la fiducia tra i nostri popoli.\n\nParla con la speziale Zamah. È una studiosa e un'emissaria dei Reietti. La troverai nelle Pools of Vision, sotto l'⟦Spirit Rise=Altura degli Spiriti⟧.", nil, "Magatha mi ha annunciato il tuo arrivo, {name}. Anche se il mio cuore non batte più, provo ancora dolore per gli spiriti di ⟦Stonetalon=Petrartiglio⟧.\n\nNoi Reietti siamo ansiosi di offrire tutto l'aiuto possibile.", 0x17b128b1, 0x5e69b8a1, 0x592f2fc1, nil, 0x577f8df2, "...m." },
  [1065] = { "Viaggio al ⟦Tarren Mill=Mulino di Tarren⟧", "Porta l'⟦Zamah's Note=Appunto di Zamah⟧ allo speziale Lydon, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Per liberare ⟦Stonetalon=Petrartiglio⟧ dalla ⟦Venture Company=S.P.R. & Co.⟧ dobbiamo ricorrere a misure estreme. Estreme, ma senza spargimento di sangue.\n\nUn mio collega potrebbe avere proprio lo strumento che ci serve. Si chiama Lydon e vive nel villaggio del ⟦Tarren Mill=Mulino di Tarren⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, nella lontana terra di Lordaeron.\n\nPer raggiungere ⟦Hillsbrad=Colletorto⟧, prendi lo zeppelin fino alla nostra capitale, ⟦Undercity=Sepulcra⟧. Poi va' a nord fino alle ⟦Tirisfal Glades=Radure di Tirisfal⟧, a sud-ovest fino a ⟦Silverpine=Pinargento⟧ e a sud fino a ⟦Hillsbrad=Colletorto⟧.\n\nCerca Lydon e portagli questo appunto. Gli spiega nei dettagli ciò che ci serve.", "Ah, sei qui con le mie nuove cavie?", "Un appunto di Zamah? Le sue necessità devono essere grandi, se scrive da così lontano. Vediamo cosa dice...\n\nAh, splendido! So esattamente cosa fare!", 0x2c58c31f, 0x813d4940, 0x672cefbb, 0x377d5a13, 0x60e2ce21, "....." },
  [1066] = { "Sangue di innocenti", "Porta 5 Fiala di Sangue Innocente allo speziale Lydon, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Creerò una tossina che prosciughi la ⟦Venture Company=S.P.R. & Co.⟧ della sua violenza, rendendo i suoi uomini deboli e docili. Questo dovrebbe risolvere il problema dell'Orda a ⟦Stonetalon=Petrartiglio⟧, no?\n\nMa per creare la tossina mi servirà il sangue di innocenti, un ingrediente difficile da procurarsi.\n\nPer fortuna la ⟦Syndicate=Lega dei Tagliagole⟧, una banda di briganti umani di questa zona, impiega maghi dell'ombra... e quei maghi raccolgono sangue innocente per i loro scopi poco raccomandabili.\n\nTroverai i maghi dell'ombra della ⟦Syndicate=Lega dei Tagliagole⟧ a ⟦Durnholde Keep=Forte Durnholde⟧, a sud-est.", "Hai trovato i maghi dell'ombra della ⟦Syndicate=Lega dei Tagliagole⟧ e hai preso loro il sangue?", "Molto bene! Immagino che la ⟦Syndicate=Lega dei Tagliagole⟧ non ti abbia dato troppi problemi?\n\nCome ti ho detto, il sangue di innocenti non è facile da procurarsi. Siamo fortunati che i maghi dell'ombra della ⟦Syndicate=Lega dei Tagliagole⟧ abbiano fatto il lavoro difficile per noi.\n\nOra aspetta un momento mentre preparo il mio intruglio...", 0x99926917, 0x85aef9f0, 0x6a790f80, 0x2f61455a, 0x43a8a3bb, "....." },
  [1067] = { "Ritorno a ⟦Thunder Bluff=Picco del Tuono⟧", "Porta la ⟦Lydon's Toxin=Tossina di Lydon⟧ alla speziale Zamah, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ecco la tossina. Se la userai contro la ⟦Venture Company=S.P.R. & Co.⟧ dovrebbe produrre risultati favorevoli, forse perfino contagiosi. Devo dire che è piuttosto emozionante vedere il mio lavoro applicato sul campo!\n\nMa prima di usarla, portala alla speziale Zamah. Deve trovare un modo per diffondere la tossina e massimizzarne l'effetto.", "Sei tornat<o/a>, {name}. Porti aiuto dallo speziale Lydon?", "Una tossina dello speziale Lydon? Molto bene. Se conosco Lydon, questa tossina sarà piuttosto efficace contro la ⟦Venture Company=S.P.R. & Co.⟧..", 0xb5d4ecc4, 0x34181589, 0x0f57607d, 0xac7d03bb, 0x301885a4, "....." },
  [1068] = { "Macchine trituratrici", "Distruggi i segatronchi XT:4 e XT:9, poi torna da Seereth Stonebreak al confine tra le ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ e le ⟦Barrens=Savane⟧.", "C'è un legame tra la magia spirituale degli sciamani e la magia naturale dei druidi. È per questo che noi sciamani possiamo udire la supplica degli spiriti di ⟦Stonetalon=Petrartiglio⟧. Molti dei loro sussurri mi sfuggono, ma un messaggio, una visione, è chiaro...\n\nHo visto in visione due macchine dalla forma umana nella ⟦Windshear Crag=Landa di Tagliavento⟧, a nord-ovest della ⟦Greatwood Vale=Valle Grandalbero⟧, che abbattevano alberi con una velocità impossibile. Queste bestie di metallo vanno fermate!\n\nNella mia visione, le macchine erano segnate da strani simboli:\n\nXT:4 e XT:9.", "Gli spiriti degli alberi piangono la perdita dei loro fratelli, {name}. Devi distruggere i segatronchi XT:4 e XT:9, o temo che ⟦Stonetalon=Petrartiglio⟧ non guarirà mai.", "La distruzione delle macchine XT:4 e XT:9 ha placato molti degli spiriti di ⟦Stonetalon=Petrartiglio⟧, {name}. Con la loro perdita, speriamo che la ⟦Venture Company=S.P.R. & Co.⟧ se ne vada da queste montagne.\n\nPerché, se non lo farà, temo che le atrocità subite da questo luogo impallidiranno di fronte a ciò che ci attende.", 0x2ad62d6a, 0xa1ab4fd0, 0xd582b30c, 0xf176340a, 0x8d125b87, "....." },
  [1069] = { "Uova di ragno di Muschiofondo", "Porta 15 Uova di Muschiofondo a Mebok Mizzyrix, a ⟦Ratchet=Porto Paranco⟧.", "Le frittate di uova di ragno sono la nuova moda alla ⟦Booty Bay=Baia del Bottino⟧! Il problema è che... alla ⟦Booty Bay=Baia del Bottino⟧ le uova non ci sono.\n\nSento odore di affari!\n\nNella ⟦Windshear Crag=Landa di Tagliavento⟧ e nel ⟦Sishir Canyon=Canyon di Sishir⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ a nord-ovest, vive il ragno di Muschiofondo. Portami le sue uova e ti pagherò un bel gruzzolo!\n\nNella ⟦Windshear Crag=Landa di Tagliavento⟧ le uova sono ammucchiate sotto quei pochi alberi rimasti.\n\nNel ⟦Sishir Canyon=Canyon di Sishir⟧... be', se hai lo stomaco debole forse faresti meglio a raccogliere le uova nella ⟦Windshear Crag=Landa di Tagliavento⟧...", "Hai preso le uova, {name}? Ho già fatto un accordo per la spedizione con il capomolo Dizzywig!", "Le hai prese! Grazie!\n\nLe farò mandare a Dizzywig e spedire alla ⟦Booty Bay=Baia del Bottino⟧. Sento già il sapore dei profitti!\n\nEcco la tua parte, {name}. Non avrei potuto concludere questo affare senza di te.", 0x14d2d688, 0xf245c60e, 0x270b2709, 0x883bef30, 0x74f54230, "....." },
  [1070] = { "Di guardia a ⟦Stonetalon=Petrartiglio⟧", "Trova Kaela Shadowspear, che sorveglia la valle d'ingresso alla ⟦Windshear Crag=Landa di Tagliavento⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "Ciao, {name}.\n\nA guardarti, sembri pien<o/a> di voglia di viaggiare. Sei mai stat<o/a> nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧? È una terra afflitta dalla S.P.R. & Co. e da altri nemici degli elfi della notte.\n\nDi recente la sentinella Wolfrunner ci ha mandato la mia amica Kaela Shadowspear a indagare su ciò che sta accadendo alla terra, ma non ho ancora avuto sue notizie. Mi preoccupa ancora di più il fatto che l'⟦Alliance=Alleanza⟧ abbia mandato con lei un mago gnomo... un segno sicuro di guai.\n\nPotresti trovarla e tornare a riferirmi?", nil, "Ah, vieni da ⟦Ashenvale=Valtetra⟧ su richiesta di Tara... quanto mi mancano lei, la mia terra e i miei amici. Deve cavarsela bene con le ⟦Sentinels=Sentinelle⟧, se recluta avventurieri per altri compiti. Sono fiera di lei.\n\nÈ un piacere conoscerti, {name}.", 0xf1b5310d, 0x9ed94a98, 0xee657ad7, nil, 0x44b73423, "...m." },
  [1071] = { "La tregua di uno gnomo", "Uccidi 10 Venture Co. Logger e 10 Venture Co. Deforester e torna da Gaxim Rustfizzle a ⟦Stonetalon=Petrartiglio⟧.", "Vedi, {name}, sono membro della Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, e il mio obiettivo... anzi, il mio DOVERE! è dimostrare agli elfi della notte che un misto di magia, miscele e meccanismi può aiutare a salvare le loro foreste.\n\nMa è una guerra dura, e a quanto pare i goblin si riproducono come conigli. Non ho avuto nemmeno il tempo di costruire le mie ultime invenzioni!\n\nMi serve tempo per pianificare e organizzarmi. Ma per farlo ho bisogno del tuo aiuto per tenere a bada i goblin nella ⟦Windshear Crag=Landa di Tagliavento⟧, a est...", "Come va la battaglia dalle tue parti, {name}?", "Grazie davvero per il tuo aiuto, {name}. Anzi, sei tornat<o/a> giusto in tempo.\n\nCredo di avere un piano perfetto... esplosivi. No, il piano non è quello, ma ne fa parte.\n\nVedi, ho usato esplosivi ad alto potenziale (non preoccuparti, non sono pericolosi come pensano tutti) per spaventare un po' i goblin e farli indietreggiare. Riesco a radunarli piuttosto bene con qualche detonazione mirata lungo i bordi delle montagne, ma da qualche giorno sono a corto di scorte...", 0x81885f31, 0x39875a59, 0x4f827ebf, 0x8ed33a78, 0x1460c1f4, "....." },
  [1072] = { "Un vecchio collega", "Parla con Lomac Gearstrip a ⟦Ironforge=Forgiardente⟧.", "Il congegno a cui sto pensando è la mia versione più avanzata finora. Ma per farlo funzionare ci servirà una pozione speciale. Già che ci siamo, tanto vale procurarci la roba buona, visto che questa missione potrebbe essere la tua ultima.\n\nE per questo ci serviranno degli esplosivi potenti: il Nitromirglyceronium.\n\nL'unico che sa preparare l'NG-5 è un mio vecchio amico: Lomac Gearstrip. Cercalo a Tinker Town.\n\nTu convincilo a prepararci un po' di NG-5, e io intanto mi metto al lavoro sul posizionamento dei miei congegni.", nil, "Ahhh... ti manda Gaxim, eh? Come faccio a sapere che non mi stai mentendo?! Eh? Eh...?", 0xad49e719, 0xa710c50b, 0x2f2357b3, nil, 0xcaefb60e, "...m." },
  [1073] = { "Incompetenza + chimica = divertimento", "Porta 4 Minor Mana Potion e 2 Elixir of Minor Fortitude a Lomac Gearstrip a ⟦Ironforge=Forgiardente⟧.", "Ahahah... ti serve il Nitromirglyceronium per impedire ai goblin di distruggere una foresta?!\n\nNon m'importa se conosci Gaxim o no... ti darò la roba solo per vedere te o loro saltare in aria in tanti pezzettini.\n\nC'è però un problema: l'ho finita.\n\nMa facciamo così: tu mi porti le pozioni giuste e io te ne preparo un po' all'istante.\n\nIl minimo che puoi fare è dimostrare di avere un po' di abilità come alchimista, prima che ti dia un campione della mia più grande creazione.", "Non posso fare il Nitromirglyceronium se non ho le pozioni... sono essenziali per prepararlo.", "Questo andrà benissimo.\n\nSe non sapessi come stanno le cose, <straniero/straniera>, direi che di alchimia te ne intendi. Bene, bene... il mondo non è fatto solo di spade e stregonerie, sai?", 0x5ce18882, 0xed8cfce0, 0x0bf71576, 0x36a2a5fb, 0x7db747d1, "....." },
  [1074] = { "Incompetenza + chimica = divertimento", "Riporta il Nitromirglyceronium a Gaxim Rustfizzle a ⟦Stonetalon=Petrartiglio⟧.", "Ecco qua, <straniero/straniera>. Però fai attenzione... è roba instabile.\n\nSe Gaxim è davvero tuo amico, salutamelo. Se non lo è, divertiti a farti saltare in aria.", "Ah, benissimo, benissimo, sei tornat<o/a>.", "Hai svolto il tuo compito in modo impeccabile, {name}.\n\nL'NG-5 è il componente indispensabile della ricetta per far saltare i carri di dinamite.\n\nCome? Sì, dinamite... carri interi. È la distrazione perfetta, te lo dico io... aspetta e vedrai.", 0x5ce18882, 0xced1e491, 0xa98e7a8f, 0x3742a9e2, 0x1ee3952b, "....." },
  [1075] = { "Una pergamena da Mauren", "Trova Collin Mauren a ⟦Stormwind=Roccavento⟧.", "Bene, ora passiamo alla parte del mio piano sulla detonazione a distanza... ah, non te l'ho ancora spiegata, vero?\n\nDunque, in breve è così: con un po' di magia posso far esplodere gli esplosivi mentre tu non sei nei paraggi. Sto assemblando un congegno che ti permetterà di premere un solo pulsante e far esplodere l'NG-5 quando sei pront<o/a>.\n\nMa mi serve un incantesimo da un amico di ⟦Stormwind=Roccavento⟧: si chiama Collin Mauren. Lo trovi nel Quartiere dei Maghi. È umano, quindi non dovrebbe essere difficile notarlo.", nil, "Dunque, questo incantesimo che ti serve: un incantesimo che ti permetta di far detonare esplosivi a distanza... mmh.", 0x58c40a09, 0x1b3699f4, 0xf43ca5a0, nil, 0x723899cb, "...m." },
  [1076] = { "Diavoli nelle ⟦Westfall=Marche Occidentali⟧", "Porta i ⟦Dust Devil Debris=Resti del Diavolo di Sabbia⟧ a Collin Mauren a ⟦Stormwind=Roccavento⟧.", "Ah, credo di aver capito. Un incantesimo di messaggistica... credo sia proprio l'effetto che cerca.\n\nDovrò creare una pergamena con l'incantesimo impresso sopra. Per farlo mi servono i resti di un diavolo di sabbia.\n\nMentre raccolgo il resto dei componenti, perché non vai nelle ⟦Westfall=Marche Occidentali⟧ a cercare una di quelle creature immonde? Sono pericolose, ma sono certo che non sia niente che tu non possa affrontare, se sei dispost<o/a> a sottoporti a uno degli esperimenti di Gaxim.\n\nSarò qui quando tornerai.", "Ciao, {name}. Hai trovato il componente che mi serve?", "Concedimi solo qualche istante e la tua pergamena sarà pronta.", 0xf0e28ebb, 0x2aa2e96c, 0x3e02eba9, 0x7f60f7de, 0x19cadc30, "....." },
  [1077] = { "Consegna speciale per Gaxim", "Porta la ⟦Scroll of Messaging=Pergamena Scritta⟧ a Gaxim Rustfizzle a ⟦Stonetalon=Petrartiglio⟧.", "Eccoti, {name}. Questo dovrebbe andare benissimo.\n\nPorta i miei saluti a Gaxim la prossima volta che lo vedi. Non vedo l'ora di sentire il racconto di questa avventura quando sarà conclusa.\n\nStammi bene.", "Ahah! Sei tornat<o/a>! Ce l'hai? Hai l'incantesimo?", "È perfetta, {name}! Ben fatto.\n\nQuesto incantesimo, unito all'NG-5, creerà l'esplosivo a distanza perfetto.\n\nPotremo creare la distrazione perfetta per permetterti di intrufolarti e rubare le lettere e i progetti tecnici della S.P.R. & Co.\n\nQuesto rallenterà di sicuro il loro disboscamento.", 0xd1462095, 0x51ae1c5d, 0x1b8d59b2, 0xdd1faf10, 0xbe0ac519, "....." },
  [1078] = { "Un recupero per Mauren", "Porta 8 Crystalized Scales a Collin Mauren, a ⟦Stormwind=Roccavento⟧.", "I viaggiatori continuano a chiedermi delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧. Pare sia un posto molto popolare per le avventure, che tu cerchi viverne, elementali o abbia affari con la S.P.R. & Co.\n\nNella ⟦Charred Vale=Valle Bruciata⟧, nel cuore di ⟦Stonetalon=Petrartiglio⟧, viveva una specie di basilischi le cui scaglie, ridotte in polvere, erano un reagente meraviglioso per alcuni incantesimi che ho creato.\n\nSe quei basilischi vivono ancora, mi piacerebbe molto avere qualcuna delle loro scaglie.\n\nFa' con calma, non c'è fretta, ma posso pagare bene.", "Salve di nuovo, {name}.\n\nSei già tornat<o/a> dalla Valle, a ⟦Stonetalon=Petrartiglio⟧, con quelle scaglie?", "È perfetto, {name}. Grazie infinite.\n\nForse un giorno potrò aiutarti come tu hai aiutato me.", 0xf7d838e2, 0x2360a1f8, 0xc942697b, 0x291f5038, 0xdba69ed3, "....." },
  [1079] = { "Operazioni segrete - Alpha", "Recupera i Piani di Ingegneria della S.P.R. & Co. dalla segheria nella ⟦Windshear Crag=Landa di Tagliavento⟧.", "Ci siamo, {name}. Ascolta bene. I congegni sono finiti e pronti all'uso.\n\nPrendi queste pagine: ti spiegheranno meglio i detonatori e gli esplosivi, e dove devi piazzarli.\n\nRicorda: il successo della tua missione non dipende da quanta distruzione causi. Il successo del Piano Alpha dipende dal fatto che tu riporti i piani di ingegneria della S.P.R. & Co. dall'interno della segheria a sud del ⟦Cragpool Lake=Lago di Altarupe⟧.", "Hai preso i piani, {name}?", "Davvero sbalorditivo! È un colpo durissimo per la S.P.R. & Co.\n\nPotremo trovare i punti deboli delle loro macchine e anche incorporare i loro progetti nelle nostre creazioni. È davvero una giornata meravigliosa.", 0x67625d6d, 0xdbfd5680, 0x4c8cfe7c, 0x7e92c08b, 0xf3532bc5, "....." },
  [1080] = { "Operazioni segrete - Beta", "Recupera le ⟦Venture Co. Letters=Lettere della S.P.R. & Co.⟧ dalla ⟦Windshear Mine=Miniera di Tagliavento⟧, all'estremità orientale della ⟦Windshear Crag=Landa di Tagliavento⟧.", "Il Piano Beta è proprio come il Piano Alpha, {name}.\n\nCreiamo un diversivo e poi rubiamo le loro preziose lettere.\n\nLa cosa fondamentale è prendere le lettere... ricordatelo.\n\nLe pagine che ti ho già dato ti diranno dove piazzare gli esplosivi. Tu torna qui <vivo/viva> e con quelle lettere...", "Com'è andata, {name}?", "Incredibile, {name}! Kaela e le ⟦Sentinels=Sentinelle⟧ saranno felicissime. Con la tua abilità e le mie creazioni, siamo inarrestabili.", 0x435bdad7, 0xaaab2588, 0xd5c09f15, 0x30cd8aea, 0xea15a34a, "....." },
  [1081] = { "Udienza con Tyrande", "Trova Tyrande Whisperwind a Darnassus.", "{name}, di certo Tyrande Whisperwind in persona vorrà ringraziarti per aver preso parte a questa missione.\n\nIn superficie potrebbe non sembrare, ma ciò che hai contribuito ad avviare potrebbe davvero rafforzare la nostra posizione nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.\n\nSe ti consideri nostr<o/a> alleat<o/a> contro queste atrocità, va' da Tyrande nel ⟦Temple of the Moon=Tempio della Luna⟧, a Darnassus.", nil, "Salve, {name}. Ho già sentito il tuo nome e, anche se sei ancora nel fiore della giovinezza, mi fa piacere vedere il cammino che hai scelto.\n\nMi faresti un grande onore se accettassi questo come dono di riconoscenza.", 0x2ecc6a2b, 0xbb227158, 0x02acff07, nil, 0x42a56151, "...m." },
  [1082] = { "Notizie per la sentinella Thenysil", "Torna dalla sentinella Thenysil a ⟦Ashenvale=Valtetra⟧.", "{name}, hai fatto una gran cosa dandoci una mano qui.\n\nLe ⟦Sentinels=Sentinelle⟧ di ⟦Ashenvale=Valtetra⟧ ti ricompenseranno bene se farai sapere loro che Gaxim e io siamo vivi. Di' loro che siamo sulla buona strada per fermare la S.P.R. & Co. e risanare queste terre.\n\nCerca Tara Thenysil ad Astranaar: sarà felice di vederti tornare con buone notizie.", nil, "Grazie, {name}. Hai reso un servizio alle ⟦Sentinels=Sentinelle⟧.\n\nSono lieta di sapere che Kaela... e persino Gaxim stanno bene.\n\nTi sei <guadagnato/guadagnata> la nostra riconoscenza.", 0x8cbe9e1c, 0xa02009ab, 0x0efa59cf, nil, 0xb214a8e6, "...m." },
  [1083] = { "Spiriti infuriati", "Prendi 8 ⟦Smoldering Embers=Braci Infuocate⟧ dagli elementali del fuoco della ⟦Charred Vale=Valle Bruciata⟧ e portale a Kaela Shadowspear, a ⟦Stonetalon=Petrartiglio⟧.", "Non so bene cosa abbia fatto la S.P.R. & Co. alla Valle, ma è evidente che le creature del posto hanno avuto la meglio.\n\nHanno dato fuoco alla foresta e usato le loro invenzioni distruttive per devastare quanta più Valle possibile.\n\nMa nella loro ignoranza hanno liberato anche qualcos'altro: spiriti ardenti, elementali di fiamma, pietra e furia.\n\nLa terra non potrà vedere il sorriso di Elune finché queste creature saranno libere.\n\nPortami le loro braci infuocate per dimostrare di averne ridotto il numero.", "La prima volta che ho visto la ⟦Charred Vale=Valle Bruciata⟧ per poco non ho pianto, {name}.", "I resti del nostro nemico... la tua forza ci è preziosa, {name}. Grazie.", 0x541e782d, 0x32646144, 0x91e83ed1, 0x4ab60f8c, 0x584d2d40, "....." },
  [1084] = { "Antichi feriti", "Porta un pezzo di ⟦Corroded Shrapnel=Granata Corrosa⟧ a Kaela Shadowspear, a ⟦Stonetalon=Petrartiglio⟧.", "Per me è evidente che i protettori della Valle, i treant, abbiano avuto a che fare con la ritirata della S.P.R. & Co. Purtroppo anche quei guardiani, un tempo grandiosi, ora sono corrotti.\n\nGaxim pensa che la loro corruzione sia in qualche modo legata alle armi usate dai goblin durante la ritirata.\n\nGli ho detto che avrei raccolto un campione da un treant ferito, così che potesse studiarlo e capire se è vero.\n\nPortami un po' di quelle schegge, così lo gnomo potrà dirmi di più...", "Ho la sensazione che Gaxim troverà un uso per quelle schegge, a prescindere da come le abbia usate la S.P.R. & Co. in passato.", "Grazie, {name}.\n\nQuesto dovrebbe bastare e avanzare a Gaxim per capire come sono stati corrotti i treant. Glielo porterò subito.", 0x00a0d96c, 0x41c21b98, 0x08fc2949, 0x1516aa6d, 0x95a6d4f4, "....." },
  [1085] = { "Di guardia a ⟦Stonetalon=Petrartiglio⟧", "Parla con Gaxim.", "La situazione qui a ⟦Stonetalon=Petrartiglio⟧ dev'essere davvero grave, se un'elfa della notte e uno gnomo lavorano insieme.\n\nLa S.P.R. & Co. ha devastato queste terre, e ho passato gran parte del mio tempo a porre fine alla distruzione.\n\nNon giudicare Gaxim troppo in fretta: capisce che dobbiamo lavorare insieme.\n\nSe vuoi aiutarci, comincia parlando con Gaxim.\n\nMi dispiace di non poterti ancora rimandare da Tara con buone notizie. Forse presto.", nil, "Insidiosa... insidiosa e pericolosa, ecco cos'è questa terra.\n\nMa sono qui per dimostrare agli elfi della notte che è un po' più sicura con l'aiuto della buona vecchia ingegneria e di un pizzico di magia.\n\nVedi, rinunciare del tutto alla magia non aiuterà gli elfi della notte: ne hanno bisogno. Il mondo ne ha bisogno. E se ci aggiungi ingegneria e alchimia, non puoi sbagliare. Le possibilità sono infinite.", 0xf1b5310d, 0x404858ae, 0xf9b6af40, nil, 0x80f212a2, "...m." },
  [1086] = { "L'aeroporto delle macchine volanti", "Porta il ⟦Toxic Fogger=Nebulizzatore Tossico⟧ allo scalo aereo della S.P.R. & Co., poi torna dalla speziale Zamah.", "La tossina è pronta. Resta solo da consegnarla. Tu, {name}, dovrai occuparti della consegna.\n\nLa ⟦Venture Company=S.P.R. & Co.⟧ deve avere un modo per inviare messaggi e piccoli carichi tra il suo quartier generale e le sue operazioni a ⟦Stonetalon=Petrartiglio⟧. Probabilmente si tratta di un piccolo scalo aereo: non abbastanza grande per uno zeppelin, ma forse per una macchina volante. Devi perlustrare le zone di ⟦Stonetalon=Petrartiglio⟧ controllate dalla ⟦Venture Company=S.P.R. & Co.⟧ e trovare questo scalo, se esiste. Se lo trovi, piazzaci la tossina.\n\nPiazzala, e scappa.", "Devi trovare l'aeroporto della ⟦Venture Company=S.P.R. & Co.⟧, se esiste, {name}.", "Hai trovato lo scalo? Ben fatto, {name}! Sono sicura che i goblin siano rimasti piuttosto sorpresi dalla tua consegna! Speriamo che la tossina arrivi fino al loro quartier generale.\n\nHai servito bene la tua gente, e ti consiglio di ignorare qualunque senso di colpa tu possa provare per aver avvelenato la ⟦Venture Company=S.P.R. & Co.⟧ Meritano molto di peggio.\n\nE se c'è un briciolo di saggezza che i Reietti possono insegnare ai loro alleati, è questo:\n\nNon evitare le vie oscure... se quelle vie portano alla vittoria.", 0x081eaf2b, 0x0f1268ec, 0xf51ce998, 0x3c03c943, 0x4e325c2a, "....." },
  [1087] = { "L'eredità di Cenarius", "Uccidi 4 Son of Cenarius, 4 Daughter of Cenarius e 4 Cenarion Botanist per conto di Braelyn Firehand, vicino al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", "Non puoi immaginare quanto odio questa terra miserabile. La progenie di Cenarius e i druidi kaldorei sulla vetta usano i loro patetici poteri per soffocare il flusso della magia, persino così a sud dei loro patetici domini... le loro amate foreste.\n\nVorrei tanto tornare a Jaedenar ed esultare nel flusso della magia, ma il mio padrone non me lo permetterà finché il mio lavoro non sarà compiuto.\n\nNon ho dubbi che tu ami gli Elfi della Notte e i loro alleati quanto me, cioè poco. Aiutami, e potremo raggiungere entrambi i nostri scopi.", "Qui, incanalare la magia è come attingere acqua da un pozzo con un secchio pieno di buchi.", "Già lo sento... sì... un potere così dolce... il flusso impetuoso. I kaldorei sono stolti a disprezzare i doni di questo mondo, a rifiutare la magia che scorre cantando nelle vene.\n\nChe pallida parodia è la vita senza il suo abbraccio ardente!", 0xed1982a5, 0xbcbb0b9b, 0x1af6bead, 0x47aaba26, 0x59ff2e1e, "....." },
  [1088] = { nil, "Porta la testa di Ordanus a Braelyn Firehand, vicino al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", "Pensavano di poter fermare il flusso della magia. Si sbagliavano. Pensavano di poter nascondere Ordanus, ma io avrò la sua testa!\n\nLa magia mi concede la vera vista. Sì... eccolo. Un crocevia... In cima a un grande albero nella foresta di ⟦Ashenvale=Valtetra⟧. Un nome... Legnovivo. Uno dei figli più antichi del dio della foresta. L'hanno portato via dal picco prima che potessi trovarlo, ma il suo tempo sta per scadere.\n\nPortamela e condividerò con te un dono potente.", "Quando il mio padrone mi ordinò di recarmi sul Picco di ⟦Stonetalon=Petrartiglio⟧, pensavo che mi sarebbe bastato fare strage degli elfi della notte che strisciavano tra le sacre rovine del nostro antico tempio di Azshara, profanandone la santità con il loro tocco... ma Ordanus mi era sfuggito.", "Conoscevo Ordanus, molto tempo fa. Aveva l'arroganza della sua specie e si riteneva superiore perfino agli ⟦Highborne=Alti Nobili⟧.\n\nOra la sua testa non sta più così in alto, vero, {name}?\n\nTi ho promesso una ricompensa, e l'avrai. Ascoltami.", 0xac86867a, 0xf081772c, 0x3c3cbd54, 0x28ec0d86, 0x664423d0, "e...." },
  [1089] = { nil, "Raggiungi l'Eremo Grinfialunga sul ⟦Stonetalon Peak=Picco di Petrartiglio⟧. Con la ⟦Gatekeeper's Key=Chiave del Custode del Portale⟧, recupera gli oggetti nascosti dei druidi. Usali per aprire il Talon Den Hoard.", "I druidi hanno costruito l'Eremo Grinfialunga sul ⟦Stonetalon Peak=Picco di Petrartiglio⟧, dove custodiscono molti oggetti potenti.\n\nHanno escogitato un piano complesso per evitare che finiscano nelle mani sbagliate.\n\nPer fortuna ho potuto... estorcere qualche dettaglio a uno di loro.\n\nNascosta in una piccola lanterna all'ingresso dell'Eremo troverai la ⟦Gatekeeper's Key=Chiave del Custode del Portale⟧: con essa potrai aprire i nascondigli sparsi per l'Eremo. Gli oggetti di quei nascondigli ti permetteranno di aprire il loro tesoro, che si trova in una delle zone centrali.", "Nella pietra sono incise tre serrature.", "Mentre le tre chiavi scivolano nelle rispettive aperture, al centro della luce scintillante appaiono alcuni oggetti.", 0x69a60aaa, 0x32a26601, 0x5799a343, 0x17c59583, 0x5dc68227, "e...." },
  [1090] = { "Gli ordini di Gerenzo", "Prendi il misterioso minerale da Piznik quando avrà finito di estrarlo.", "Sai, un tempo ero la seconda persona più importante di questo cantiere. Tutto è cambiato quando è arrivato Gerenzo. Ha licenziato il mio capo, Ziz Fizziks, e ha spedito me a lavorare in miniera. Però Ziz mi ha detto di restare qui a raccogliere informazioni. Il suo nuovo capo ci pagherà bene se riusciamo a scoprire quali sono i piani di Gerenzo.\n\nComunque, quello che so è che Gerenzo ha ordinato di estrarre grandi quantità di questo minerale verde oro. Posso procurarti un campione da portare a Ziz, ma dovrai tenere d'occhio le pattuglie mentre lo prendo.", nil, "Grazie, {name}. Per un attimo le cose si erano messe male, e probabilmente abbiamo attirato fin troppa attenzione su di noi.\n\nL'importante, però, è che abbiamo il campione di minerale, e dovremmo portarlo a Ziz il prima possibile.", 0xce6824bd, 0x17fb1d28, 0x30d3cff4, nil, 0x96af83cc, "...m." },
  [1091] = { "Il rapporto di Kaela", "Porta le ⟦Venture Co. Letters=Lettere della S.P.R. & Co.⟧ a Kaela Shadowspear.", "{name}, porta queste lettere a Kaela. Sono sicuro che vorrà saperlo. O almeno lo vorranno le ⟦Sentinels=Sentinelle⟧.\n\nAssicurati di dirle quanto è andata bene e che non ce l'avremmo fatta senza un pizzico di magia.", "Sì, {name}? Cosa posso fare per te?", "È davvero interessante.\n\nTu e Gaxim avete fatto un ottimo lavoro, {name}. Grazie.", 0x2303e574, 0x88de288b, 0xcc598924, 0x1573cda6, 0xcb79207d, "....." },
  [1092] = { "Gli ordini di Gerenzo", "Consegna il ⟦Unidentified Ore=Minerale Sconosciuto⟧ a Ziz Fizziks nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "Credo che farei meglio a pensare a filarmela anch'io. Non ci vorrà molto perché la notizia di quanto è successo qui arrivi ai piani alti, e di sicuro non sarebbero contenti di rivedermi.\n\nSgattaiolerò via e raggiungerò Ziz. Speriamo che riesca a trovarmi un nuovo lavoro!\n\nCercherò di sistemare un po' questo disastro, ma tu dovresti portare subito il campione di minerale a Ziz. Mi ha detto che si sarebbe accampato da qualche parte sul lato occidentale della ⟦Windshear Crag=Landa di Tagliavento⟧. Buona fortuna.", "Posso aiutarti in qualcosa?", "Ahhh, sapevo di aver fatto bene a dire a Piznik di restare indietro. Sono sicuro che gli ingegneri di Undermine saranno molto interessati a esaminarlo...\n\nOvviamente vorrò tenerne un pezzetto per me, ma occhio non vede, cuore non duole, giusto?", 0xce6824bd, 0x5ff378be, 0xe65a92f9, 0xdf112bb5, 0x1883fb16, "....." },
  [1093] = { "Super Mietitore 6000", "Procurati i ⟦Super Reaper 6000 Blueprints=Progetti del Super Mietitore 6000⟧ per Ziz Fizziks, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "Terribile quello che la ⟦Venture Company=S.P.R. & Co.⟧ ha fatto qui, eh? Cosa gli è passato per la testa? Una compagnia goblin che assume uno gnomo!\n\nPer mia fortuna, Sputtervalve riconosce un genio quando lo vede. Mi ha assunto subito dopo che mi avevano cacciato!\n\nMi dice che hanno costruito un'enorme macchina taglialegna, e Sput' vuole che gli rubi i progetti. Purtroppo Gerenzo, quel maledetto gnomo, mi vuole morto appena mi vede... forse potresti rubarli tu i progetti per me? Dovresti trovarli addosso a uno dei loro operatori.", "Hai trovato quei progetti? Non vedo l'ora di fare colpo sul nuovo capo. Spero che, una volta convinto della mia lealtà (be', per quanto lo si possa convincere... parola di goblin, capisci?), si sentirà a suo agio nello sfruttare il mio genio piuttosto notevole.", "Ehi, è quello che penso? Fantastico!\n\nVediamo un po'. Uff... come dovrei capirci qualcosa in questa roba... non riesco a capire come ragionano gli gnomi. Te lo dico io, mi sorprende che siano riusciti a inventare la ruota, figuriamoci quelle macchine volanti che gli piacciono tanto.", 0xfe7b3d9f, 0xfe2d59bd, 0xad532ea7, 0x7a6f86e7, 0x7531d6d0, "....." },
  [1094] = { "Nuove istruzioni", "Consegna la ⟦Sealed Envelope=Busta Sigillata⟧ a Sputtervalve, nelle ⟦Barrens=Savane⟧.", "Questa busta contiene tutte le informazioni che sono riuscito ad arraffare mentre mi sbattevano fuori dalla porta... documenti interni della ⟦Venture Company=S.P.R. & Co.⟧, qualche manuale, roba tecnica... Ah, e ovviamente i progetti del Super Mietitore 6000.\n\nSputtervalve si è stabilito a ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧. Non dovresti avere problemi a trovarlo: è un tipetto verde.", "Salve! Come posso aiutarti?", "Fizziks, eh? Non posso dire di fidarmi di lui, ma queste informazioni sembrano abbastanza buone. Cosa darei per togliermi di torno la ⟦Venture Company=S.P.R. & Co.⟧\n\nPerò qualche buona macchina la tirano fuori... non posso negare che abbiamo tratto vantaggio da alcuni dei miglioramenti che hanno ideato.", 0xd12c0eee, 0xc9ab2557, 0xb0912f98, 0x73864487, 0xd6844379, "....." },
  [1095] = { "Nuove istruzioni", "Porta i nuovi ordini a Ziz Fizziks, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "La faccenda di questo gnomo assoldato dalla ⟦Venture Company=S.P.R. & Co.⟧ ha suscitato un certo scompiglio a Undermine. I principi mercanti non approvano che Razdunk se la faccia con questo Gerenzo.\n\nRiddlevox mi ha chiesto di occuparmi del problema, e sono sicuro che sia stato uno o più principi mercanti a ordinarglielo. Certo, il direttore non me l'ha detto. Diciamo che ho un presentimento.\n\nComunque sia, Gerenzo va tolto di mezzo, e sarebbe una prova adatta far sì che sia Fizziks a occuparsene.", nil, "Eliminare Gerenzo? Ecco una prospettiva a cui non ho nulla da obiettare.\n\nGli gnomi sono già abbastanza insopportabili di loro, ma quello che ho scoperto su Gerenzo peggiora le cose. A quanto pare era uno dei capi ingegneri di Gnomeregan, dove lavorava al loro progetto segreto (non siamo mai riusciti a infiltrarci abbastanza a Dun Morogh da scoprirne i dettagli). Fu un fallimento. Secondo i nostri rapporti, qualunque cosa fosse gli è letteralmente esplosa in faccia.", 0xd12c0eee, 0x4cd21a54, 0x5de65c53, nil, 0x539bf0fe, "...m." },
  [1096] = { nil, "Porta il Gerenzo Wrenchwhistle's Mechanical Arm a Ziz Fizziks, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "Ho incontrato Gerenzo una volta e, credimi, non è un bello spettacolo. La sua carne sembra in putrefazione, e si è innestato metallo e ingranaggi sul corpo, sostituendo alcuni arti con arti meccanici.\n\nA nord-est di qui, molto più in alto del ⟦Cragpool Lake=Lago di Altarupe⟧, vicino alla ruota idraulica: è da lì che Gerenzo sorveglia l'intero sito. Non potrei mai farmi strada fin lassù, figuriamoci affrontare Gerenzo... Ma tu sembri in grado di farcela.\n\nSe lo uccidi per me, ti ricompenserò come si deve!", "Sputtervalve vorrà una qualche prova che Gerenzo è morto. Credo che il suo braccio meccanico possa bastare.", "Guarda quella roba... solo a uno gnomo poteva venire in mente una cosa del genere. Non capisco perché uno dovrebbe tagliarsi un braccio e sostituirlo con quello, quando potrebbe tenersi tutte e due le braccia e aggiungerne un terzo!\n\nGli gnomi, te lo dico io...\n\nAlmeno Gerenzo è fuori gioco. Speriamo che basti come prova, e che Sputtervalve mi assegni a uno dei laboratori della Tinkers' Union a ⟦Gadgetzan=Meccania⟧, o magari persino a Undermine.", 0x896fbf9b, 0xf0c79254, 0x2e6098b0, 0xe15dc320, 0xfc121249, "e...." },
  [1097] = { "L'incarico di Elmore", "Parla con Grimand Elmore.", "C'è un armaiolo nano a ⟦Stormwind=Roccavento⟧, Grimand Elmore, che ha fatto sapere di aver bisogno di aiuto per una consegna. Credo voglia spedire un pacco alla sua terra natale, a nord.\n\nHai un bel paio di gambe robuste! Quindi, se ti va di camminare un po', parla con Grimand. Qui ci saresti utile, ma dobbiamo anche mantenere saldi i legami con i nani.\n\nTroverai Grimand Elmore nella bottega d'armi del Dwarven District di ⟦Stormwind=Roccavento⟧, nella parte nord-orientale della città.", nil, "Sei qui per aiutarmi con la consegna? Molto bene!", 0x30749260, 0x6ac05387, 0xf12b5a6f, nil, 0x7d006a0a, "...m." },
  [1098] = { "⟦Deathstalkers=Inseguitori della Morte⟧ a ⟦Shadowfang=Zannascura⟧", "Trova l'⟦Deathstalker=Inseguitore della Morte⟧ Adamant e l'⟦Deathstalker=Inseguitore della Morte⟧ Vincent.", "In vista di un assalto a ⟦Shadowfang=Zannascura⟧, due ⟦Deathstalkers=Inseguitori della Morte⟧ sono stati mandati al forte a raccogliere informazioni. Sono passati molti giorni e non sono tornati, ma il loro rapporto ci serve, se vogliamo avere qualche speranza di riuscita nell'attacco!\n\nQuindi ecco il tuo compito, {name}. Va' al ⟦Shadowfang Keep=Forte di Zannascura⟧, a sud, e trova gli ⟦Deathstalkers=Inseguitori della Morte⟧ Adamant e Vincent. Trovali e, se hanno bisogno di aiuto, daglielo.\n\nQuesta missione è tanto pericolosa quanto decisiva, {name}. Non fallire.", nil, "Il corpo di Vincent giace spezzato e immobile.\n\nAnche se l'⟦Deathstalker=Inseguitore della Morte⟧ Adamant manderà il suo rapporto a Hadrec... qualunque altro dettaglio Vincent abbia scoperto dovrà restare con lui.\n\nMa nella sua mano stringe un piccolo ninnolo...", 0xf489f723, 0x203b0fd7, 0x8e3dd6ce, nil, 0x7257ca64, "...m." },
  [1099] = { "Vincono i goblin!", nil, nil, nil, nil, 0x5cd506d5, nil, nil, nil, nil, ".mmmm" },
  [1103] = { "Il richiamo dell'acqua", "Se non sei riuscit<o/a> a parlare con la Minor Manifestation of Water, porta un ⟦Water Sapta=Sapta d'Acqua⟧ a Tiev Mordune nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Salute, <fratello/sorella>! Anche tu sei venut<o/a> a purificare le acque qui e a dimostrare a Islen che hai capito?\n\nIo ho appena sconfitto lo spirito dell'acqua corrotto, e stavo giusto pe' mettere i bracciali e le ultime gocce d'acqua sul braciere.\n\nCome dici? Ahhh. Tiev capisce fin troppo bene quando qualcosa va storto. Be', Tiev può aiutarti parecchio se hai bisogno di vedere di nuovo lo spirito dell'acqua pura.\n\nPortami un sapta d'acqua di Islen come prova che sei <pronto/pronta>, e io aspetterò a consegnare la mia roba.", "Ce l'hai il sapta, <fratello/sorella>?\n\nConosco un altro che ha avuto problemi dopo aver sconfitto lo spirito dell'acqua corrotto: pare che abbia aspettato troppo e sia uscito dal mondo degli spiriti troppo presto pe' i suoi gusti. Non vorrei che succedesse a qualcun altro, quindi aspetterò qui ancora un po' per essere sicuro che nessun altro abbia bisogno del mio aiuto.", "Ahhh, allora sei <pronto/pronta>...\n\nMetterò la mia roba nel braciere, allora, e potrai parlare con lo spirito anche tu.\n\nE non preoccuparti pe' niente di vedere nel mondo degli spiriti col sapta... il vecchio Tiev conosce un trucco o due su come funziona la magia del sapta.\n\nSu, vieni giù al santuario con me e parliamo insieme agli spiriti, <fratello/sorella>.", 0x1f0e11aa, 0x672cce87, 0x1e351ce9, 0xec055306, 0x2814faec, ".....", nil, nil, 0x58f5d2d9, 0xff56d459, 0x7c436da4 },
  [1104] = { "Veleno delle Distese Salate", "Porta 6 Salty Scorpid Venom a Fizzle Brassbolts nelle Distese Salate.", "Ho così tanti progetti per la nostra auto a razzo! Così tanti! E devo provarli tutti!!\n\nSto lavorando a un nuovo tipo di carburante. Uno che brucia davvero davvero davvero caldo!! Non ho ancora trovato la miscela perfetta, ma credo di sapere cosa mi serve...\n\nGli scorpidi che girano per le Distese Salate hanno un veleno con tantissimo sale dentro. È unico! Ed è proprio quello che mi serve!\n\nPortami il veleno e fidati: la nostra auto volerà!!", "Ciao ciao ciao! Hai preso quel veleno??", "Evviva! Questo veleno funzionerà alla grande! Grazie, {name}!\n\nOra devo solo farlo bollire per ridurlo, applicare lo skipper-otometro, aggiungere un nega-catalizzatore e... Accidenti! Dove sono i miei appunti!?", 0x79971380, 0x01790f68, 0x8cc37d86, 0x9c48d083, 0x08780fd1, "....." },
  [1105] = { "Gusci induriti", "Porta 9 Hardened Tortoise Shell a Wizzle Brassbolts nelle Distese Salate.", "Mio fratello sta lavorando a un nuovo carburante per la sua auto a razzo. È geniale, davvero. Così geniale che... credo che il nuovo carburante che sta progettando sia abbastanza forte da corrodere il telaio dell'auto da parte a parte!\n\nVoglio rinforzarne i serbatoi prima che succeda.\n\nLe tartarughe là fuori, nelle distese, hanno gusci durissimi. Voglio usarli per costruire nuovi serbatoi per la nostra auto a razzo. Serbatoi che possano contenere il nuovo carburante di mio fratello.\n\nSembri una persona abbastanza responsabile. Mi procuri quei gusci?", "Mio fratello sta facendo progressi con il suo nuovo carburante, e questo mi preoccupa. Devo cominciare a lavorare a un serbatoio di guscio di tartaruga il prima possibile!\n\n{name}, hai già quei gusci?", "Li hai presi! Grazie, {name}!\n\nAccidenti, questi gusci sono più duri di quanto pensassi! Eh, quando ci lavorerò probabilmente piegherò un'intera cassetta di attrezzi!", 0x63fa007a, 0x1e243142, 0x73ecbecf, 0x5543b2ae, 0x8597a885, "....." },
  [1111] = { "Il capo del porto Dizzywig", "Porta l'⟦Kravel's Parts Order=Ordine Pezzi di Kravel⟧ al capo del porto Dizzywig a ⟦Ratchet=Porto Paranco⟧.", "Il mio mestiere è procurare alla gente ciò che le serve, e gli gnomi laggiù devono far evadere un ordine di pezzi. I pezzi sono stati spediti a ⟦Ratchet=Porto Paranco⟧ una settimana fa, ma io non sono riuscito a fare il viaggio.\n\nAllora, te la senti di macinare un po' di strada? Va' a ⟦Ratchet=Porto Paranco⟧ e consegna questo ordine al capo del porto Dizzywig: probabilmente sarà al molo.\n\nFallo per me e avrò altri lavori per te.\n\nLavori, amico mio, con serie possibilità di guadagno...", "Parla più forte! Dimmi, devi consegnare o ritirare?", "Ah, sì. I pezzi per Kravel. Sono contento che tu sia qui. Questa roba è rimasta qui fuori per giorni, e temevo che si arrugginisse!", 0x68543425, 0xdf36f17f, 0x20992db4, 0x0757cb25, 0xed60a7b4, "....." },
  [1130] = { "Un messaggio da Melor", "Parla con Melor Stonehoof a ⟦Thunder Bluff=Picco del Tuono⟧.", "{name}, Melor Stonehoof ha sentito parlare delle tue imprese e ha tracciato un sentiero davanti a te.\n\nSe vuoi percorrerlo, va' a ⟦Thunder Bluff=Picco del Tuono⟧ e parla con Melor. Lo troverai sull'Altura dei Cacciatori.", nil, "Dunque, {name}, sei venut<o/a>. Ora, sei pront<o/a> a viaggiare per terre lontane?\n\nSe è così, giovane {class}, allora continua ad ascoltare...", 0x5e008bcd, 0x6a65c556, 0x4231584c, nil, 0x6a852b38, "...m." },
  [1131] = { nil, "Porta la ⟦Steelsnap's Rib=Costola di Ganascia⟧ a Melor Stonehoof a ⟦Thunder Bluff=Picco del Tuono⟧.", "A volte cacciamo per il cibo. A volte cacciamo per l'onore. E a volte cacciamo per guadagnarci gli insegnamenti della Madre Terra.\n\nMa la caccia che ora ti affido non è nessuna di queste. Si tratta di uccidere una creatura che vive al di fuori della benedizione della Madre Terra.\n\nLa iena Steelsnap si aggira per ⟦Thousand Needles=Millepicchi⟧, a sud delle ⟦Barrens=Savane⟧. È un tiranno: attira a sé altre iene e sparge paura e sangue tra le bestie più pacifiche.\n\nTrova Steelsnap, {name}. Trovalo e sconfiggilo.", "Hai sconfitto l'ignobile Steelsnap, {name}?", "Sconfiggendo la creatura Steelsnap, hai liberato ⟦Thousand Needles=Millepicchi⟧ da un'orribile piaga.\n\nE questa, {name}, è la tua lezione di oggi.", 0x308aefca, 0x9044f45f, 0x9c4857f9, 0x2b305955, 0xb98ec3d8, "e...." },
  [1132] = { nil, "Parla con Fiora Longears a Theramore.", "Oh, essere di nuovo per mare! Sentire il bacio del vento e farmi cullare dalle onde come dalla mia benedetta madre, tanto tempo fa!\n\nOh, vorrei avere la tua fortuna, buon {class}, perché vedo il mare nel tuo futuro!\n\nIl mio compito è parlare alle anime intraprendenti della terra di Kalimdor, la terra delle opportunità! Se te la senti di tentare la sorte oltremare, prendi una nave da qui per il grazioso porto di Theramore. Lì parla con la mia socia, l'elfa Fiora Longears.\n\nSarà lei ad avviarti alla tua avventura a Kalimdor!", nil, "Buongiorno a te! Ti ha mandato il signor Flint da ⟦Menethil Harbor=Porto di Menethil⟧? Be', il signor Flint sa giudicare bene le persone. Se ti ha mandato lui, non c'è dubbio che il tuo posto sia qui a Kalimdor!", 0x30729feb, 0x79d16431, 0x1e6af9aa, nil, 0xf87f590d, "e..m." },
  [1133] = { "Viaggio ad Astranaar", "Parla con Shindrell Swiftfire ad Astranaar.", "Se sei appena sbarcat<o/a> da Menethil, la prima cosa da fare è... andare ad Astranaar. Sono sicuro che un membro dell'⟦Alliance=Alleanza⟧ zelante come te potrà fare del vero bene laggiù. Parla con Shindrell Swiftfire e offrile i tuoi servigi.\n\nMa non serve dire chi ti manda. Shindrell non mi conosce...", nil, "Sei qui per offrire i tuoi servigi all'⟦Alliance=Alleanza⟧, {name}? L'aiuto è il benvenuto, perché anche se la sua bellezza resta... la foresta di ⟦Ashenvale=Valtetra⟧ non è più il luogo pacifico di un tempo.", 0x78f25323, 0x8608dbb8, 0x35dfad68, nil, 0x975151ed, "...m." },
  [1134] = { "Le viverne di ⟦Stonetalon=Petrartiglio⟧", "Porta 12 Pridewing Venom Sac a Shindrell Swiftfire ad Astranaar.", "Non siamo in guerra aperta con l'⟦Horde=Orda⟧, ma la nostra pace è fragile. Spesso scopriamo i loro agenti muoversi contro di noi, ma lo fanno di nascosto.\n\nUna di queste manovre ci è stata rivelata da fonti segrete a Theramore: pare che gli orchi raccolgano il veleno delle viverne vicino al ⟦Mirkfallon Lake=Lago Mirkfallon⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧, a sud. Gli assassini orchi usano poi quel veleno nelle loro incursioni mortali segrete contro l'⟦Alliance=Alleanza⟧!\n\nSe è vero, dobbiamo fermarli, {name}. Dobbiamo privarli della loro fonte di veleno.", "Hai le sacche di veleno di viverna, {name}? Non possiamo permettere che gli orchi usino contro di noi i veleni di quelle bestie!", "Grazie, {name}. Mi rattrista ordinare il massacro di creature che forse non aiutano di loro volontà i nostri nemici, eppure è mio dovere farlo.\n\nIl tuo cuore potrà piangere per le viverne che hai ucciso, <amico/amica> mi<o/a>, ma possa poi gonfiarsi sapendo che i tuoi alleati sono al sicuro dal loro veleno.", 0xa7c7d697, 0x11cffadd, 0xf879268d, 0x5e83f83e, 0xcd6cbd25, "....." },
  [1135] = { "Veleno di ⟦Highperch=Covoalto⟧", "Porta 10 Highperch Venom Sac a Fiora Longears a Theramore.", "Come forse saprai, le viverne vengono spesso addomesticate dagli orchi per usarle come cavalcature. Ma quello che si sa meno è che il veleno di viverna, in certi ambienti, vale più della bestia stessa. Quindi, se non hai paura di andare un po' a caccia di viverne, allora... ho un lavoro per te.\n\nC'è un luogo chiamato ⟦Highperch=Covoalto⟧, nella terra di ⟦Thousand Needles=Millepicchi⟧, a ovest di qui. Le viverne di ⟦Highperch=Covoalto⟧ hanno un veleno potente. Potente, e prezioso.", "Hai trovato ⟦Highperch=Covoalto⟧, {name}? Hai avuto fortuna con le viverne di lassù?", "Ah, la maggior parte di queste sono quasi sul punto di scoppiare dal veleno, {name}. Sacche così si ottengono di solito solo dalle viverne giovani o dalle femmine fertili. Dev'essere stata una bella strage lassù a ⟦Highperch=Covoalto⟧!", 0x943fcf56, 0x49a49b68, 0xcf4ffefe, 0xc18d63cc, 0xc81ed9b7, "....." },
  [1138] = { "Il frutto del mare", "Raccogli 6 ⟦Fine Crab Chunks=Bocconcini Fini di Granchio⟧ per Gubber Blump ad Auberdine.", "Adoro il granchio. I granchi sono il frutto del mare! Puoi cuocerlo al forno, alla brace, bollirlo e grigliarlo. Si fanno in padella, fritti e saltati. C'è l'insalata di granchio, la zuppa di granchio, lo stufato di granchio, il granchio al pepe, il granchio al limone, il granchio alla radice frusta e il granchio sorpresa di ⟦Ironforge=Forgiardente⟧. Ecco... più o meno è tutto.\n\nOra sono qui a pescare, quindi non posso procurarmi Bocconcini Fini di Granchio. Puoi ricavarli dai Reef Crawler e dagli Encrusted Tide Crawler. Ci puoi fare un sacco di cose. Puoi cuocerlo al forno, alla brace, bollirlo...", "...granchio al limone, granchio alla radice frusta e granchio sorpresa di ⟦Ironforge=Forgiardente⟧. Più o meno è tutto.\n\nOh, ciao, {name}. Ce li hai quei Bocconcini Fini di Granchio di cui ti parlavo?", "Wow, questi Bocconcini Fini di Granchio sono proprio quello che mi serve. Grazie, {name}! Ho trovato questo mentre pescavo tempo fa e non so che farmene. Magari tu ci puoi fare qualcosa. Di sicuro non ci vengono dei buoni piatti di granchio.\n\nTi ho già detto tutto sui granchi, vero?", 0xcf90f28d, 0x836c5e9a, 0x029859ec, 0x81c4ae4d, 0x4d6e1f4b, "....." },
  [1140] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Libera le anime intrappolate degli ⟦Highborne=Alti Nobili⟧ a ⟦Night Run=Jorxian⟧ e a ⟦Satyrnaar=Satirnaar⟧, poi torna da Delgren il Purificatore all'⟦Maestra's Post=Accampamento di Maestra⟧.", "La scrittura degli orchi non è molto meglio degli scarabocchi di un bambino. Molti del mio ordine mi hanno deriso quando ho scelto di imparare la loro lingua, ma ho trovato utile capire meglio i miei nemici.\n\nDagli scarabocchi di Ilkrud sembra che Athrikus possieda ancora due gemme dell'anima, custodite a ⟦Night Run=Jorxian⟧ e a ⟦Satyrnaar=Satirnaar⟧, zone controllate dai satiri nel nord-est di ⟦Ashenvale=Valtetra⟧.\n\nFa' attenzione là fuori, {name}: i templi intrisi di sangue dei satiri possono turbare persino <un/una> {class} <esperto/esperta> come te.", "Una volta ho sentito sussurrare che la storia dei satiri è in qualche modo legata a quella degli Elfi della Notte, ma i miei stimati ospiti si sono mostrati restii a parlarne.", "Forse ai satiri è stato permesso di restare nella foresta troppo a lungo. Ne parlerò con Elissa la prossima volta che andrò ad Auberdine.\n\nIn ogni caso, con le gemme dell'anima distrutte, il potere di Athrikus sarà molto ridotto. Dobbiamo cogliere questa occasione per eliminare lui e il suo culto.", 0x6dbe45ec, 0x43c733b7, 0xc9035df4, 0x57e3d2c0, 0x557eef7f, "....." },
  [1141] = { "La famiglia e la ⟦Fishing Pole=Canna da Pesca⟧", "Pesca 6 ⟦Darkshore Grouper=Cernia di Rivafosca⟧ per Gubber Blump, ad Auberdine.", "Mi piace pescare. La famiglia Blump è famosa per la pesca. Mi chiamo Gubber Blump; io pesco.\n\nDa queste parti c'è un pesce che mi piace prendere, si chiama cernia di ⟦Darkshore=Rivafosca⟧. Una volta uscivo in barca a pescare cernie, ma da quando sono arrivati quei murloc cattivi non esce più nessuna barca. Scommetto che si sono mangiati anche tutte le cernie.\n\nSenti, vuoi aiutarmi a pescare le cernie di ⟦Darkshore=Rivafosca⟧? Se lo fai, ti do una ⟦Blump Family Fishing Pole=Canna da Pesca della Famiglia Blump⟧ autentica! È proprio una bella canna per prendere i pesci.", "Ci sono un sacco di buoni piatti che si fanno con le cernie di ⟦Darkshore=Rivafosca⟧. Sono buone da mangiare, ma secondo me è più divertente pescarle.\n\nHai già preso qualche cernia di ⟦Darkshore=Rivafosca⟧?", "Sono proprio delle belle cernie, {name}! Grazie per avermi aiutato!\n\nSei brav<o/a> a pescare almeno quanto mia cugina, Graun Blump. Lei ha anche la barba e ha un odore un po' strano, ma questo non le impedisce mica di pescare. Direi che hai la stoffa per usare una ⟦Blump Family Fishing Pole=Canna da Pesca della Famiglia Blump⟧.", 0x51cfab45, 0xde03fdb7, 0x220d149f, 0x9b959209, 0x5b8f085a, "....." },
  [1142] = { "Una vita che si spegne", "Trova il ⟦Treshala's Pendant=Pendente di Treshala⟧ e riportalo a Treshala Fallowbrook a Darnassus.", "Non mi resta molto da vivere... così... così... debole.\n\n...il c-c-coraggioso nano, Lonebrow, è stato mandato ad a-a-avvertire Falfindel...\n\nMa prima che io... m-m-muoia...\n\n...mia moglie, Treshala... il suo pendente, che la lega a me... rubato... da uno degli i-i-ignobili aggressori...\n\nTrovalo, t-t-ti prego... e riportalo a Treshala a Darnassus...\n\n...insieme alla n-n-notizia della mia solitaria... morte.", "Cosa ti porta a casa mia, {race}?", "No!\n\nNon è giusto. Oh, mondo crudele e insopportabile!\n\nOra devo portare questo fardello di dolore e non lasciare che l'opera di Heralath muoia con lui.\n\nSei stat<o/a> coraggios<o/a> a venire da un luogo così pericoloso, {name}. Ma ora, ti prego, lasciami.\n\nPiangerò in solitudine.", 0x2566ff32, 0xee06bc91, 0x7bd38ff5, 0x01d3203d, 0xd4c26cfb, "....." },
  [1143] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Uccidi Athrikus Narassin e porta la sua testa a Balthule Shadowstrike, vicino alla ⟦Tower of Althalaxx=Torre di Althalaxx⟧.", "Capisco. Be', se ciò che dici è vero, questo è il momento di colpire. Credo che Athrikus risieda in cima alla torre. Ma fa' attenzione: è circondato da molti stregoni potenti, molto più letali di quelli che hai affrontato finora.", "Athrikus Narassin è uno stregone antico e potente. Forse dovremmo aspettare l'aiuto di Delgren, ma evidentemente aveva molta fiducia in te, per mandarti da sol<o/a>.", "Con la morte di Athrikus, spero che le forze demoniache di questa zona vengano respinte. Non ho dubbi che si riorganizzeranno e torneranno, ma allora saremo ancora più preparati ad affrontare la loro minaccia.", 0x6dbe45ec, 0x0df455be, 0xb1924267, 0x1854f1fa, 0x2672806c, "....." },
  [1144] = { "Willix l'importatore", "Scorta Willix l'importatore fuori dalle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧.", "Finalmente, sono arrivati i soccorsi!\n\nNon hai idea di quanto tempo sono rimasto prigioniero qui. Non ricordo l'ultima volta che ho visto l'esterno di questo posto.\n\nVedi, io sono un imprenditore. Sempre a caccia di un soldo, come si dice. Avevo saputo che Mebok Mizzyrix pagava bene i Redleaf Tuber di questo porcile. Pensavo che sarebbe stata una faccenda facile: dentro e fuori. Come vedi, mi sbagliavo un pochino!\n\nComunque, se fossi così gentile da aiutarmi a uscire di qui, saprò ricompensarti a dovere.", nil, "Grazie ancora, amico! Te l'avevo detto che avrei saputo ricompensarti.", 0xc56a0766, 0xd41eb22d, 0x19bfdb10, nil, 0x7fb3ae2d, "...m." },
  [1149] = { "La Prova di Fede", "Se hai fede, salta dalle assi che si affacciano su ⟦Thousand Needles=Millepicchi⟧.", "Dunque mi hai cercato, o forse è il destino a condurti da me? Non importa. Ora sei qui, e così il tuo viaggio ricomincerà da capo.\n\nUn essere è fatto di molte sfaccettature: lo spirito, il corpo, la mente. Alcune si possono misurare con le tradizioni di una cultura. Altre possiamo solo sperare che esistano dentro di noi. Se sei d'accordo, metterò alla prova alcune delle tue sfaccettature.\n\nSe supererai la prova, diventerai più forte. Se fallirai, comprenderai la vastità del Nether.\n\nLa prima è la Prova di Fede.", "La fede. È molto più importante di quanto alcuni credano.\n\nA volte non importa in cosa credi. L'importante è credere in qualcosa.", "Solo di fronte a un'avversità inattesa cominciamo a vedere quanto è forte il nostro spirito. Hai fatto il salto della fede anche senza alcuna garanzia di sopravvivere. La tua mente è aperta e il tuo spirito è pronto per ciò che verrà.\n\nSe lo desideri, la prossima prova ti attende.", 0xc6309c50, 0x327a01d5, 0xcf6b2811, 0xa135d3da, 0x4948c899, "....." },
  [1150] = { "Prova di Resistenza", "Porta l'⟦Grenka's Claw=Artiglio di Grenka⟧ a Dorn Plainstalker a ⟦Thousand Needles=Millepicchi⟧.", "Sono lieto di vedere che il tuo coraggio resta saldo alla luce di ciò che hai già fatto. Dato che la tua fede è intatta, è giunto il momento di mettere alla prova il tuo corpo.\n\nLa prima è una prova di resistenza. Va' con degli amici all'⟦Roguefeather Den=Antro delle Piume Furenti⟧, a ovest del ⟦Freewind Post=Presidio di Ventolibero⟧. Fatti strada fino alle profondità della loro tana e distruggi le loro provviste. A quel punto avrai scatenato la loro furia e, se riuscirai a sopravvivere abbastanza a lungo, Grenka Bloodscreech in persona verrà a cercarti: uccidila e portami il suo artiglio per completare la prova.", "Devi essere pront<o/a> nello spirito, nel corpo e nella mente per le sfide che ti attendono.\n\nTroppo spesso ci precipitiamo in avanti prima di essere pronti. Considero mio dovere verso i giovani, a qualunque tribù appartengano, prepararli ai pericoli che potrebbero affrontare dopo aver lasciato la sicurezza della loro casa.", "Grenka era potente, persino per <un/una> {race}. Dovresti essere fier<o/a> della tua impresa di oggi.\n\nDurante la prova di fede hai mostrato forza di spirito, e ora hai dimostrato resistenza in battaglia affrontando le arpie delle Piume Furenti, ma è giunto il momento di una nuova prova.", 0x12df1701, 0x72831da6, 0x073abcf2, 0xc0c9c65e, 0x06612afd, "....." },
  [1151] = { "Prova di Forza", "Porta i ⟦Fragments of Rok'Alim=Frammenti di Rok'alim⟧ a Dorn Plainstalker a ⟦Thousand Needles=Millepicchi⟧.", "Al tempo degli Dei Antichi, gli elementali abitavano gran parte di questo mondo. Adoravano gli Dei Antichi e gli Dei, con il loro potere, tenevano gli elementali legati a questo mondo. Quando gli Dei Antichi furono banditi, gli elementali svanirono dal nostro mondo e ora vi fanno ritorno solo su richiesta di maghi potenti.\n\nCi sono però delle eccezioni. Alcuni elementali erano abbastanza potenti da restare qui da soli. Uno di questi è Rok'Alim.\n\nPer mettere alla prova la tua forza, trova Rok'Alim a ⟦Thousand Needles=Millepicchi⟧ e uccidilo.", "Le tribù di centauri di ⟦Thousand Needles=Millepicchi⟧ chiamano Rok'Alim anche il Martellatore, per il rombo dei suoi pugni quando percuote le creature abbastanza coraggiose, o stupide, da sbarrargli la strada.", "La Prova di Forza è compiuta. Hai mostrato forza e coraggio, e ora sei pront<o/a> per l'ultima prova prima che questi riti siano completati.", 0xace06693, 0xf94cffe9, 0x1118dcbc, 0x474061dc, 0x6f3ea674, "....." },
  [1152] = { "⟦Test of Lore=Prova di Conoscenza⟧", "Trova Braug Dimspirit vicino all'ingresso del Sentiero di Graffiofondo, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "Il tuo tempo con me è quasi finito. Possiedo molto sapere, ma non spetta a me impartirti la ⟦Test of Lore=Prova di Conoscenza⟧. Ci sono lezioni da imparare e luoghi da visitare su cui altri reclamano il dominio.\n\nSe sei pront<o/a>, cerca Braug Dimspirit: è uno sciamano di grande saggezza. Ti metterà ancora alla prova, quindi ascolta bene le sue parole, {name}.\n\nQuando sarai pront<o/a>, trova la galleria che collega le ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ a ⟦Ashenvale=Valtetra⟧: Braug vive lì vicino. E fa' attenzione, {name}: gli elfi della notte potrebbero voler ostacolare la tua prova.", nil, "I giorni e le notti si fanno più freddi in tutto il mondo, mentre i goblin devastano la terra e gli elfi della notte puntano il dito contro le razze più giovani. I Reietti e gli orchi non sono i soli colpevoli delle difficoltà che affliggono Kalimdor e Lordaeron. Molte delle razze intelligenti hanno contribuito al dolore del mondo. Dorn lo sa, e ti ha mandato da me perché hai mostrato le qualità necessarie per comprenderlo a tua volta.\n\nOra sei al cospetto di Braug.", 0xdf27dbbd, 0xbc1c7dd5, 0xf66e37cc, nil, 0xbf8f016c, "...m." },
  [1153] = { "Un nuovo campione di minerale", "Trova un ⟦Unrefined Ore Sample=Campione di Minerale Grezzo⟧ su un Gravelsnout Digger o un Gravelsnout Surveyor e portalo a Tatternack Steelforge, a Camp Taurajo nelle ⟦Barrens=Savane⟧.", "{class}, in passato mi hai aiutato bene. Finora il Capoguerra è soddisfatto di ciò che ho ottenuto e mi chiede di continuare con rinnovata determinazione. Il mio onore impone che io ti dia il giusto riconoscimento davanti al Capoguerra per tutto ciò che hai fatto, ma prima vorrei chiederti di nuovo il tuo aiuto.\n\nDi recente sono arrivati dei viaggiatori da sud, da un luogo chiamato ⟦Thousand Needles=Millepicchi⟧. Laggiù hanno ucciso un coboldo che aveva un insolito campione di minerale, ma non hanno voluto vendermelo. Voglio un campione di quel minerale da esaminare.", "Ho rivisto quei viaggiatori, quelli che non hanno voluto vendermi un campione del minerale. Ho sputato loro addosso perché non hanno aiutato il Capoguerra.\n\nChe muoiano in battaglia da codardi e non da guerrieri, come dovrebbe spettare a tutti coloro che si alleano con l'⟦Horde=Orda⟧.", "Un buon campione, {name}. Davvero un buon campione.\n\nQuei viaggiatori non potranno più vantarsi con me del minerale che hanno trovato, ora che ci sei riuscit<o/a>.\n\nMi metterò subito al lavoro. Se si rivelerà abbastanza resistente, manderò al Capoguerra un'arma forgiata con questo materiale per mostrargli il nostro successo.\n\nNon dimenticherò il tuo aiuto, {class}.", 0x3d65e9bc, 0xeedf12cb, 0x8c10fc6a, 0x8d95d80a, 0xb5b523b0, "....." },
  [1154] = { "⟦Test of Lore=Prova di Conoscenza⟧", "Trova l'⟦Legacy of the Aspects=Eredità degli Aspetti⟧ e riportala a Braug Dimspirit vicino all'ingresso del Sentiero di Graffiofondo, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "Hai superato le prove di Dorn e ora cerchi di superare la prossima. Molto bene. Ma finora le tue sfide sono state infantili. È facile mettere alla prova il corpo: la mente è tutt'altra faccenda.\n\nTe lo spiegherò in modo semplice: trova il libro che ti indico, studialo e rispondi alla mia domanda sul suo contenuto.\n\nQuale libro, ti starai chiedendo? L'⟦Legacy of the Aspects=Eredità degli Aspetti⟧. Si trova in fondo all'Eremo di Dor'danil, nel sud di ⟦Ashenvale=Valtetra⟧, protetto dai druidi morti e dai loro assassini.", "Portami il libro dopo averlo studiato. Non ti farò la mia domanda finché non mi avrai dato il libro.", "Questo è il libro che ti ho indicato. C'è speranza, allora, che risponderai correttamente alla mia domanda... a meno che tu non abbia dimenticato di studiarne il contenuto.\n\nQuando sarai pront<o/a>, parlami di nuovo e ti porrò una domanda.", 0xdf27dbbd, 0x39bbcae9, 0x72aec8c5, 0xef15ae23, 0x8b098b5b, "....." },
  [1159] = { "⟦Test of Lore=Prova di Conoscenza⟧", "Trova Parqual Fintallas a ⟦Undercity=Sepulcra⟧.", "Ben fatto, {name}. Hai superato la prima parte della ⟦Test of Lore=Prova di Conoscenza⟧, ma c'è ancora un'altra domanda a cui rispondere. Però non spetta a me porla.\n\nCerca Parqual Fintallas nella città di Lordaeron. Era un grande storico degli umani prima che la Piaga lo sopraffacesse. Ora continua a cercare l'illuminazione, ma di natura diversa.\n\nAvrà un'altra richiesta da farti prima di chiederti qualsiasi cosa, ma finora te la sei cavata magistralmente: sono sicuro che supererai il suo ostacolo.", nil, "Ti ha mandato Braug? Impossibile.\n\n<Parqual ti squadra da capo a piedi.>\n\nHai sfidato l'Eremo di Dor'danil, hai fatto un atto di fede, hai combattuto e sopraffatto un potente elementale? Bah! Probabilmente sei una montatura, qualche avventuriero che ha origliato chiacchiere in una taverna. E ora pensi di avere la stoffa per superare la mia prova. E sia... {class}.", 0xdf27dbbd, 0x476bd838, 0xbc70b167, nil, 0x47c906c9, "...m." },
  [1160] = { "⟦Test of Lore=Prova di Conoscenza⟧", nil, nil, nil, nil, 0xdf27dbbd, nil, nil, nil, nil, ".mmmm" },
  [1167] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Parla con Balthule Shadowstrike vicino alla ⟦Tower of Althalaxx=Torre di Althalaxx⟧.", "Prima di affrontare Athrikus, sarebbe saggio consultarti con Balthule. Non ho dubbi che abbia sorvegliato la torre con attenzione, e potrebbe avere informazioni sugli ultimi sviluppi.", nil, "Ah, che bello rivederti, {name}! Da queste parti stanno succedendo cose stranissime, sono contento che tu sia arrivat<o/a>!\n\nÈ stato molto strano, {name}. Sembrava tutto normale (be', normale per quanto le cose possano esserlo da queste parti) e poi all'improvviso c'è stato un lampo di luce accecante dalla stanza in cima alla torre. Poi sono arrivate le urla. Le grida squarciavano l'aria e ogni tanto i fulmini colpivano il suolo. Che sta succedendo?", 0x6dbe45ec, 0x8c848775, 0xac045326, nil, 0xce65d2b7, "...m." },
  [1174] = { "Vincono gli gnomi!", nil, nil, nil, nil, 0x5a91d422, nil, nil, nil, nil, ".mmmm" },
  [1176] = { "Alleggerire il carico", "Procura 10 Hollow Vulture Bone per Pozzik nelle Distese Salate.", "Quando si tratta di corse, ogni dettaglio conta! Che sia una piccola regolazione della potenza erogata, un leggero allentamento delle bobine di tensione o l'alleggerimento del telaio, devi tenere conto di tutto.\n\nUsiamo ossa di avvoltoio per molte delle piccole modifiche strutturali ai nostri bolidi: offrono l'equilibrio perfetto tra robustezza e peso. E per di più è facile procurarsene altre, visto che le piane salate pullulano di avvoltoi.\n\nPortamene un po' e te le pagherò bene.", "Hai quelle ossa per me? Stavo proprio per cominciare ad alleggerire lo sterzo, ma non voglio aprirlo senza tutti i pezzi che mi servono.", "Fantastico! Posso mettere subito la squadra al lavoro. Grazie, {name}!", 0x8045452d, 0x9cca10c7, 0xe02de3be, 0xb41bd113, 0x8ecc8ad5, "....." },
  [1179] = { "I fratelli Brassbolts", "Porta la cassa di caschi protettivi a Wizzle Brassbolts nelle Distese Salate.", "Hai mai sentito parlare delle Distese Salate? È un tratto di piane salate laggiù a Kalimdor, appena a sud del canyon di ⟦Thousand Needles=Millepicchi⟧. È un posto fantastico per le corse perché, beh, è così piatto!\n\nUn paio di fratelli gnomi, amici miei, sono laggiù a provare la loro nuova auto a razzo, e da quel che sento è veloce! Eh, così veloce che i loro piloti continuano a schiantarsi. E si beccano delle commozioni cerebrali.\n\nCosì mi hanno chiesto degli elmi da macchina d'assedio, ma io ho dei compiti qui. Non posso fare il viaggio!\n\nTu puoi?", "Guarda dove metti i piedi! Guarda guarda guarda!! Questa è roba delicata, sai, e se vogliamo vincere deve funzionare tutto alla perfezione!", "Ah! Longbeard ti ha mandato con un carico di elmi! Evviva!\n\nOra forse riusciremo a convincere un pilota a guidare la nostra auto...", 0x089469a7, 0x61c0dbae, 0x6042b639, 0xbe73198d, 0x3d6efd11, "....." },
  [1195] = { "La fiamma sacra", "Riporta una ⟦Filled Etched Phial=Fiala Intagliata Piena⟧ a Zangen Stonehoof, a ⟦Thunder Bluff=Picco del Tuono⟧.", "I centauri Galak di ⟦Thousand Needles=Millepicchi⟧ proteggono un manufatto risalente ai tempi della creazione dei centauri.\n\nVorremmo recuperarlo, ma ci serve una fiala d'acqua da uno dei pozzi lunari degli Elfi della Notte.\n\nPer raccogliere l'acqua, dovrai prima procurarti una delle fiale portate dalle driadi vicino al ⟦Raynewood Retreat=Rifugio di Legnovivo⟧, nel cuore della foresta di ⟦Ashenvale=Valtetra⟧. C'è un pozzo lunare vicino alla riva occidentale del ⟦Falfarren River=Fiume Falfarren⟧, a sud della strada principale, dove potrai riempire la fiala.", "Quando avremo la fiala piena, potremo mandarla al mio socio, Rau, a ⟦Thousand Needles=Millepicchi⟧. È stato lui a chiedere la fiala d'acqua, quindi saprà meglio come usarla.", "Molto bene. Dovrebbe soddisfare perfettamente la richiesta di Rau. Potresti portargliela? Magari ti piacerà passare un po' di tempo a Millepicchi.", 0x0eec15af, 0xbef453f2, 0x39ee05d9, 0x1e88abdc, 0x6bcc8f92, "....." },
  [1196] = { "La fiamma sacra", "Consegna la ⟦Filled Etched Phial=Fiala Intagliata Piena⟧ a Rau Cliffrunner al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Porta la fiala piena a Rau Cliffrunner al ⟦Freewind Post=Presidio di Ventolibero⟧, nel sud-est di ⟦Thousand Needles=Millepicchi⟧. Puoi raggiungere ⟦Thousand Needles=Millepicchi⟧ prendendo il Grande Ascensore al confine meridionale delle ⟦Barrens=Savane⟧.\n\nNon mi sorprenderebbe se potessi aiutarci ancora.", "Non è che ti manda Zangen, eh?", "Mmm, sì, questa fiala d'acqua servirà perfettamente ai nostri scopi. Grazie alla discendenza comune di driadi e centauri, l'acqua dei pozzi lunari ci permetterà di superare la protezione della fiamma eterna che circonda la reliquia dei centauri.", 0x0eec15af, 0xedccb470, 0xcc1fbf00, 0xa64fa397, 0x98a80600, "....." },
  [1197] = { "La fiamma sacra", "Recupera lo ⟦Cloven Hoof=Zoccolo Fesso⟧ per Rau Cliffrunner al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Con l'acqua che hai portato potrai spegnere temporaneamente la fiamma che protegge la reliquia dei centauri. Però non funzionerà per sempre, quindi dovrai fare in fretta.\n\nTroverai la ⟦Splithoof Crag=Rupe di Zoccolo Spezzato⟧, la roccaforte dei centauri, a nord di qui. La fiamma è custodita nel ⟦Splithoof Hold=Covo di Zoccolo Spezzato⟧, una parte della rupe sorvegliata da molte guardie.\n\nFai attenzione, però: qui i centauri Galak sono numerosi, e non saranno affatto disposti a cedere qualcosa a cui tengono tanto.", "Sono impaziente di mettere le mani sullo ⟦Cloven Hoof=Zoccolo Fesso⟧. L'hai già preso?", "Percepisco una strana energia che emana dallo Zoccolo... Non ho dubbi che studiandolo scopriremo nuove e sorprendenti informazioni sui centauri.\n\nGrazie, {name}. Ora devo cominciare a decifrare i misteri che mi hai portato.", 0x0eec15af, 0x29892850, 0xe37c2230, 0x248ac646, 0x46ef0c77, "....." },
  [1198] = { "Alla ricerca di Thaelrid", "Cerca la guardia argentea Thaelrid negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧.", "In questi giorni circolano molte voci sull'alleanza tra il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ e i naga negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧, sulla costa di ⟦Ashenvale=Valtetra⟧.\n\nIl mio compito qui con l'⟦Argent Dawn=Alba d'Argento⟧ è raccogliere quante più informazioni possibile, così da sapere quando e dove serve aiuto.\n\nSono passate settimane da quando ho mandato un esploratore a controllare le attività negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. La guardia argentea Thaelrid non ha ancora fatto rapporto.\n\nGli altri miei esploratori sono impegnati in questioni urgenti.\n\nTrova Thaelrid e aiutalo per me, {name}.", nil, "Ha fatto bene la vegliante dell'alba Shaedlass a mandarti. In questo luogo corrotto è davvero in atto un piano malvagio.", 0x6711bba5, 0x899a2616, 0x5e4d6659, nil, 0xa5cf35d8, "...m." },
  [1199] = { "La caduta del Crepuscolo", "Porta 10 Twilight Pendant alla guardia argentea Manados a Darnassus.", "Forti degli antichi riti dei caotici Dei Antichi, i membri del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ lottano per riportare i loro oscuri patroni e diffondere morte e terrore in tutto il mondo.\n\nCrediamo che il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ si sia alleato con i naga e che si stia radunando negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧, sulla costa di ⟦Ashenvale=Valtetra⟧.\n\nQualunque piano malvagio si stia tramando nelle profondità dell'antico tempio, va sventato.\n\nMuovi guerra al Martello e riporta le prove delle tue gesta. I tuoi sforzi saranno ricompensati generosamente.", "Gli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧ erano un tempo un antico tempio degli Elfi della Notte. Un tempo ospitavano un potentissimo pozzo lunare. Chissà quale male vi si trama ora per mano del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.\n\nHai fatto progressi nel liberarci della loro presenza?", "Senza dubbio nelle tue vene scorre sangue coraggioso e nobile, {name}. L'⟦Argent Dawn=Alba d'Argento⟧ ti elogia per i tuoi sforzi contro il male.", 0x89671cf6, 0x4e205a89, 0x1b3033fd, 0x81e6c9bf, 0x80ee0d52, "....." },
  [1200] = { "Malvagità a ⟦Blackfathom=Fondocupo⟧", "Porta la testa di Twilight Lord Kelris a Dawnwatcher Selgorm, a Darnassus.", "Le forze mi hanno abbandonato. Ho bisogno del tuo aiuto!\n\nTanto tempo fa questo luogo era un grande tempio di Elune. Ma la sventura lo portò alla rovina quando la corruzione di un Dio Antico filtrò dalle profondità della terra e contaminò il sacro Pozzo della Luna.\n\nAku'Mai, servitore del Dio Antico, emerse dalle acque.\n\nI cultisti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ si sono alleati con i naga per occupare questi luoghi. I cultisti, guidati da Kelris, sacrificano innocenti ad Aku'Mai in cambio di potere.\n\nUccidi Kelris e porta la sua testa a Selgorm, a Darnassus, {name}, ti prego.", "Il tempo è una risorsa preziosa, {class}.\n\nIl mio compito qui a Darnassus è assicurare che l'⟦Argent Dawn=Alba d'Argento⟧ prosperi e che le forze del male che minacciano Kalimdor vengano sventate.\n\nEsponi in fretta ciò che ti porta qui, o va' per la tua strada.", "Kelris ci è sfuggito per parecchio tempo.\n\nSembra che, ogni volta che il male si manifestava da queste parti, Kelris avesse avuto un ruolo. Per un certo periodo lo abbiamo creduto morto o disperso.\n\nMa ora tutto torna. Ponendo fine al suo regno hai risparmiato la vita di molti innocenti.\n\nPer la Luce! Sacrificare qualcuno a un servitore di un Dio Antico per il proprio tornaconto è quanto di più riprovevole ci sia!\n\nHai compiuto una grande impresa, {name}. Ti rendo omaggio a nome dell'⟦Argent Dawn=Alba d'Argento⟧.", 0x43ec82c9, 0x563f3e88, 0x7cceb3eb, 0xcf6bba07, 0xa9fa6819, "....." },
  [1220] = { "Il capitano Vimes", "Porta il ⟦Spy's Report=Rapporto della Spia⟧ al capitano Garran Vimes.", "Il capitano Vimes dovrebbe vedere il rapporto orchesco che hai trovato, {name}. Conosce la lingua degli orchi meglio di quasi tutti. E deve sapere che ci sono spie dell'⟦Horde=Orda⟧ vicino a Theramore!\n\nIl capitano si trova nella caserma, sul lato nord-orientale dell'⟦Theramore Isle=Isola di Theramore⟧.", "Hai qualcosa per me?", "Un rapporto di una spia orco! Come l'hai trovato? Non importa, vediamo cosa dice...", 0x5cadbab4, 0x82091bb0, 0xf362d612, 0xa03be4c2, 0x434989ce, "....." },
  [1221] = { "Tuberi di Foglia Blu", "Prendi una Crate with Holes.\n\nPrendi un ⟦Snufflenose Command Stick=Vincastro per Tartasniffo⟧.\n\nPrendi e leggi il ⟦Snufflenose Owner's Manual=Manuale di Istruzioni del Tartasniffo⟧.\n\nNelle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧, usa la Crate with Holes per evocare uno Snufflenose Gopher e usa il vincastro sul gopher per fargli cercare i tuberi.\n\nPorta 6 Blueleaf Tuber, il ⟦Snufflenose Command Stick=Vincastro per Tartasniffo⟧ e la Crate with Holes a Mebok Mizzyrix, a ⟦Ratchet=Porto Paranco⟧.", "I tuberi di foglia blu sono una prelibatezza in tutto il mondo! Ma sono rari, rarissimi. L'unico posto dove trovarli è qui nelle ⟦Barrens=Savane⟧, nelle profondità della terra, nelle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧.\n\nE anche lì è impossibile trovarli, a meno di sapere esattamente dove cercare! Per questo ho addestrato questi tartasniffo a scovarli per me. Hanno un gran fiuto e sentono l'odore di un tubero a cinquanta passi di distanza.\n\nNon sarà facile, ma se mi porti qualche tubero ti pagherò profumatamente.", "Hai i tuberi, {name}?", "Grande, li hai presi! Posso venderli ai miei contatti per un bel gruzzolo!\n\nGrazie per la consegna, {name}! Sei <un/una> gran <socio/socia>.", 0x7ee65c2a, 0x7098b232, 0x604bd2e9, 0x6deb831e, 0xca3541f1, "....." },
  [1238] = { "Il rapporto perduto", "Porta il ⟦Spy's Report=Rapporto della Spia⟧ a Nazeer Bloodpike a ⟦Brackenwall Village=Felcimura⟧.", "Frugando nella terra smossa, trovi la mano mozzata di un orco. Stretto nella mano c'è un tubo intagliato nell'osso. E nel tubo c'è una pergamena macchiata di terra.\n\nLa pergamena è un rapporto scritto da un orco che ha passato settimane a spiare la città di Theramore.\n\nDopo averla scorsa, è chiaro che va portata al capo delle spie orco a ⟦Brackenwall Village=Felcimura⟧.", "Hai qualcosa per me?", "Ottimo lavoro, {name}. Il nostro agente, Marg Nighteye, era di stanza fuori Theramore. Aveva il compito di spiare la città.\n\nQuesto è il suo ultimo rapporto, e potrebbe essere davvero l'ultimo: da quello che racconti, temo che Marg abbia trovato la morte nella palude...", 0xf5b5536a, 0xad5280a6, 0x2210ebf5, 0xa03be4c2, 0xf08dae6b, "....." },
  [1241] = { "Il diplomatico scomparso", "Trova Jorgen a ⟦Stormwind City=Roccavento⟧.", "Di recente un diplomatico è stato mandato a Theramore per incontrare Jaina Proudmoore. Quel diplomatico non è mai arrivato.\n\nCredo che dietro a questo complotto ci siano i Defias, ma non so in che modo. La scomparsa del diplomatico sfugge ancora all'attenzione pubblica, ma non potrà restare così a lungo.\n\nGli agenti del re stanno già setacciando la città in cerca di indizi, ma ho dei contatti miei che vorrei coinvolgere.\n\nNella ⟦Valley of Heroes=Valle degli Eroi⟧ c'è un mio vecchio amico di nome Jorgen. Trovalo, dagli questo messaggio e segui le sue istruzioni.", "Mph, faresti meglio ad avere un buon motivo per disturbare un uomo che pesca. Non sopporto i venditori ambulanti, figuriamoci i mendicanti.", "Mmh... <Jorgen ti guarda con gli occhi socchiusi.>\n\nVa bene. Ti aiuterò, ma non perché ne ho voglia: perché ci sono obbligato.\n\nE mettiamo subito una cosa in chiaro: sai già molto più di quanto dovresti. Teniamocelo come nostro piccolo segreto, e non andare a spifferare in giro per le taverne quello che scopri. Capito?", 0xbe525a75, 0x33b9abb0, 0x849a1ec8, 0x3360f67b, 0x7c260137, "....." },
  [1242] = { "Il diplomatico scomparso", "Consegna il ⟦Sealed Note to Elling=Messaggio Sigillato per Elling⟧ di Jorgen a Elling Trias, a ⟦Stormwind City=Roccavento⟧.", "Porta 'sto messaggio a Elling Trias. Non dirgli nient'altro. Sii educat<o/a> e aspetta che ti risponda. E non preoccuparti, lo farà.\n\nTe lo ripeto solo un'altra volta, {name}: prendi la faccenda sul serio e tieni la bocca chiusa.\n\nTrovi Trias nel suo negozio di formaggi, il Trias' Cheese, nel ⟦Trade District=Quartiere del Commercio⟧. Buona fortuna.", "Salve, {name}. Posso fare qualcosa per te? Magari vuoi assaggiare il nostro speciale cheddar Trias? O un pezzo di Groviera di Darnassus?", "Scusa, una lettera per me? Ma guarda un po'... non capita spesso di ricevere una consegna che non sia una cassa o un barile, quando non fai altro che lavorare. Vediamo di che si tratta.\n\n<Elling ti guarda mentre apre la lettera.>\n\nSembri un po' tes<o/a>, tutto bene, {name}?", 0xbe525a75, 0x5346c0c9, 0x39356874, 0x382f590a, 0x3fbb5bf2, "....." },
  [1243] = { "Il diplomatico scomparso", "Consegna a ⟦Duskwood=Boscovespro⟧ il ⟦Sealed Note to Watcher Backus=Messaggio Sigillato per il Guardiano Backus⟧.", "Jorgen, vecchio figlio di una... Allora è così che vanno le cose, eh?\n\nVa bene, posso farci i conti. Spero che finisca nella ⟦Twisting Nether=Distorsione Fatua⟧ ancora prima!\n\nEcco come andrà, {name}. Io comincerò a sentire i miei contatti qui, ma il grosso delle scarpinate lo farai tu, così risparmio qualche moneta.\n\nVa' a ⟦Darkshire=Borgoscuro⟧, a ⟦Duskwood=Boscovespro⟧, e trova il guardiano Backus: di solito pattuglia la strada nord, appena fuori dal paese. Digli solo che stai indagando per conto mio sulle attività dei Defias e ti aiuterà con tutte le informazioni che può.", "Non è molto sicuro andarsene in giro per i boschi, {name}. Sta' attent<o/a>, e se vedi qualcosa di sospetto o pericoloso, avverti subito i Guardiani. Non provare ad affrontare niente da sol<o/a>. Non siamo responsabili di qualunque cosa terribile possa capitarti.\n\nMa sappiamo entrambi che mi ignorerai e combatterai comunque qualunque cosa esca dall'oscurità, vero? Ah ah, già, voi avventurieri... tutti uguali.", "Oh, ti manda Trias, eh? Allora è un po' diverso.\n\nSentiti liber<o/a> di combattere qualunque mostruosità ti venga addosso dall'oscurità. Sono sicuro che te la caverai senza problemi, se sei il tipo che se la fa con gente come lui.\n\nAllora, di cosa ha bisogno il mio amico in una giornata così cupa?", 0xbe525a75, 0x46fcf9c1, 0x7257660b, 0x9545778d, 0x820d06c6, "....." },
  [1244] = { "Il diplomatico scomparso", "Trova il ⟦Defias Docket=Registro dei Defias⟧ e riportalo al guardiano Backus a ⟦Duskwood=Boscovespro⟧.", "Attività dei Defias? Beh, c'è sempre qualche attività; anche se se ne stanno per conto loro, li consideriamo una minaccia.\n\nMa, ora che ci penso, di recente c'è stato un avvistamento che mi è sembrato strano. Sarà stato un paio di settimane fa: alcuni dei loro agenti si erano radunati attorno alla ⟦Addle's Stead=Cascina degli Addle⟧. Dal rapporto, avrei detto che era successo qualcosa di grosso.\n\nPerché non dai un'occhiata lì per prima cosa e mi riporti tutto ciò che trovi?\n\nLa fattoria è a sud della strada che viene dalle ⟦Westfall=Marche Occidentali⟧, appena entri a ⟦Duskwood=Boscovespro⟧.", "Fa' attenzione là fuori, {name}. So che è stato Trias a mandarti qui, ma questo non significa che nei boschi non si nasconda qualcosa che potrebbe crearti dei guai... soprattutto ora che indaghi sui Defias.", "Sei tornat<o/a> san<o/a> e salv<o/a>. Non si potrebbe chiedere molto di più, no?\n\nOra vediamo cosa abbiamo qui. Ha l'aria piuttosto ufficiale, rispetto ai documenti dei Defias che ho visto. Ma potrebbe essere un falso, solo per sviarti da quello che stai cercando.", 0xbe525a75, 0x48feff50, 0xea67aecc, 0xcea0ed63, 0x67804e8a, "....." },
  [1245] = { "Il diplomatico scomparso", "Porta il ⟦Defias Docket=Registro dei Defias⟧ a Elling Trias a ⟦Stormwind=Roccavento⟧.", "Accidenti, questa roba sembra fin troppo complicata per essere solo un modo per metterti fuori strada. Non dovrei nemmeno guardarla. Portala a Trias: lui saprà darle un senso. E NON lasciare che nessuno ti ostacoli. È una cosa più grande di me. Potrebbe essere più grande perfino di lui, ma vedremo.\n\nE fammi un favore, {name}: non dire a nessuno che ti ho aiutato. Se i miei superiori scoprissero che sapevo qualcosa di tutto questo e non gliel'ho detto, probabilmente mi impiccherebbero.", "Vedo che sei tornat<o/a>, e tutto in un pezzo. Sappiamo entrambi che non sei qui per il formaggio, quindi lasciamo perdere i convenevoli. Backus ti è stato d'aiuto, o non sei nemmeno ancora partit<o/a> per ⟦Duskwood=Boscovespro⟧?", "Sì... è una lettura interessante. Jorgen e DeLavey hanno fatto bene a coinvolgermi.\n\nSembra che i Defias si siano dati parecchio da fare per portare a termine questo loro piano. Mmm... cos'è questo? «Fist»? È un nome familiare.", 0xbe525a75, 0xa98e158b, 0xfafe092f, 0x24e86e52, 0x8bf38d0b, "....." },
  [1246] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1247] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1248] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1249] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1250] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1264] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1265] = { "Il diplomatico scomparso", "Cerca al ⟦Sentry Point=Presidio di Guardia⟧ qualche traccia del soldato Hendel.", "Hendel? Sì, conosco quell'uomo. Ma perché ti serve uno dei miei soldati?\n\nTi ha mandato Elling a cercarlo? Mmm, la cosa non mi piace. Elling non ti avrebbe fatto venire prima da me se la faccenda non fosse preoccupante. Capisco se non puoi dirmi di cosa si tratta, ma sappi questo: ho il dovere di proteggere queste terre. Se hai intenzione di creare scompiglio, ti consiglio di dirmi tutto quello che puoi.\n\nCredo che Hendel fosse di stanza alla prima torre fuori da Theramore. Sii prudente.", "Sì, {name}?", "L'uomo che cerchi, quello che chiamano Hendel, non è qui. Altre fonti hanno portato a lady Proudmoore informazioni che credo tu conosca già. Mi ha chiesto di trovarti e di aiutarti nella tua impresa. Se me lo permetti, ti dirò dove trovare il soldato Hendel, così potremo consegnarlo alla giustizia.", 0xbe525a75, 0xb829492c, 0xb6dd2bf9, 0xabfc0333, 0xf5957b11, "....." },
  [1266] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1267] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1274] = { "Il diplomatico scomparso", "Trova il vescovo DeLavey nel Castello di ⟦Stormwind=Roccavento⟧.", "Scusa, <signore/signora>. Il vescovo DeLavey mi ha chiesto di avvicinare gli avventurieri che potrebbero aiutarlo in una faccenda delicata.\n\nSe potessi recarti con discrezione al Castello di ⟦Stormwind=Roccavento⟧ e parlargli appena possibile, sono certo che apprezzerebbe il tuo aiuto. Ancora una volta, ti prego, sii discret<o/a>. È una questione di una certa importanza.", nil, "Salve, {name}. Sono il vescovo DeLavey.\n\nSe mi chiedi cosa faccio qui al castello, senza dubbio il giovane Thomas è riuscito a reclutarti per aiutare il nostro regno. È sempre stato bravo a eseguire le mie richieste.\n\nTemo di non avere il tempo di dilungarmi, quindi permettimi di essere diretto... e ti prego, cerca di evitare che la cosa diventi di dominio pubblico.", 0xbe525a75, 0xad07fc69, 0x603a2b7b, nil, 0x1740d560, "...m.", nil, nil, 0xdcbfc145, nil, nil },
  [1275] = { "Studiare la corruzione", "Gershala Nightwhisper, ad Auberdine, vuole 8 Corrupt Brain stem.", "Gli stolti elfi del sangue si cimentano con la magia demoniaca. Non hanno visto cos'è successo ai naga e ai satiri di Kalimdor?\n\nTemo che gli elfi del sangue andranno incontro a una simile deformazione. Azeroth non può permettersi di dare alla luce un'altra ignobile razza di mostri.\n\nDesidero studiare i tronchi cerebrali dei satiri e dei naga, per capire quale destino attende gli elfi. Negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧, sulla costa di ⟦Ashenvale=Valtetra⟧, troverai sia satiri sia naga.\n\nÈ un lungo viaggio, {name}.", "Quando avrò abbastanza campioni da studiare, potrà cominciare il mio vero lavoro. Con i tronchi cerebrali corrotti dei satiri e dei naga degli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧ posso cercare una correlazione tra le mutazioni.\n\nForse, con questa conoscenza, potremo impedire agli elfi del sangue di sprofondare ancora di più nella deformità e nel male.", "Hai viaggiato a lungo e di certo hai affrontato grandi pericoli.\n\nHai agito con altruismo. Aiutarmi nelle mie ricerche è per il bene di tutta Azeroth. Ti ringrazio, {name}, per tutto ciò che hai fatto.\n\nOra, se vuoi scusarmi, ho molto lavoro da fare...", 0x80a39979, 0x1c3b6c70, 0x7deb66bd, 0x0e194d4e, 0x90492795, "....." },
  [1324] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1338] = { "L'ordine di Stormpike", "Porta la ⟦Stormpike's Request=Richiesta dei Piccatonante⟧ a Furen Longbeard, a ⟦Stormwind=Roccavento⟧.", "C'è un armaiolo nanico di cui ammiro molto il lavoro. Si chiama Furen Longbeard, e la sua abilità non ha eguali. Mi serve un nuovo scudo, e devo averne uno dei suoi!\n\nIl problema è che... Furen sta molto a sud, nel quartiere dei nani di ⟦Stormwind=Roccavento⟧. Nelle terre degli umani! Non riesco a immaginare perché viva laggiù, così lontano da ⟦Ironforge=Forgiardente⟧. Gli umani devono pagarlo una fortuna per tenerlo lì!\n\nAllora, se hai voglia di viaggiare e non ti dispiace guadagnare qualche soldo, porteresti a Furen la mia richiesta per uno scudo?", "Una lettera dalle terre dei nani? Chissà chi scrive da così lontano, a nord...\n\nPrego, fammi vedere l'ordine.", "Ah, una richiesta da uno degli Stormpike. È un clan orgoglioso, pieno di nani di qualità. E anche ricchi.\n\nGrazie, {name}. Mi metterò al lavoro sullo scudo del montanaro Stormpike entro la fine della giornata.", 0xecf988f4, 0x130880f5, 0x24e88b1f, 0xd07031a3, 0xae03cdbb, "....." },
  [1339] = { "L'incarico del montanaro Stormpike", "Parla con il montanaro Stormpike.", "Ho sentito che il montanaro Stormpike cerca un corriere. Qualcuno che viaggi un po' per conto suo. Che ne dici? Sei tu il {race} giusto per il lavoro?\n\nSe è così, troverai Stormpike in cima alla torre di guardia settentrionale.", nil, "Proprio così. Ho un compito che non posso svolgere mentre sono di guardia. Anzi, ti porterà lontano da Loch Modan.\n\nL'occasione perfetta per un'avventura!", 0x7fce6abd, 0x1e66698f, 0xb2c24d7c, nil, 0x86e71667, "...m." },
  [1358] = { "Un campione per Helbrim", "Porta il ⟦Wolf Heart Sample=Campione di Cuore di Lupo⟧ allo speziale Helbrim, nelle ⟦Barrens=Savane⟧.", "Un collega a Kalimdor, lo speziale Helbrim, sta studiando gli effetti delle tossine di Lordaeron sulle bestie di Kalimdor. Sarebbe molto interessato a un campione dei cuori di lupo che mi ha mandato Renferrel.\n\nHelbrim si trova nelle ⟦Barrens=Savane⟧, in un villaggio chiamato ⟦Crossroads=Crocevia⟧. Per raggiungerlo devi prendere lo zeppelin fino a Orgrimmar, la capitale degli orchi, poi andare a sud, a piedi, fino a Durotar. Dirigiti a ovest nelle ⟦Barrens=Savane⟧ e presto arriverai al ⟦Crossroads=Crocevia⟧.", "Hai un pacco per me?", "Ah, molto bene. Se i primi rapporti sono veri, la tossicità di questi cuori potrebbe portare a nuovi progressi nella nostra conoscenza dei veleni.\n\nÈ una consegna gradita, {name}. La tua ricompensa è ben meritata.", 0x1774ad9a, 0x34098eea, 0x43d57adf, 0x3bd8c94e, 0x48a9688d, "....." },
  [1359] = { "La consegna di Zinge", "Porta i ⟦Wolf Heart Samples=Campioni di Cuore di Lupo⟧ alla speziale Zinge, a ⟦Undercity=Sepulcra⟧.", "I cuori di lupo che hai procurato hanno una qualità mai vista in esemplari simili. Contengono una tossicità che dovrebbe essere letale per gli stessi lupi in cui battono!\n\nÈ davvero incredibile, e dobbiamo studiarlo a fondo. Ho tenuto qualche campione dei cuori. Portali alla mia collega, la speziale Zinge. La troverai nel nostro quartier generale a ⟦Undercity=Sepulcra⟧.", "Hai qualcosa per me?", "Ah sì, i campioni di cuore di cui parlava Renferrel. Non vedo l'ora di sperimentarli... alla Royal Apothecary Society interessa sempre scoprire nuove forme di tossine.", 0xc147e9c6, 0x64dad9f3, 0x8fc4a7ce, 0xa03be4c2, 0xb2b3ed16, "....." },
  [1431] = { "Rapporti con l'⟦Alliance=Alleanza⟧", "Parla con Keldran a Orgrimmar.", "Fermati un momento, {class}, e lascia che ti riveli qualcosa di importante per il nostro popolo, ma tutt'altro che ovvio.\n\nSiamo una razza fiera, e la guerra con gli umani ha messo alla prova perfino la grande pazienza di Thrall. Vedi, il nostro Capoguerra è saggio e prudente, e continua a mettere il suo popolo al primo posto. In fondo è un diplomatico, e nel tempo passato tra gli umani ha imparato molto dei loro costumi.\n\nSe la storia che ho cominciato stuzzica il tuo interesse, allora trova Keldran vicino all'uscita occidentale della città. La sua catapecchia è lì.", nil, "Putanni, nobile {class}. Sono Keldran, studioso di magia... e di altre arti mistiche.\n\nLa faccenda per cui Craven ti ha mandato a parlarmi richiede un tocco di finezza in più di quanto ti sia servito finora, ma questo non significa che tu non possa comunque aiutare la nostra causa.\n\nTi prego, mettiti comod<o/a>, e ti spiegherò perché il Capoguerra ha bisogno del mio aiuto... e del tuo.\n\nTutto comincia dalle apparenze, {name}. Come l'⟦Horde=Orda⟧ vede se stessa. Come ci vedono i nostri alleati. E, soprattutto, come ci vedono i nostri nemici.", 0x3dfe4bf4, 0xe4927aad, 0xb8b5b27d, nil, 0x232bbca9, "...m." },
  [1432] = { "Rapporti con l'⟦Alliance=Alleanza⟧", "Parla con Takata Steelblade a ⟦Desolace=Desolanda⟧.", "Mentre l'⟦Alliance=Alleanza⟧ si spinge sempre più a fondo in Kalimdor, potrebbero trarsi conclusioni errate su presunti patti tra l'⟦Horde=Orda⟧ e la Legione Infuocata. Il Capoguerra non può permetterlo. E, con la sua benedizione, mi sto occupando di sovrintendere alla loro rimozione.\n\nHo degli agenti nella zona di ⟦Desolace=Desolanda⟧, al ⟦Ghost Walker Post=Presidio delle Ombre⟧, a nord del grande ⟦Kodo Graveyard=Cimitero dei Kodo⟧. Dirigiti a sud della ⟦Charred Vale=Valle Bruciata⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧, e lo troverai. Quando arrivi, cerca Takata Steelblade.", nil, "Salute, {class}. Porti notizie da Orgrimmar: bene.\n\nL'infestazione demoniaca opprime questa zona perfino più della puzza di sterco di centauro. Gli uomini-cavallo rivendicano questa terra come propria, ma è chiaro che ci sono influenze fuori dal loro controllo che li schiacceranno, se non vengono tenute a freno.\n\nNon mi fa piacere aiutare i centauri, sia pure indirettamente, ma è per il bene dell'⟦Horde=Orda⟧, quindi faccio il mio dovere per il Capoguerra, anche se significa aiutare gli stregoni dell'⟦Horde=Orda⟧.", 0x3dfe4bf4, 0xfa6ed566, 0xe87c4f74, nil, 0x046395cd, "...m." },
  [1433] = { "Rapporti con l'⟦Alliance=Alleanza⟧", nil, nil, nil, nil, 0x3dfe4bf4, nil, nil, nil, nil, ".mmmm" },
  [1436] = { "Rapporti con l'⟦Alliance=Alleanza⟧", "Parla con Keldran a Orgrimmar.", nil, nil, nil, 0x3dfe4bf4, 0xe4927aad, nil, nil, nil, "..mmm" },
  [1442] = { "Alla ricerca della Gemma Kor", "Porta una Gemma Kor a Thundris Windweaver a ⟦Darkshore=Rivafosca⟧.", "Salute, {name}. Cosa posso fare per chi segue un sentiero sacro?\n\nAh, sì, Stilwell, il fabbro... di tanto tempo fa. Lo ricordo bene, anche se è da un po' che non sento il suo nome.\n\nNon mi è mai sembrato un uomo insolente, quindi posso solo supporre che il suo desiderio di una Gemma Kor sia nobile.\n\nSe vuoi davvero una di queste gemme, devi andare a nord-ovest di ⟦Ashenvale=Valtetra⟧. Lì, tra antiche rovine, troverai gli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. I naga che usano ancora le gemme sono laggiù, in profondità. Non andarci da <solo/sola>, {class}.", "Mi fiderei meno di chi non segue un sentiero sacro, se venisse a chiedermi di una Gemma Kor. Ma mi fido più di quelli come te che di certi miei simili. Non giudico il tuo intero ordine dalle azioni di uno solo dei tuoi caduti.", "È proprio la gemma che Stilwell desidera, ma prima che io ti permetta di portargliela, va purificata dalla corruzione: quelle sciagurate delle naga infondono potere nelle gemme, questo è vero, ma un potere del loro genere malvagio.\n\nFa' sapere a Stilwell che il suo potere è intatto, e che dovrebbe funzionare bene per qualunque rituale in cui voglia usarla.\n\nSpero che tu sappia cosa stai facendo, {class}: non è un oggetto qualunque quello che possiedi.", 0x5d353131, 0x049bb428, 0x8e41ca81, 0x45d628b2, 0x4ca4aaaa, "....." },
  [1447] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1462] = { "⟦Earth Sapta=Sapta di Terra⟧", "Parla con la veggente Ravenfeather per avere un'altra ⟦Earth Sapta=Sapta di Terra⟧.", nil, nil, "Prendi questa e ricorda: è sacra.", 0x9c7e1740, 0xcbef76ba, nil, nil, 0x794bb81e, "..mm." },
  [1463] = { "⟦Earth Sapta=Sapta di Terra⟧", "Parla con Canaga Earthcaller per avere un'altra ⟦Earth Sapta=Sapta di Terra⟧.", nil, nil, "Te ne do una in buona fede. Hai già dato prova di te una volta, ma io penso che in futuro dovresti stare più attent<o/a>.", 0x9c7e1740, 0xb10078b8, nil, nil, 0x8882c1af, "..mm." },
  [1464] = { "⟦Fire Sapta=Sapta di Fuoco⟧", "Parla con Telf Joolam per avere un'altra ⟦Fire Sapta=Sapta di Fuoco⟧.", nil, nil, "Che il fuoco arda nel tuo cuore, {name}.\n\nGli elementi ti attendono.", 0xe8738c8b, 0xdfafed76, nil, nil, 0xeab93f1f, "..mm." },
  [1468] = { nil, nil, "Sei dispost<o/a> ad aiutarci qui all'orfanotrofio? Che tu sia benedett<o/a>, amico; il tuo aiuto durante la Children's Week sarà prezioso.\n\nPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non oltre la Children's Week stessa. Quando lo userai, potrai parlare con il bambino di cui hai accettato di occuparti. Usandolo di nuovo, il bambino se ne andrà.\n\nForza, {name}: usa il fischietto e conosci il tuo protetto! Di certo il bambino non vede l'ora di conoscerti.", nil, nil, 0x70336621, nil, 0x427476d3, nil, nil, "em.mm" },
  [1470] = { "Oltre il velo", "Porta a Venya Marthand 3 Rattlecage Skull.", "Salute, <figliolo/figliola>. Vedo che sei ancora giovane nelle vie dello stregone e che il potere ti sfugge ancora di mano. Sento il tuo desiderio di imparare.\n\nE imparerai.\n\nNon c'è forza nell'ignoranza. La conoscenza è il nostro potere più grande. Applicandola possiamo controllare le magie caotiche e gli esseri del Vuoto, piegandoli alla nostra volontà.\n\nTi mostrerò come vincolare un servitore alla tua volontà, ma prima devi portarmi tre teschi degli scheletri Rattlecage vicino alla fucina abbandonata.", "Il tuo potere ora è poca cosa, anche se sospetto che tu ne intuisca già le possibilità.\n\nPerfino i morti potrebbero sentirsi vivi, con quel potere che scorre in noi.", "Anche se sei ancora inespert<o/a> e giovane nel tuo apprendimento, hai dimostrato di possedere capacità sufficienti per padroneggiare l'evocazione e il vincolo di un imp. Non lasciarti ingannare dalle dimensioni di un imp. Anche se gli manca la forza fisica, possiede poteri e un'astuzia che ti serviranno bene.\n\nAscoltami con attenzione, {name}, perché non ripeterò questa lezione, e lascerò a te il compito di padroneggiarla.", 0x8a25b592, 0xddd91cad, 0xb55098f9, 0x14b29f22, 0x89ff488a, "....." },
  [1471] = { "Il vincolo", "Con le ⟦Runes of Summoning=Rune dell'Evocazione⟧, evoca e sottometti un'ombra del Vuoto, poi riporta le ⟦Runes of Summoning=Rune dell'Evocazione⟧ a Carendin Halgar, nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧.", "Avrai certo visto il cerchio d'evocazione sotto di noi? Solo lì potrai richiamare un'ombra del Vuoto libera da vincoli.\n\nCon queste rune potrai farla apparire, e poi dovrai dominarla con la forza delle armi e della magia.\n\nUna volta sottomessa, ti sarà vincolata. Allora vieni da me, e ti spiegherò l'incantesimo di evocazione, perché possa servirti per qualunque scopo tu voglia.", "Mi aspetto di sentir parlare del tuo successo, {name}. Ma se dovessi fallire, deludere le mie aspettative sarà l'ultima delle tue preoccupazioni.", "Hai fatto bene, {name}. Ora ti insegnerò l'incantesimo per evocare l'ombra del Vuoto.\n\nIl potere che ha scatenato contro di te ora è tuo da comandare. Usalo con saggezza.", 0x5926988f, 0xb0c8ef2d, 0x89f8824d, 0x55fcbafc, 0xc8611eae, "....." },
  [1472] = { "Divoratore di anime", "Parla con Godrick Farsan nel Temple of the Damned.", "Un sayaad è un divoratore di anime, un dominatore di volontà, un tentatore di cuori. Una creatura di profonda malvagità e di mente singolare.\n\nLe leggende popolari raccontate da giusti e malvagi usano il loro nome comune: succube per le femmine, incubo per i maschi.\n\nIl demone va attirato nel nostro mondo con un'esca: i cuori di mortali puri e amorevoli. Il sayaad non saprà resistere. Allora potrai dominarlo e farlo tuo.\n\nParla con il mio assistente, Godrick Farsan, all'interno del tempio. Ti aiuterà a trovare l'esca.", nil, "Ti manda Carendin? Allora sei {name}.\n\nNon pensare male di me perché ho perso la vista. Ora vedo le cose che stanno dietro, con una chiarezza che non avevo mai conosciuto. Quella che un tempo credevo una maledizione ora è un dono.", 0xc90e9da6, 0x8c9c2de8, 0xd89bee8d, nil, 0x4683a2b5, "...m." },
  [1473] = { "Creatura del Vuoto", "Recupera il ⟦Egalin's Grimoire=Grimorio di Egalin⟧ e portalo a Carendin Halgar, nel Temple of the Damned.", "Pare che tutti concordino: sei pront<o/a> a imparare a evocare un'ombra del Vuoto.\n\nÈ un essere nato dal caos che si stende oltre. Se ne evochi una ma non riesci a controllarla, ti farà a pezzi.\n\nLa prima ombra del Vuoto fu evocata da Egalin, e nel suo grimorio è spiegato il procedimento.\n\nPurtroppo ce l'ha rubato un agente della ⟦Scarlet Crusade=Crociata Scarlatta⟧, che lo tiene nascosto nella sua base, in una torre a ovest. Portamelo, e ti trasmetterò questo sapere.", "Egalin fu il mio maestro. Con appena uno sguardo riusciva a comandare l'ombra del Vuoto che aveva evocato.\n\nQuando venne il mio turno di provare, fui troppo sicuro di me. Non prendere alla leggera i poteri che maneggi, {name}: possono consumare anche chi è vigile.", "Ah, eccellente. Con ogni probabilità, Perrine ignorava il vero potere del libro ammuffito che ci aveva rubato.\n\nNon ci sfuggirà più di mano. Osserva, {name}, la struttura dell'incantesimo, il modo in cui il tuo potere deve essere canalizzato.", 0xb03c11f0, 0xb78fe20e, 0x67827b5f, 0x4c05983d, 0xa9462493, "....." },
  [1474] = { "Il vincolo", "Usando i ⟦Pure Hearts=Cuori Puri⟧, evoca e sottometti una succube, poi riporta i ⟦Pure Hearts=Cuori Puri⟧ a Carendin Halgar, nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧.", "Usando questi cuori, lancia un incantesimo sul cerchio di evocazione per aprire un varco da cui la succube possa passare. Ora i tuoi poteri sono più grandi, e ti serviranno tutti per sconfiggerla.\n\nGuardati dal suo fascino, {name}: molte menti forti sono state piegate al suo volere. Una volta sconfitta, la succube tornerà nel Vuoto e io ti insegnerò l'incantesimo per evocarla ai tuoi ordini.", "Tra i poteri che vengono da oltre il Vuoto, la succube è uno dei più pericolosi, perché i deboli sono i più facili da avvolgere attorno alle sue dita.\n\nRicordalo, ora e in futuro.", "Ancora una volta hai fatto un buon lavoro, {name}. È da parecchio tempo che non vedo <un/una> giovane <stregone/strega> con il tuo potenziale. Ti assicuro che continuerò a seguire i tuoi progressi e a prepararti e assisterti nelle tue prove future.\n\nPer ora, lascia che ti mostri l'incantesimo per evocare la succube che hai appena dominato.", 0x5926988f, 0xddee7319, 0x7ce3671d, 0xcfab2997, 0xf5810adb, "....." },
  [1476] = { "Cuori dei puri", "Porta i cuori di Dalin Forgewright e Corma Villard a Carendin Halgar, nel Temple of the Damned.", "Per attirare una succube serviranno i cuori dei puri. Ma esiste un mortale senza vizi?\n\nDa frammenti di storie sentite qua e là, ho trovato due umani che dovrebbero andare bene.\n\nIl primo è Dalin Forgewright, che si è dedicato alla cura dei profughi di Lordaeron, respinti dai loro stessi simili al Muro dei Mantogrigio.\n\nL'altra è Corma Villard, una donna rimasta fedele al suo amore perduto, che vaga per le ⟦Wetlands=Paludi Grigie⟧ in cerca di un suo segno.\n\nConsegna i loro cuori a Carendin. Ma prima lascia che ti mostri le tue prede.", "Finora la rapidità dei tuoi progressi mi ha piacevolmente sorpreso, {name}. Portami i cuori e mi impressionerai ancora una volta.", "Il cuore di un brav'uomo, visto così, sembra uguale a qualunque altro, non trovi?\n\nForse noi abbiamo un punto di vista un po'... diverso... sull'argomento. Comunque questi andranno bene. Non ho dubbi che una succube sarà attratta dalla loro purezza.", 0xed4dadf4, 0x458b0130, 0x6fb0be4e, 0x8c61a82d, 0x50a945bb, "....." },
  [1478] = { "La convocazione di Halgar", "Parla con Carendin Halgar a ⟦Undercity=Sepulcra⟧.", "Ah, {name}! Ho appena ricevuto un messaggio da Carendin Halgar: vuole vederti per proseguire il tuo addestramento.\n\nDovresti essere fier<o/a> di te, {name}. Non capita tutti i giorni che il maestro Halgar ritenga opportuno istruire di persona <un/una> giovane <stregone/strega>.\n\nLo troverai nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧, vicino al Temple of the Damned.", nil, "Bene, vedo che Ageron è riuscito a trovarti, {name}. Non perdiamo tempo in chiacchiere e convenevoli e concentriamoci sul tuo addestramento. Hai ancora molto da imparare.", 0xe177dd44, 0xf7495b7c, 0x60a08a74, nil, 0xe35c74a7, "...m." },
  [1483] = { nil, "Parla con Ziz Fizziks nella ⟦Windshear Crag=Landa di Tagliavento⟧.", "La ⟦Venture Company=S.P.R. & Co.⟧ ci ha rubato molte delle migliori menti goblin, ma ogni tanto abbiamo l'occasione di rubarne qualcuna indietro.\n\nTempo fa, la squadra della ⟦Venture Company=S.P.R. & Co.⟧ nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ ha assunto Gerenzo Wrenchwhistle... uno gnomo! L'altro loro ingegnere, Ziz Fizziks, ne è rimasto così sconvolto che mi ha supplicato di trovargli un nuovo impiego presso la Tinkers' Union. Gli ho affidato qualche compito, ma potrebbe aver bisogno d'aiuto.\n\nPotresti andare a vedere come se la cava, per conto mio? È di stanza al margine occidentale della ⟦Windshear Crag=Landa di Tagliavento⟧.", nil, "Pensavo che i capoccia della ⟦Venture Company=S.P.R. & Co.⟧ fossero degli schiavisti, ma poi ho conosciuto Sputtervalve, il più crudele di tutti!\n\nAh! Però è meglio che restare senza lavoro, immagino... O peggio, lavorare con quel Gerenzo. Se sei qui per dare una mano, ho qualcosa da farti fare.", 0x6cf0b999, 0xd85f0063, 0x5c119beb, nil, 0x4bc25ea8, "e..m." },
  [1484] = { nil, "Parla con Takata Steelblade a ⟦Desolace=Desolanda⟧.", nil, nil, nil, nil, 0xfa6ed566, nil, nil, nil, "m.mmm" },
  [1485] = { "Famigli vili", "Porta 6 Vile Familiar Head a Ruzan.", "Gli stregoni venuti prima di noi si sono guadagnati la diffidenza dell'⟦Horde=Orda⟧ e, anche se siamo tollerati, non siamo amati.\n\nQuesto però non ha avvicinato gli stregoni tra loro: molti scelgono di vivere in disparte, dilettandosi da soli con le loro magie. Non cercherò di condurti su un sentiero o sull'altro, ma solo di aiutarti a maturare.\n\nPrima di insegnarti l'arte dell'evocazione, portami sei teste dei famigli vili della caverna a nord-est.", "È importante che tu sappia controllare gli esseri che evochi con la tua magia. Sono già pochi quelli che vogliono diventare {class}, e non rischierei di gettare via la tua vita insegnandoti qualcosa prima che tu sia pront<o/a>.", "Durante il tuo addestramento come {class}, imparerai a richiamare esseri di molti tipi. Alcuni potrebbero non sembrarlo, ma sono tutti strumenti utili.\n\nNon farti ingannare dalle piccole dimensioni dell'imp. Come avrai senz'altro notato, è comunque un avversario temibile.", 0x8ce65439, 0x2ec68e02, 0xbf697324, 0x5b74965b, 0xa4f071a9, "....." },
  [1486] = { "Pelli deviate", "Nalpak, nella ⟦Wailing Caverns=Caverna dei Lamenti⟧, vuole 20 Deviate Hide.", "Mentre Naralex sprofondava sempre più nel suo incubo, una strana razza di bestie è emersa da sotto le ⟦Barrens=Savane⟧ nella ⟦Wailing Caverns=Caverna dei Lamenti⟧.\n\nQueste creature deviate hanno strane proprietà ultraterrene. Anche se malvagie per natura, a mio parere dalla loro presenza qui a Kalimdor può nascere qualcosa di buono. Credo che le loro pelli saranno particolarmente utili nell'arte della conciatura.\n\nSe te la senti, avventurati nelle caverne qui sotto e recupera qualche pelle deviata.", "Sono molto interessato a esaminare le pelli delle creature deviate che hanno infestato queste caverne. Hai avuto fortuna nel raccoglierne qualcuna, {class}?", "I tuoi sforzi nel raccogliere queste pelli non passeranno inosservati, {name}.\n\nGrazie per la tua dedizione.", 0x1bed65d5, 0x27d84e49, 0x3e2a3766, 0x0dcdb776, 0x715ed582, "....." },
  [1487] = { "Sterminio dei degeneri", "Ebru, nella ⟦Wailing Caverns=Caverna dei Lamenti⟧, vuole che tu uccida 7 Deviate Ravager, 7 Deviate Viper, 7 Deviate Shambler e 7 Deviate Dreadfang.", "Naralex aveva un nobile obiettivo.\n\nIl nostro grande capo aspirava a entrare nel ⟦Emerald Dream=Sogno di Smeraldo⟧ e ad aiutare queste terre aspre a tornare la foresta rigogliosa che erano un tempo. Ma qualcosa è andato terribilmente storto.\n\nIl sogno di Naralex si è trasformato in un incubo, e creature corrotte hanno cominciato a infestare le caverne.\n\nMentre alcuni discepoli di Naralex cercano di risvegliare il nostro maestro, a me preme liberare queste grotte dalle bestie malvagie.\n\nAffronta le caverne, {name}, e stermina la progenie degenere.", "{name}, noi, i discepoli di Naralex, abbiamo bisogno del tuo aiuto. Il nostro numero si assottiglia, mentre il nostro maestro è intrappolato nel suo incubo distorto. Non abbiamo le forze necessarie per affrontare le creature corrotte che ora infestano queste caverne.\n\nTi supplico, entra nelle grotte e muovi guerra alle creature degeneri!", "Come discepolo di Naralex, lodo il tuo coraggio, {name}.\n\nIl tuo aiuto nel ripulire le caverne è il primo passo della nostra lunga lotta per vedere rinascere le ⟦Barrens=Savane⟧.\n\nGrazie, e che tu possa prosperare.", 0x97d1256c, 0x65cf05d4, 0xc616bee2, 0x56e545f4, 0x09635dc9, "....." },
  [1489] = { nil, "Parla con Hamuul Runetotem", "Le conchiglie che mi hai portato hanno una contaminazione che non avevo mai visto. Non ho dubbi che la causa sia l'acqua delle Oasi, e percepisco la confusione che portano in questa terra. È come se la terra sognasse e non riuscisse a svegliarsi.\n\nLa ⟦Wailing Caverns=Caverna dei Lamenti⟧ deve essere l'origine della contaminazione. Ma prima di andarci, parla con Hamuul Runetotem, il druido anziano. Gli ho mandato notizia di ciò che accade nelle ⟦Barrens=Savane⟧. È saggio e può darti consiglio.\n\nLo troverai a ⟦Thunder Bluff=Picco del Tuono⟧, sull'⟦Elder Rise=Altura degli Anziani⟧.", nil, "Ti saluto, {name}. Sei <il/la> <benvenuto/benvenuta> qui, e ti consiglio di raccogliere tutte le tue forze. Perché il compito che ora ti affidiamo... è terribile.", 0x034c803e, 0x658f0ea3, 0x9a855028, nil, 0x4f036dc1, "e..m." },
  [1490] = { nil, "Parla con Nara Wildmane.", "Sono entrato nella terra dei sogni e ho sognato una setta di druidi che dimorano nella ⟦Wailing Caverns=Caverna dei Lamenti⟧. Ho visto che un tempo i loro scopi erano nobili, ma hanno smarrito la via. Ora sono servi della contaminazione che si diffonde nelle ⟦Barrens=Savane⟧.\n\nSono vecchio e le forze mi abbandonano. Non ho potuto restare a lungo in quel luogo di sogno e so poco di più dei druidi corrotti. Ma Nara è giovane e il suo spirito è fiero. È rimasta nel sogno quando io sono fuggito.\n\nParla con Nara. È nella tenda, laggiù.", nil, "Sì, è vero. Conosco i druidi della ⟦Wailing Caverns=Caverna dei Lamenti⟧. Ho visto i loro volti deformi e squamosi. Conosco i loro crimini e conosco i loro piani.\n\nDevi fermarli, {name}.", 0xa9a75b81, 0x236c53c8, 0xdac1c62f, nil, 0xcfbd0a8a, "e..m." },
  [1491] = { "Bevande intelligenti", "Porta 6 porzioni di ⟦Wailing Essence=Essenza Lamentosa⟧ a Mebok Mizzyrix, a ⟦Ratchet=Porto Paranco⟧.", "Va bene, i corni di raptor non hanno funzionato granché. Ma non importa: nessuno è mai diventato ricco al primo tentativo! E poi credo di aver trovato qualcosa che funzionerà ancora meglio nelle mie bevande intelligenti!\n\nC'è una sostanza chiamata ⟦Wailing Essence=Essenza Lamentosa⟧, e credo che sia la causa delle strane piante e degli strani animali delle ⟦Barrens=Savane⟧. Procuramene un po' e la proverò nella mia bevanda!\n\nHo sentito che l'essenza si accumula nelle creature ectoplasmatiche della ⟦Wailing Caverns=Caverna dei Lamenti⟧, a ovest. Dà la caccia a quelle creature e raccogli l'essenza.", "Dov'è la mia essenza lamentosa?", "Fantastico, ce l'hai fatta! Non vedo l'ora di provarla. Mi farà fare una fortuna, me lo sento!\n\nGrazie, {name}. Prendi questo, e quando sarò ricco te ne manderò dell'altro, promesso!", 0x3bd3c186, 0x92e0631f, 0x440930e0, 0x1ed90584, 0x985f6f88, "....." },
  [1492] = { "Il capo del porto Dizzywig", "Porta la ⟦Secure Crate=Cassa Sicura⟧ al capo del porto Dizzywig, a ⟦Ratchet=Porto Paranco⟧.", "Devo spedire una cassa di pozioni, reagenti e altri oggetti ai miei soci nel Vecchio Mondo. Ho poco tempo per accompagnarla di persona al molo di ⟦Ratchet=Porto Paranco⟧, e l'ultima carovana è già partita.\n\nSe puoi, porta questa al capo del porto Dizzywig. Si assicurerà che venga caricata sulla prossima nave per la ⟦Blackwater Cove=Baia degli Acquanera⟧.", "Cerchi un passaggio sulla prossima nave, o hai qualcosa che vuoi mandare a bordo?", "Una cassa abbastanza piccola. Sì, dovrei riuscire a trovarle posto a bordo della nave. Salpa con la prossima marea, confido che sia abbastanza presto? Eccellente. Lascia solo che la registri nel mio libro mastro.\n\nTutto sistemato! Buona giornata, {class}.", 0x68543425, 0x17f5da95, 0xb65ac0a7, 0x189f5df8, 0xd447e508, "....." },
  [1498] = { "La via della difesa", "Porta 5 Scaglie Strinate a Uzzek, al ⟦Far Watch Post=Presidio Lungosguardo⟧ nelle ⟦Barrens=Savane⟧.", "Per un guerriero, uno dei compiti più importanti è... la protezione. Noi siamo lo scudo dell'⟦Horde=Orda⟧ e proteggiamo i nostri fratelli più deboli. Se vuoi unirti ai nostri ranghi, devi dimostrarmi il tuo valore.\n\nVa' alla ⟦Thunder Ridge=Fossa del Tuono⟧, a Durotar, dove vivono i sauri del fulmine e i sauri del tuono. Dà la caccia a quelle bestie! Dimostrami che sei più dur<o/a> di loro! Resisti ai loro assalti e portami un mucchio delle loro scaglie strinate come prova.\n\nFallo, e allora ti insegnerò.", "Hai le scaglie, {name}? Se non sai resistere agli attacchi dei sauri del tuono, i miei insegnamenti non ti serviranno.", "Ah. Vedo che hai sconfitto i sauri del tuono, il che dimostra che sei resistente. Ora ti mostrerò come una pelle dura e movimenti accorti possono unirsi per formare un muro di difesa impenetrabile.\n\nImpara bene la lezione, {name}. E tieniti pront<o/a> per i prossimi insegnamenti.", 0xd3cf9699, 0x7867009f, 0xda36a73f, 0x7db1e33a, 0x88e15585, "....." },
  [1499] = { "Famigli vili", "Parla con Zureetha Fargaze.", "Zureetha manda novizi come te ad aiutare a sfoltire le creature della caverna vicino al punto in cui hai combattuto i famigli vili.\n\nCredo che ti farebbe bene fare esperienza aiutandola. Dille che hai dato una mano con il problema degli imp: probabilmente avrà una ricompensa per te.", nil, "Hai fatto bene, {name}.\n\nAnche se i famigli vili erano solo semplici famigli al servizio dei poteri più oscuri delle ⟦Burning Blade=Lame Ardenti⟧, il tuo successo contro di loro preannuncia imprese più grandi.", 0x8ce65439, 0x71f688ac, 0xd440d0c7, nil, 0x1dac4028, "...m." },
  [1500] = { "Il risveglio di Naralex", nil, nil, nil, nil, 0x7c8df543, nil, nil, nil, nil, ".mmmm" },
  [1501] = { "Creatura del Vuoto", "Recupera la ⟦Tablet of Verga=Tavoletta di Verga⟧ per Gan'rul Bloodeye, a Orgrimmar.", "Sono rimasti così pochi stregoni... Rischiamo molto, ma i rischi sono giustificati. Devi raggiungere in fretta la piena maturità delle tue capacità, se vuoi essere utile all'⟦Horde=Orda⟧ e al Capoguerra.\n\nÈ ora che tu impari un nuovo incantesimo di evocazione.\n\nPrima devi recuperare la ⟦Tablet of Verga=Tavoletta di Verga⟧, rubata dagli stregoni delle ⟦Burning Blade=Lame Ardenti⟧ e ora custodita nel loro covo alla ⟦Skull Rock=Roccia del Teschio⟧, a est della città. Con la tavoletta ti mostrerò le rune necessarie per evocare un'ombra del Vuoto.", "Hai la ⟦Tablet of Verga=Tavoletta di Verga⟧, {name}? Se non ce l'hai, non voglio parlare con te finché non l'avrai.", "Bene. Spero che tu abbia inflitto qualche altra perdita alle ⟦Burning Blade=Lame Ardenti⟧ quando sei <andato/andata> a recuperarla.\n\nSono state una grande seccatura per il Capoguerra e una vera piaga per tutti gli stregoni.", 0xb03c11f0, 0xba21a12c, 0x041f9a8c, 0xac90ab1b, 0xa45dabc8, "....." },
  [1502] = { nil, "Parla con Thun'grim Firegaze nelle ⟦Barrens=Savane⟧.", "È fondamentale che l'arma di un guerriero sia di qualità. E se c'è un orco capace di forgiare armi di qualità, quell'orco è Thun'grim Firegaze. È un eremita che vive in cima alle colline a est del ⟦Crossroads=Crocevia⟧.\n\nSe cerchi un'arma, <guerriero/guerriera>, devi cercare Thun'grim. Per trovarlo, va' prima al ⟦Crossroads=Crocevia⟧, a ovest, poi dirigiti a est verso le colline. Il suo accampamento è in alto, su una collina.", nil, "I miei occhi si sono seccati da tempo a forza di fissare la fiamma della forgia, ma qualcosa riesco ancora a vederlo. Vedo che vuoi qualcosa.\n\nE se hai trovato la strada fin qui, posso indovinare cosa desideri.", 0xc4560ed6, 0xb0a44244, 0xdaa37c45, nil, 0x8b035e5e, "e..m." },
  [1503] = { "Acciaio forgiato", "Porta i ⟦Forged Steel Bars=Lingotti d'Acciaio Forgiato⟧ a Thun'grim Firegaze, nelle ⟦Barrens=Savane⟧.", "Ti darò un'arma, {name}, ma prima devi aiutarmi. I Chiomaguzza a nord-ovest sono entrati nel mio accampamento qualche notte fa. Non hanno voluto affrontarmi in combattimento, ma sanno che ho la vista debole: alcuni mi hanno distratto con i loro grugniti mentre altri mi derubavano! Codardi!\n\nHanno preso una cassa di ferro, e dentro c'erano dei lingotti d'acciaio forgiato. Se riesci a recuperarli, ti darò l'arma che cerchi.\n\nCerca la cassa di ferro negli accampamenti dei verrospini e torna con i lingotti d'acciaio forgiato.", "Hai i miei lingotti d'acciaio?", "Li hai trovati! E ci sono tutti i lingotti, il che non mi sorprende. Non pensavo che i Chiomaguzza sapessero cosa farsene di un acciaio pregiato come questo.\n\nGrazie, {name}. Ecco la tua ricompensa. Che ti serva bene.", 0xf63daa21, 0x537f8286, 0xe1ba1ae1, 0x59a53ecc, 0x748375a3, "....." },
  [1504] = { "Il vincolo", "Usando i ⟦Glyphs of Summoning=Glifi dell'Evocazione⟧, evoca e sottometti un'ombra del Vuoto, poi riporta i ⟦Glyphs of Summoning=Glifi dell'Evocazione⟧ a Gan'rul Bloodeye, a Orgrimmar.", "Ora osserva la ⟦Tablet of Verga=Tavoletta di Verga⟧, perché contiene i glifi che ti serviranno per l'evocazione. Portali al cerchio nella tenda di Neeru Fireblade, dall'altra parte della caverna. Lì potrai richiamare l'ombra del Vuoto.\n\nDovrai sconfiggerla con tutti i mezzi fisici e magici a tua disposizione. Fatto questo, torna da me con i glifi dell'evocazione e ti mostrerò come piegare la creatura al tuo volere.", "L'ombra del Vuoto è una creatura potente. Ricordo quando ero io al tuo posto, {name}. Con gli anni, la mia ombra del Vuoto ha imparato a combattermi meno, anche se sospetto che sia solo perché spera che io abbassi la guardia.\n\nRicordatelo, {name}.", "Hai fatto bene, {name}. Ti mostrerò come evocare un'ombra del Vuoto simile a quella che hai appena sconfitto.\n\nDevi sapere che abbiamo grandi aspettative su di te e che finora le hai soddisfatte.\n\nMa non montarti la testa, perché i compiti che ancora ti attendono faranno sembrare questo semplice come svegliarsi al mattino.", 0x5926988f, 0x127c523e, 0x0b393cbb, 0xbd139f64, 0x6a8e44d2, "....." },
  [1505] = { "Il veterano Uzzek", "Parla con Uzzek al ⟦Far Watch Post=Presidio Lungosguardo⟧.", "L'⟦Horde=Orda⟧ onora i suoi guerrieri perché la loro forza è indiscussa. Ma i guerrieri davvero grandi sono anche grandi allievi.\n\nCerca Uzzek. È un veterano di molte battaglie e ora istruisce i giovani guerrieri nell'arte del combattimento. Lo troverai a sud del ⟦Far Watch Post=Presidio Lungosguardo⟧, la guarnigione degli orchi al confine tra le ⟦Barrens=Savane⟧ e Durotar, a est.", nil, "Salve, giovane. Sei qui per un po' di addestramento, vero?", 0x365c7a94, 0x93d0830e, 0x5f80517e, nil, 0xf9b5711a, "...m." },
  [1506] = { "La convocazione di Gan'rul", "Parla con Gan'rul Bloodeye a Orgrimmar.", "Ehi, tu. {name}, giusto?\n\nSpero che tu non abbia troppi impegni, perché Gan'rul vuole vederti subito. Lo troverai con gli stregoni anziani nel Cleft of Shadow.\n\nA giudicare da come sono andate le cose tra me e Gan'rul in passato, questa convocazione è o un'ottima cosa o una pessima cosa.", nil, "Bene. Temevo che Ophek non riuscisse a raggiungerti.\n\nÈ ora che io prosegua il tuo addestramento da stregone. Qualunque faccenda tu abbia in corso dovrà aspettare.\n\nConfido che questo non sarà un problema.", 0x45c24282, 0x52eba0f6, 0xea7dba0a, nil, 0xe1bee51f, "...m." },
  [1507] = { "Divoratore di anime", "Parla con Cazul nel Cleft of Shadow.", "È giunto il momento che tu impari di più sulle magie di evocazione. Imparerai a evocare un sayaad, una creatura dai poteri mentali incredibili. Può soggiogare le menti deboli e ridurle in servitù... ma non temere! Sono certo che sarai all'altezza della sfida.\n\nUn sayaad si può evocare solo attirandolo con un oggetto che rappresenti grande devozione e amore. Lascio a te il compito di trovarlo.\n\nUn consiglio? Parla con Cazul... Sembra che ci sia ben poco che l'antico stregone non sappia.", nil, "Mmm... {name}. Sei ancora all'inizio del tuo cammino, ma sento in te la possibilità della grandezza.\n\nSei nat<o/a> con dei doni, {name}. Fa' in modo che non vadano sprecati.", 0xc90e9da6, 0x0892f9ee, 0x6a5a0197, nil, 0x0b0ec202, "...m." },
  [1508] = { "Cazul il cieco", "Parla con Zankaja a Orgrimmar.", "Se Gan'rul ti ha mandato da me, significa che devi evocare una succube, una femmina della razza dei sayaad, e ti serve un oggetto con cui attirarla.\n\nMmm... Se ti fidi di un cieco come guida, {name}, allora ascolta. Sulle alture di Orgrimmar, a ovest della torre delle viverne, vive Zankaja. Aspetta il ritorno del suo compagno.\n\nVa' da lei.", nil, "Sei venut<o/a> con notizie di Dogran? Doveva tornare giorni fa, e non ho saputo nulla...", 0x4b8d82bc, 0xab264922, 0xdc04a746, nil, 0xc30ee2c1, "...m." },
  [1509] = { "Notizie di Dogran", "Parla con Gazrog a ⟦Crossroads=Crocevia⟧.", "Il mio compagno, Dogran, è stato mandato da poco in servizio a ⟦Crossroads=Crocevia⟧. Era una promozione, e ne andava molto fiero.\n\nIo ero triste, naturalmente, ma non gliel'ho fatto capire. E anche preoccupata. Le ⟦The Barrens=Savane⟧ sono un posto più pericoloso di Orgrimmar, e temevo il peggio.\n\nOra è passata una settimana da quando sarebbe dovuto tornare, e non ho ricevuto sue notizie...\n\nForse potresti andare a ⟦Crossroads=Crocevia⟧ a vedere se hanno notizie? Lavorava con Gazrog, che dovrebbe essere ancora di stanza lì.", nil, "Zankaja? È la compagna di Dogran, giusto?\n\nSì, ho avuto sue notizie, ma non sono il tipo di notizie che dovremmo far arrivare a lei...\n\nNo, non è morto. Ma è ferito e prigioniero dei verrospini.", 0x38116f43, 0x1552029b, 0x075a7321, nil, 0x0ed15c17, "...m." },
  [1510] = { "Notizie di Dogran", "Parla con Ken'zigla a Malaka'jin.", "Era di stanza a Camp Taurajo, dove stiamo cercando di sradicare i verrospini. Ha guidato alcuni grunt contro uno dei loro accampamenti, dove è stato ferito gravemente. Gli altri sono riusciti a tornare e hanno cercato di salvarlo. Era messo male, le ferite si erano infettate, e temevano di spostarlo senza prima averlo rattoppato.\n\nHanno mandato un messaggio qui, chiedendo un decotto curativo ai troll di Malaka'jin, ai piedi delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧. Abbiamo mandato qualcuno a prenderlo, ma non è ancora tornato.", nil, "Un altro orco, eh? Spero che tu non sia venut<o/a> per l'altro. Non ce l'ha fatta. Quei goblin l'hanno sistemato per bene.\n\nHa detto che gli serviva un decotto curativo, ma non molto altro.", 0x38116f43, 0x274e05fb, 0x8e29736f, nil, 0xc87ee0e8, "...m." },
  [1511] = { "⟦Ken'zigla's Draught=Bevanda di Ken'zigla⟧", "Porta la ⟦Ken'zigla's Draught=Bevanda di Ken'zigla⟧ al grunt Logmar, a Camp Taurajo.", "Me lo immaginavo che sarebbe venuto qualcun altro a prendere il decotto, così l'ho preparato comunque.\n\nEcco qua, {name}. Bada, devi dargliene solo metà! Gli darà abbastanza forza per muoversi senza dissanguarsi. Aspetta una notte, poi dagli l'altra metà.\n\nComunque, dovrai portarlo a Logmar, a Camp Taurajo. Da quanto mi ha detto il primo, lui dovrebbe sapere dove si trova questo Dogran.", "Sì, che c'è?", "Be', era ora! Dogran sta morendo là fuori, aspettando questo.\n\nDobbiamo farglielo avere subito, ma quasi tutti i grunt di stanza qui sono fuori in missione di approvvigionamento.", 0xa5e7e1b3, 0xf17fda61, 0x719c82c7, 0xb4a62c76, 0xb7888e5f, "....." },
  [1512] = { "Il dono dell'amore", "Porta il Dirt-caked Pendant a Gan'rul Bloodeye, a Orgrimmar.", "Zankaja è giovane e bella. Essere incatenata a un invalido... Non le permetterò di subire questa ingiustizia.\n\nLasciami, {name}. E grazie. Potrò porre fine alla mia vita in una battaglia gloriosa, invece che come un guscio senza vita.\n\nE ti prego, non dire niente di tutto questo alla mia compagna... Non voglio che abbia sensi di colpa sulla coscienza.", "Sei tornat<o/a>. Sei pront<o/a> ad affrontare una succube?", "Se mi dici che basterà, allora mi fido di te, {name}. Lascia però che lo pulisca... Immacolato e splendente, potrebbe essere ancora più allettante per una succube.", 0xbe13511d, 0x30cfa262, 0x4113689c, 0xe4777579, 0xae4f2aa0, "....." },
  [1513] = { "Il vincolo", "Usando il ⟦Dogran's Pendant=Pendente di Dogran⟧, evoca e sottometti una succube, poi riporta il ⟦Dogran's Pendant=Pendente di Dogran⟧ a Gan'rul Bloodeye, a Orgrimmar.", "Porta questo al cerchio di evocazione nella tenda di Neeru, {name}. Evoca un'immonda succube, poi mostrale la tua padronanza. Credo nella forza della tua magia. Ma come sempre, stai in guardia, perché l'orgoglio e l'eccesso di sicurezza hanno sopraffatto molti stregoni promettenti.\n\nQuando l'avrai sconfitta, riportami il pendente, così potrò dare la notizia a Zankaja.", "Quando guardo una succube, il mio cuore prende il volo... Ma al tempo stesso sento quasi la mia anima rifluire, allontanarsi come la marea.\n\nStai in guardia, amico mio.", "Successo! Ti assicuro che non mi aspettavo niente di meno dal <mio/mia> <allievo/allieva> migliore.\n\nHai dimostrato il tuo valore, e ti mostrerò volentieri il metodo per evocare la succube che hai sottomesso. Ora va', hai molto da imparare, e la prossima volta che ti vedrò mi aspetto che tu abbia raggiunto la vera padronanza della tua succube.\n\nLascia il dolore di Dogran e Zankaja a quelli di noi che hanno più anni sulle spalle, ma ricordalo, e tienilo come protezione contro le lusinghe del potere oscuro che oggi hai imparato a evocare.", 0x5926988f, 0xa3846b0b, 0xcbb4f07d, 0x60f275cd, 0x5e6deefa, "....." },
  [1515] = { "La prigionia di Dogran", "Porta la ⟦Ken'zigla's Draught=Bevanda di Ken'zigla⟧ a Dogran, nelle ⟦Barrens=Savane⟧.", "Sei arrivat<o/a> fin qui, quindi se vuoi andare fino in fondo non ti fermerò. Però non posso darti altri uomini, sarai da sol<o/a>.\n\nDogran è tenuto prigioniero in un accampamento di verrospini a nord di qui. Cerca un gruppo di due capanne. Sarà sorvegliato a vista... sempre che non l'abbiano già ucciso o che non sia morto per le ferite.\n\nBuona fortuna.", nil, "Che intruglio disgustoso...\n\nOra sento la forza in me, abbastanza per allontanarmi zoppicando... Ma la gamba l'avrò persa per il resto della vita. E anche il braccio.", 0xb9c2abe8, 0xd92b478b, 0xd3ece112, 0xec7d2401, 0x5eda9561, "...e." },
  [1516] = { "Il richiamo della terra", "Porta 2 Felstalker Hoof a Canaga Earthcaller nella ⟦Valley of Trials=Valle delle Sfide⟧.", "È giunto il momento, giovane {class}. Sei diventat<o/a> forte e il tuo spirito resiste come la terra. Seguire il sentiero dello sciamano dimostra che hai saggezza ancor prima di aver dato prova di te.\n\nL'elemento della terra guiderà il tuo destino e diventerà parte di te, se sei pront<o/a>. Ma dovrai presentarti al cospetto della terra stessa. Se sei pront<o/a>, vedrai cose che solo gli sciamani conoscono.\n\nCerca i Felstalker a nord e prendi loro due zoccoli. Poi torna da me e parleremo ancora del tuo futuro.", "La pazienza è la virtù più grande della terra. La terra è testimone del ciclo di tutte le cose: le montagne che diventano deserti, i fiumi che diventano canyon. La terra è il più ostinato e saggio di tutti gli elementi, e non tollera l'impazienza.\n\nLa terra ora ti chiama perché si avvicina un tempo di conflitto. Quando tornerai da me dopo aver avuto successo, sarai molto più vicin<o/a> a essere complet<o/a>.\n\nAltri invidieranno la tua saggezza e ti odieranno per la loro ignoranza.", "Eccellente. Il tuo successo dimostra che sei pront<o/a>.\n\nDi tutti gli elementi, la terra rappresenta il fondamento di tutte le cose. È la tua forza, la tua resistenza e la tua pazienza. La terra ti proteggerà, ma solo se le mostrerai il giusto rispetto. Come gli altri elementi, anche la terra può essere volubile. La terra è la base della vita e, osservandone le leggi, otterrai una saggezza più grande. Non dimenticare mai i segreti che la terra condivide con te.\n\nOra preparerò per te una sapta e, accettandola, comprenderai il tuo sentiero.", 0xe316c17f, 0x38769ca5, 0x569e02d2, 0x96dc0c6e, 0x2b537118, "....." },
  [1517] = { "Il richiamo della terra", "Trova la ⟦Spirit Rock=Roccia dello Spirito⟧ e bevi la ⟦Earth Sapta=Sapta di Terra⟧.", "Una sapta è una bevanda creata per legare il nostro spirito agli elementi. Infusa di magia, la pozione permette a chi ha una volontà forte di vedere gli elementi come nessun altro può. Il tuo spirito sarà legato all'elemento per cui la sapta è stata creata, e solo pochi sciamani scelti ne conoscono la ricetta.\n\nLa sapta si beve sempre in un luogo sacro, e mai altrove: ricordalo.\n\nCerca la ⟦Spirit Rock=Roccia dello Spirito⟧ a sud-ovest di qui: si trova alla fine del ⟦Hidden Path=Sentiero Nascosto⟧. Bevi lì la tua sapta, e... be', vedrai.", nil, "Ah... {name}... la terra è lieta di averti qui.\n\nCon il corpo e lo spirito uniti a lei, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso, la tua essenza.\n\nPresentarti con umiltà davanti alla terra è tutto ciò che ti è richiesto per superare questo rito. Ma gli altri non sono altrettanto passivi. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature duplici che si oppongono l'una all'altra: dovrai imparare a conoscerle a fondo.", 0xe316c17f, 0xa13b2e9f, 0x3a9eb51f, nil, 0x63c94008, "...m." },
  [1518] = { "Il richiamo della terra", "Porta il ⟦Rough Quartz=Quarzo Grezzo⟧ a Canaga Earthcaller nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Prendi da me questo quarzo grezzo e portalo a Canaga Earthcaller come prova del nostro incontro. Creerà per te un totem, e questo sassolino ne sarà il cuore. Per quanto piccolo possa sembrare, scoprirai che la grandezza non conta, e che anche la più piccola delle cose può durare più di molte altre.\n\nSii paziente, {name}. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra: rispettala, come lei rispetterà te.", "Desidero essere il primo a darti il benvenuto, a pieno titolo, sul primo dei quattro sentieri che guideranno per sempre il tuo destino.\n\nSe hai la pietra che la terra ti ha dato, ti darò il totem che ti ha promesso.\n\nAltrimenti vattene, finché non avrai trovato la tua strada.", "Eccellente!\n\nIl totem che creerò per te è più di un simbolo del tuo rango di {class}: ha anche altri poteri. Uno degli usi del totem è come focus per gli incantesimi. Quegli incantesimi sono legati alla terra e, man mano che acquisirai sempre più saggezza, ti saranno resi accessibili altri poteri della terra.\n\nGli istruttori sapranno quando sarai pront<o/a> per conoscenze più grandi.\n\nMa per ora prendi questo totem della terra e una pergamena che ti insegnerà la tua prima abilità.", 0xe316c17f, 0x54eec492, 0xaf707d12, 0x193d5207, 0x5ffb2e61, "....." },
  [1519] = { "Il richiamo della terra", "Porta 2 dosi di ⟦Ritual Salve=Balsamo Rituale⟧ alla veggente Ravenfeather a ⟦Camp Narache=Campo Narache⟧.", "È giunto il momento, giovane {class}. Il tuo corpo matura e si fa forte, e il tuo spirito resiste come la terra. Lo vedo dentro di te: possiedi già la saggezza.\n\nLa terra guida il nostro popolo e ci parla, come col tempo parlerà a te. Ma devi essere mess<o/a> alla prova. Se sei pront<o/a>, vedrai cose che solo quelli della nostra stirpe conoscono.\n\nCerca gli sciamani ⟦Bristleback=Mantotergo⟧ nella loro depressione a est e prendi loro un balsamo che usano nei loro rituali. Torna da me solo quando ne avrai abbastanza per la tua pozione.", "La terra è paziente e ti aspetterà finché non sarai pront<o/a>, perché sa che col tempo tutte le cose si erodono e rinascono. È il ciclo delle cose. Le montagne diventano deserti. I fiumi diventano canyon. La terra è il più ostinato e saggio di tutti gli elementi.\n\nSopra ogni cosa devi imparare la pazienza e la resistenza. La terra ora ti chiama perché sente che sei pront<o/a>. Se ci riuscirai, considera questa la tua rinascita. Dopo, non potrai mai più tornare all'ignoranza.", "Bene, {name}. Il tuo ritorno qui significa che sei davvero pront<o/a> per il passo successivo.\n\nDi tutti gli elementi, la terra rappresenta il fondamento di tutte le cose. È la tua forza, la tua resistenza e la tua pazienza. La Madre Terra ti proteggerà, ma solo se le mostrerai il giusto rispetto. Lei è la base della vita e, osservando le sue leggi, otterrai una saggezza più grande. Non dimenticare mai i segreti che condivide con te.\n\nOra preparerò per te la tua sapta e, accettandola, un nuovo sentiero si aprirà davanti a te.", 0xe316c17f, 0x78a5e6e9, 0xa9b6ebaa, 0x155e3f35, 0x1bb9c4df, "....." },
  [1520] = { "Il richiamo della terra", "Trova la ⟦Kodo Rock=Roccia dei Kodo⟧ e bevi la ⟦Earth Sapta=Sapta di Terra⟧.", "Una sapta è una bevanda creata per legare il nostro spirito agli elementi. Infusa di magia, la pozione permette a chi ha la mente aperta di vedere gli elementi come nessuno li ha mai visti. Il tuo spirito resterà legato per sempre all'elemento per cui la sapta è stata creata, e solo pochi della nostra stirpe conoscono i segreti della sua preparazione.\n\nLa sapta si beve sempre in un luogo sacro, e mai altrove.\n\nCerca il santuario degli sciamani a est di qui e bevi la sapta.", nil, "Ah... {name}... la terra è lieta di averti qui.\n\nCon il corpo e lo spirito uniti a lei, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso, la tua essenza.\n\nPresentarti con umiltà davanti alla terra è tutto ciò che ti è richiesto per superare questo rito. Ma gli altri non sono altrettanto passivi. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature duplici che si oppongono l'una all'altra: dovrai imparare a conoscerle a fondo.", 0xe316c17f, 0xedfdb7bf, 0x9ec79348, nil, 0x63c94008, "...m." },
  [1521] = { "Il richiamo della terra", "Porta il ⟦Rough Quartz=Quarzo Grezzo⟧ alla veggente Ravenfeather a ⟦Camp Narache=Campo Narache⟧.", "Prendi da me questo quarzo grezzo e portalo alla veggente Ravenfeather come prova del nostro incontro. Creerà per te un totem, e questo sassolino ne sarà il cuore. Per quanto piccolo possa sembrare, scoprirai che la grandezza non conta, e che anche la più piccola delle cose può durare più delle montagne.\n\nSii paziente, {name}. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra: rispettala, come lei rispetterà te.", "Salute, {name}. Non torneresti da me se non avessi portato a termine il tuo compito. Lascia che sia la prima a darti il benvenuto, a pieno titolo, sul primo dei quattro sentieri che governeranno per sempre i tuoi viaggi.\n\nSe hai la pietra che la terra ti ha dato, ti darò il totem che ti ha promesso. Altrimenti, provo pena per te. C'è molto di cui andare fieri quando ci si è dedicati completamente agli elementi.", "Splendido.\n\nIl totem che creerò per te è più di un simbolo: ha anche altri poteri. Uno degli usi del totem è come focus per gli incantesimi. Quegli incantesimi sono legati alla terra e, man mano che acquisirai sempre più saggezza, ti saranno resi accessibili altri poteri della terra. Gli istruttori che si trovano in tutto Kalimdor sapranno quando sarai pront<o/a> per conoscenze più grandi e te lo faranno sapere quando andrai da loro.\n\nMa per ora prendi questo totem della terra...", 0xe316c17f, 0x9f97d72d, 0x8bafa0d9, 0x86fa5bbc, 0x00323f04, "....." },
  [1522] = { "Il richiamo del fuoco", "Trova Kranal Fiss nelle ⟦Barrens=Savane⟧.", "Il fuoco sta con te, amico. Vedo che sei già forte nelle vie della terra, e io penso che sei pront<o/a> per parlare con Kranal.\n\nKranal vive a nord del ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧. È forte nelle vie degli elementi e può insegnarti le vie del fuoco... se pensi di essere pront<o/a>.\n\nÈ facile trovarlo, basta che non vai troppo lontano: se vai troppo lontano ti ritrovi nelle terre degli elfi.", nil, "Mmm, ti manda Searn, eh?\n\nBene, di Searn ci si è sempre potuti fidare, quindi vuol dire che sei pront<o/a> a prendere parte al prossimo sapta, il sapta del fuoco.\n\nLo vedo già nei tuoi occhi, l'ardore, il desiderio. Hai assaggiato il potere, e ora sei pront<o/a> a riceverne di più. Pazienza, {name}. Ricorda cosa ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.", 0x53f3b76b, 0xb1158d84, 0xf2febdb9, nil, 0xe2471546, "...m." },
  [1523] = { "Il richiamo del fuoco", "Trova Kranal Fiss nelle ⟦Barrens=Savane⟧.", "È passato molto tempo dall'ultima volta che sei <stato/stata> mess<o/a> alla prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. L'elemento del fuoco è tuo da comprendere, se sei pront<o/a> a pagarne il prezzo.\n\nCerca Kranal Fiss nelle ⟦Barrens=Savane⟧. Vive in una piccola dimora a nord del ⟦Crossroads=Crocevia⟧, ma fa' attenzione: se sei arrivat<o/a> nelle terre degli elfi della notte, sei andat<o/a> troppo lontano.", nil, "Mmm, ti ha mandato Narm da me, vero?\n\nBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei pront<o/a> a prendere parte alla prossima sapta: la sapta del fuoco.\n\nLo vedo già nei tuoi occhi, l'ardore, il desiderio. Hai assaggiato il potere e ora ne vuoi ancora. Pazienza, {name}. Ricorda ciò che ti ha insegnato la terra. Potere e distruzione arriveranno facilmente, ma devi comunque sapere quando trattenere la mano.", 0x53f3b76b, 0xb1158d84, 0x0f02e651, nil, 0xd20cd47c, "...m." },
  [1524] = { "Il richiamo del fuoco", "Porta la ⟦Torch of the Dormant Flame=Torcia della Fiamma Sopita⟧ a Telf Joolam, a Durotar.", "Sei abbastanza potente da impugnare il totem del fuoco, ma questo non significa che tu sia <pronto/pronta>.\n\nLungo il ⟦Southfury River=Fiume Furialunga⟧, a Durotar, prima del Grande Mare, c'è un sentiero nascosto che porta a una delle vette più alte della regione. Trova la strada fino in cima e troverai uno dei nostri santuari sacri, sorvegliato da Telf Joolam: il ⟦Shrine of the Dormant Flame=Santuario della Fiamma Sopita⟧.\n\nPortagli questa torcia: indica che stai tentando di domare il fuoco. Riportamela accesa al braciere del santuario e farò in modo che ti venga dato il totem del fuoco.", "Salute, {name}. Sei <giunto/giunta> al ⟦Shrine of the Dormant Flame=Santuario della Fiamma Sopita⟧. Solo chi è abbastanza esperto nelle arti sciamaniche potrà mai conoscere i segreti di questo luogo e il potere che custodisce. Mi dispiace che tu abbia fatto tutta questa strada solo per essere <rimandato/rimandata> indietro, dopotutto il viaggio fin quassù è tutt'altro che sicuro, ma sono il custode del santuario e non posso permettere a chiunque di aggirarsi da queste parti.", "Ah, errore mio, {name}. Ti chiedo scusa. Non mi ero accorto che possedessi la Torcia. Sono lieto di fare la tua conoscenza.\n\nMolti avventurieri arrivano fin qui in cerca di tesori perduti o attratti dalla promessa di creature mistiche da uccidere, solo per essere respinti da un santuario apparentemente vuoto. Ma noi conosciamo la verità, non è così, {name}?\n\nQuesto santuario cela un segreto più grande ai membri comuni dell'⟦Horde=Orda⟧. Per noi è sacro.", 0x53f3b76b, 0x754469c8, 0xb7ad9777, 0x2af3079b, 0x7705d50c, "....." },
  [1525] = { "Il richiamo del fuoco", "Porta 1 ⟦Fire Tar=Catrame di Fuoco⟧ e 1 ⟦Reagent Pouch=Borsa dei Reagenti⟧ a Telf Joolam, in Durotar.", "Ma non sei venut<o/a> qui per una lezione di storia, vero? Sei venut<o/a> per la Fiamma Eterna e il totem del fuoco.\n\nIl primo passo è creare una sapta e legarti alla fiamma.\n\nPosso creare per te la sapta del fuoco se mi porti due oggetti. Il primo è il catrame di fuoco, un oggetto semplice che di solito portano gli incantatori ⟦Razormane=Chiomaguzza⟧ nelle ⟦Barrens=Savane⟧ orientali.\n\nIl secondo oggetto sarà più pericoloso da ottenere: una borsa dei reagenti da uno dei cultisti delle ⟦Burning Blade=Lame Ardenti⟧. Li trovi in una grotta sopra le gole a nord-est di ⟦Razor Hill=Tranciacolle⟧.", "Ho abbastanza ingredienti per una sapta del fuoco, se trovi la borsa dei reagenti e un po' di catrame di fuoco. I fanatici delle ⟦Burning Blade=Lame Ardenti⟧ tengono in quelle borse i componenti giusti per la maggior parte dei loro incantesimi, e di solito hanno abbastanza degli oggetti che mi servono da non doverci spingere molto oltre per cercare altro.\n\nLe sapta si fanno sempre con ingredienti strettamente legati ai rispettivi elementi. Il legame degli stregoni con il fuoco ci rende il lavoro più facile.", "Questi andranno benissimo, {name}.\n\nIl fuoco è più di caos e distruzione: ricordalo bene. È anche vita e creazione. Tutte le cose sono legate tra loro in questo modo. Le forze si oppongono l'una all'altra ma, allo stesso tempo, l'una non può esistere senza l'altra. Si estinguono a vicenda, ma si danno anche significato a vicenda. Ricordalo sempre.\n\nUsare diversi tipi di magia insieme mostrerà non solo vera abilità, ma grande saggezza.", 0x53f3b76b, 0x560b3faf, 0x4dc721a7, 0x4211f69c, 0xeff16076, "....." },
  [1526] = { "Il richiamo del fuoco", "Sconfiggi la Minor Manifestation of Fire e metti la ⟦Glowing Ember=Brace Luminosa⟧ nel braciere in cima allo Shrine of Eternal Flame.", "La sapta di fuoco è pronta. È giunto per te il momento di affrontare la fiamma. Usa la sapta al santuario e sali in cima alla montagna per affrontare la manifestazione che si trova lì. Non attaccherà finché non sarai pront<o/a>, ma si accorgerà che sei in grado di vederla.\n\nAbbattila in fretta, {name}, perché il suo potere crescerà quanto più tempo impiegherai a ucciderla. Una volta sconfitta, metti le sue braci luminose nel braciere e accendi la torcia.", "Il braciere è alto circa un terzo della tua statura e sembra normale, salvo per le iscrizioni lungo le sue lisce sbarre di metallo. Il metallo non mostra alcun segno di usura dovuto alle intemperie, e la coppa in cima è fresca al tatto.", "Una fiamma incandescente si accende nella coppa quando vi deponi la brace. Senti gli effetti magici della sapta scorrerti nel corpo, e il fuoco danza ritmicamente davanti a te.\n\nPosi la cima della torcia nel bacile, e questa prende subito fuoco.", 0x53f3b76b, 0x7d09c623, 0x8243a2ed, 0x0c0f61ac, 0xca816112, "....." },
  [1527] = { "Il richiamo del fuoco", "Porta la Torcia della Fiamma Eterna a Kranal Fiss nelle ⟦Barrens=Savane⟧.", "Con la torcia ben salda in mano, ti allontani dal braciere e volgi lo sguardo su Durotar. Senti l'emozione scuoterti lo spirito mentre il vento si alza e costringe la fiamma a danzare con violenza.\n\nTi incammini lungo il sentiero che riporta alle ⟦Barrens=Savane⟧, in cerca di Kranal Fiss.", "Sì, {name}? Che cos'hai lì?", "Il tuo spirito arde più luminoso di qualunque torcia io abbia mai visto, {name}, e per questo dovresti essere fier<o/a>.\n\nSe continuerai su questo cammino, gli elementi saranno ai tuoi ordini e i nostri fratelli si rivolgeranno a te in cerca di guida e saggezza. Lascia che sia il primo a congratularmi con te e a consegnarti il tuo nuovo totem.", 0x53f3b76b, 0xd47d8263, 0x581acd2a, 0xacd1e0ef, 0xf51aa128, "....." },
  [1528] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle ⟦Barrens=Savane⟧.", "C'è l'acqua nel tuo futuro, amico. Vedo che sei già forte nelle vie del fuoco, e io penso che sei pront<o/a> a parlare con Islen.\n\nIslen vive lungo la costa delle ⟦Barrens=Savane⟧. Se vai a sud lungo il ⟦Southfury River=Fiume Furialunga⟧, non puoi sbagliare... cerca il grande squalo! Lei è forte nelle vie degli elementi e può insegnarti le vie dell'acqua... se pensi di essere pront<o/a>.\n\nÈ facile da trovare, basta che non vai troppo a sud... sta appena oltre ⟦Ratchet=Porto Paranco⟧.", nil, "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco: direi che è giunto il momento di conoscere la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più lontano. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, 0x40f9c41e, nil, 0xf9228c66, "...m." },
  [1529] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle ⟦Barrens=Savane⟧.", "È passato molto tempo dalla tua ultima prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.\n\nCerca Islen Waterseer nelle ⟦Barrens=Savane⟧. Si trova lungo la costa orientale, a sud del ⟦Southfury River=Fiume Furialunga⟧ e di ⟦Ratchet=Porto Paranco⟧. La troverai lì, nella sua capanna da pesca. Buona fortuna, {name}.", nil, "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco: direi che è giunto il momento di conoscere la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più lontano. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, 0x7363625e, nil, 0xf9228c66, "...m." },
  [1530] = { "Il richiamo dell'acqua", "Trova Brine nelle ⟦Barrens=Savane⟧ Meridionali.", "Se c'è una lezione che devi imparare sull'acqua, è questa: l'acqua significa rinascita.\n\nIl suo potere scorre, erode e purifica ogni genere di cosa. Scoprirai che la sua capacità di guarire e ristorare è impareggiabile, ma solo quando è pura.\n\nQuando capirai che l'acqua, se inquinata, può devastare tutto ciò che tocca, comprenderai quanto sia una risorsa vitale.\n\nSe desideri il sapta d'acqua, cerca Brine nel profondo delle ⟦Barrens=Savane⟧ Meridionali. La sua casa è continuamente molestata dai verrospini della zona.", nil, "Sì?\n\nMmm. Ho la sensazione di sapere cosa stai per chiedermi: cosa spinge qualcuno a vivere qui fuori, nella parte più remota delle ⟦Barrens=Savane⟧, con la minaccia dei verrospini tutt'intorno e senza alcuna protezione? Be', abbiamo tutti le nostre ragioni per giustificare il nostro modo di agire. La vera domanda è: cosa porta <un/una> semplice {race} nelle zone più remote delle ⟦Barrens=Savane⟧ a parlare con una donna che chiaramente non si cura della propria incolumità?\n\nScommetto che la risposta la conosciamo entrambi.", 0x1f0e11aa, 0xee4ba4c3, 0xfd15e1c1, nil, 0xfab4a730, "...m." },
  [1531] = { "Il richiamo dell'aria", "Trova Prate Cloudseer a ⟦Thousand Needles=Millepicchi⟧.", "Tu stai facendo progressi, amico. Sei pront<o/a> a dimostrare di essere degn<o/a> del totem dell'aria, ma prima devi trovare Prate Cloudseer a ⟦Thousand Needles=Millepicchi⟧. Lei è disposta a spiegarti come ottenere il tuo totem dell'aria, se la tratti con abbastanza rispetto.\n\nVa' a sud attraverso le ⟦Barrens=Savane⟧ e, quando arrivi a ⟦Thousand Needles=Millepicchi⟧, dirigiti a est. La troverai nascosta in una buca con il suo fidanzato... ah ah, non dirle che sparlo di lei, non la prenderebbe troppo bene.", nil, "Per ora ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem e, quando sarai pront<o/a>, torna ad addestrarti con me.", 0x8f4acf86, 0x7a57cbe0, 0x94f082ac, nil, 0x451e9311, "...m." },
  [1532] = { "Il richiamo dell'aria", "Trova Prate Cloudseer a ⟦Thousand Needles=Millepicchi⟧.", "I venti di Kalimdor si precipitano ad accoglierti, e sarai annoverat<o/a> tra i nostri <fratelli/sorelle> più potenti. È un orgoglio per me vedere che sei arrivat<o/a> fin qui e che hai un futuro così promettente.\n\nL'elemento dell'aria è difficile da controllare, ma ho fiducia che le tue abilità supereranno qualsiasi ostacolo ti venga posto davanti.\n\nDirigiti all'estremo sud delle ⟦Barrens=Savane⟧ ed entra a ⟦Thousand Needles=Millepicchi⟧. È lì, lontano verso est, che troverai Prate Cloudseer. Ti insegnerà altro.", nil, "Per ora ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem e, quando sarai pront<o/a>, torna ad addestrarti con me.", 0x8f4acf86, 0x7a57cbe0, 0xa1687f62, nil, 0x451e9311, "...m.", nil, nil, 0x6ef3855e, nil, nil },
  [1534] = { "Il richiamo dell'acqua", "Riempi la ⟦Empty Blue Waterskin=Borraccia Blu Vuota⟧ alle Ruins of Stardust, a ⟦Ashenvale=Valtetra⟧, e torna da Brine nelle ⟦Barrens=Savane⟧.", "Prendi questa borraccia e addentrati nella rigogliosa foresta che gli Elfi della Notte chiamano ⟦Ashenvale=Valtetra⟧. Si trova all'estremo nord delle ⟦Barrens=Savane⟧.\n\nUna volta entrat<o/a> nella foresta, dirigiti a ovest. Lungo le montagne che separano ⟦Stonetalon=Petrartiglio⟧ e ⟦Ashenvale=Valtetra⟧, oltre il Lago Mystral, troverai un luogo sacro: le Ruins of Stardust. Al centro del lago troverai una piccola fontana.\n\nPortami un campione dell'acqua della fontana. Sarà l'ultimo ingrediente che ti servirà prima che ti rimandi da Islen.", "Hai già l'acqua, {name}? Si racconta che le rovine siano protette da grandi creature della natura che non gradiscono i visitatori, ma potrebbero essere solo leggende per spaventare i nemici degli Elfi della Notte.\n\nIn ogni caso, fa' attenzione.", "Meraviglioso, {name}. Con tutti e tre i campioni raccolti, posso creare per te una fiala dell'acqua più pura che una creatura vivente possa trovare. Servirà nelle prossime tappe del tuo rito di passaggio.\n\nSono lieta di annoverarti tra i nostri, {name}. Rendi orgogliosi tutti gli {class}, e non vedo l'ora di sentir parlare delle tue imprese in futuro.", 0x1f0e11aa, 0x6761c4a7, 0xc0b99b1d, 0x4add2c8a, 0x3f6d811e, "....." },
  [1535] = { "Il richiamo dell'acqua", "Riempi la ⟦Empty Brown Waterskin=Borraccia Marrone Vuota⟧ alla pozza sotto la capanna di Brine e riportagliela nelle ⟦Barrens=Savane⟧.", "Per trovare la comprensione e ottenere da me il sapta, devi cercare solo le forme più pure dell'acqua. Mentre raccogli i campioni per me, osserva ciò che ti circonda. Fa' caso alle creature che dipendono dall'acqua e che la proteggono. Guarda come influisce sulle foreste e sui deserti. Sii testimone di come la sostanza stessa che sostiene la vita spinga le creature a toglierla.\n\nCominceremo con un compito semplice: sotto la mia capanna c'è uno stagno di questo prezioso liquido. Riempi questa borraccia e torna da me.", "Sono quasi pronta a mandarti a svolgere gli altri compiti. Hai già riempito la borraccia?\n\nSo quanto possono essere protettivi i verrospini. Anche una fonte d'acqua così piccola per loro è un tesoro immenso. Fanno grandi banchetti quando cade anche la più leggera pioggia sulle ⟦Barrens=Savane⟧. L'acqua è sacra per la loro specie perché è così scarsa. Capisci?", "Pensavo che sarebbe scorso un po' di sangue se avessi provato a prendere l'acqua dalla pozza. È un peccato che i verrospini non capiscano che tutti gli esseri viventi sono legati tra loro, e che la loro avidità non fa che perpetuare il dolore e la sofferenza del loro popolo. Quanto potrebbero ottenere se mettessero da parte le loro divergenze e i loro clan si unissero.\n\nDi nuovo, un peccato, ma con ogni probabilità una fortuna per le altre razze delle ⟦Barrens=Savane⟧.", 0x1f0e11aa, 0x3c4dd7b6, 0x425c8a0e, 0x96cf7b6b, 0xb02bcec2, "....." },
  [1536] = { "Il richiamo dell'acqua", "Riempi la ⟦Empty Red Waterskin=Borraccia Rossa Vuota⟧ al pozzo del ⟦Tarren Mill=Mulino di Tarren⟧ e torna da Brine nelle ⟦Barrens=Savane⟧.", "Molto tempo fa seguii alcuni compagni nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧. Ci difendemmo da alcuni umani tenaci che vivono lì e ci ritrovammo in una cittadina di cui si erano impadroniti i Reietti: il ⟦Tarren Mill=Mulino di Tarren⟧.\n\nFu lì che trovai una cosa davvero singolare: al centro del paese c'era un piccolo pozzo di fresca acqua sorgiva. Non sono sicuro che gli appestati abitanti del paese ne capiscano il valore: è un piccolo residuo sacro in un mare profanato.\n\nPortami un campione di quell'acqua in questa borraccia.", "Il pozzo rimasto puro dentro la città mi ricorda le storie che mi raccontavano da giovane, {name}. Anche nei tempi di grande dolore e sofferenza si può trovare uno spiraglio di speranza, un piccolo simbolo attorno a cui stringersi. Il popolo degli orchi vede così Thrall. È sopravvissuto contro ogni previsione e si è innalzato a guidare il nostro popolo con la sua forza e il suo esempio.\n\nNon sono sicuro che un altro orco abbia sofferto quanto lui, ma allo stesso tempo non sono sicuro che un altro orco sia forte quanto lui.", "Bene, {name}. Ti dedichi al compito che hai davanti e sai cercare ciò che serve.\n\nMi basta un altro campione per creare il reagente necessario per il tuo sapta. Anche Islen ne sarà contenta.", 0x1f0e11aa, 0xb7fce94c, 0x94c4b54f, 0x7fa68a20, 0x24c2788b, "....." },
  [1578] = { "Rifornire il fronte", "Porta 6 Copper Axe e 6 Copper Chain Belt a Thorvald, nella torre di guardia meridionale di Loch Modan", "I montanari di Loch Modan combattono i trogg e hanno il loro bel da fare! Hanno bisogno di continui rifornimenti di armature e armi nuove, se vogliamo mai tenere a bada quei trogg.\n\nPer questo il mio collega Thorvald è laggiù, a cercare di tenere i montanari ben equipaggiati. Quindi, se fabbricassi qualche Copper Axe e qualche Copper Chain Belt e li portassi a Thorvald, te ne sarebbe grato. Potrebbe persino condividere con te il suo sapere.\n\nThorvald è nella torre di guardia meridionale di Loch Modan.", "Non ho tempo per chiacchierare. Hai affari da sbrigare con me?", "Ah, scusami! Non avevo capito che eri qui per aiutare a rifornire le nostre truppe. La roba che hai fabbricato sarà di grande aiuto!\n\nEcco degli schemi per un'armatura. Spero che ti siano utili.", 0xc30dcf6c, 0xcc5d9418, 0x30473b15, 0xec2e191f, 0xf823104b, "....." },
  [1579] = { "Spinotti isolati", "Porta 8 Spinotto Isolato a Wizbang Cranktoggle ad Auberdine.", "Sono venuto ad Auberdine per la quiete. Voglio inventare le mie invenzioni dove c'è silenzio, perché dopo una notte di bevute non sopporto tutto il baccano di ⟦Ironforge=Forgiardente⟧!\n\nCosì ho preso una nave per Auberdine e durante il viaggio ho bevuto un po' troppo. Mi è caduta in mare la cassetta degli spinotti isolati! Mi servono i miei spinotti isolati!\n\nNon so di preciso dove li ho fatti cadere, ma se li peschi nell'oceano magari hai fortuna...", "Hai trovato i miei spinotti isolati, {name}? Senza i miei spinotti isolati non posso accordare i miei piroli stintilici!", "Non ci credo, li hai trovati! Devi essere <il/la> {race} più fortunat<o/a> di Kalimdor!", 0xfa9d081e, 0xb6cf36d8, 0xf09fa27e, 0x68a8175d, 0x9be37eba, "....." },
  [1580] = { "Gli Electropeller", "Porta 12 Electropeller a Wizbang Cranktoggle ad Auberdine.", "Sappiamo che sei fortunat<o/a>, ma... quanto sei fortunat<o/a>, {name}?\n\nUna notte vagavo per le strade di ⟦Darkshore=Rivafosca⟧. Cercavo un bel fiume o un lago per provare il mio nuovo richiamo per anatre semovente ed esplosivo, e credo di essere stato un po' brillo... perché sono svenuto e mi sono risvegliato ore dopo ad Auberdine. Avevo i capelli bruciacchiati e la mia borsa di electropeller era sparita! Devo averli fatti cadere in acqua!\n\nMi servono quegli electropeller! Forse riesci a ripescarli da qualche lago o torrente di ⟦Darkshore=Rivafosca⟧...", "Hai trovato qualche electropeller? Mi servono, se voglio continuare le mie ricerche sui richiami per anatre...", "Non ci posso credere! Li hai trovati! Sei <il/la> <pescatore/pescatrice> migliore che abbia mai visto!\n\nGrazie, {name}. E tieni, prendi questi. Anche se sei così brav<o/a> che probabilmente non ti servono, ti aiuteranno a pescare.", 0x667cc3c7, 0xdc46859a, 0x642310a5, 0xf9546f58, 0xc63f8173, "....." },
  [1581] = { "Elisir per i Bladeleaf", "Porta 6 Elixir of Lion's Strength e 2 Elixir of Minor Defense a Syral Bladeleaf a Dolanaar.", "Il nostro negozio di erbe e alchimia va a gonfie vele, ma mio marito passa così tanto tempo a mescolare pozioni che non abbiamo mai tempo l'uno per l'altra.\n\nPuoi aiutarci?\n\nSe mi porti una scorta di elisir già pronti, sarò felice di fare uno scambio con te. Ho alcune erbe rare che potrebbero esserti utili.", "Ciao, {name}. Hai gli elisir da scambiare?", "Sono preparati con cura. Metti grande attenzione nel tuo mestiere, {name}, ed è importante per un alchimista.\n\nEcco le tue erbe, appena raccolte. Che tu possa usarle bene.", 0x55e6a1a0, 0x4cd053d4, 0x114405e0, 0x486738da, 0xd85fcf4b, "....." },
  [1582] = { "⟦Moonglow Vest=Giaco del Bagliore Lunare⟧", "Porta 1 Embossed Leather Glove, 5 ⟦Embossed Leather Boots=Stivali di Cuoio Adorni⟧ e 5 Embossed Leather Cloak a Lotherias, a Darnassus.", "Noi di Darnassus, e soprattutto noi artigiani, siamo molto indaffarati. I giovani avventurieri non vedono l'ora di mettersi alla prova nelle terre selvagge e hanno sempre bisogno di rifornimenti.\n\nSe mi aiuti a evadere i miei ordini di articoli in cuoio, forse potrò insegnarti una tecnica avanzata di conciatura.", "Salute, {name}.", "Sì, sono ottimi pezzi. Hai una mano esperta e occhio per i dettagli. Il tuo futuro da conciatore è promettente.\n\nEcco, {name}. Lascia che ti mostri lo schema per realizzare il ⟦Moonglow Vest=Giaco del Bagliore Lunare⟧.", 0x13b76bcf, 0xd2ae52ab, 0x86455e3c, 0x1355ea4c, 0x60bb3c3a, "....." },
  [1598] = { "Il tomo rubato", "Recupera i ⟦Powers of the Void=Poteri del Vuoto⟧ per Drusilla La Salle.", "Ehi, tu! {name}, giusto?\n\nSpero che tu sia sicur<o/a> di voler seguire la via dello stregone, perché se non sai cavartela da sol<o/a>, rischi di finire travolt<o/a>.\n\nDevo addestrarti, ma prima devo assicurarmi che tu sia abbastanza forte.\n\nC'era un novizio che studiava all'Abbazia ed è scappato per unirsi alla ⟦Defias Brotherhood=Fratellanza dei Defias⟧. Perché mi interessa? Be', ha rubato alcuni libri importanti.\n\nUno di questi è proprio un libro che volevo per me, i ⟦Powers of the Void=Poteri del Vuoto⟧. Rubalo per me: lo tengono nascosto nella loro tenda, nelle Vigne.", "Sarebbe stato troppo vistoso rubare il libro di persona. Che fortuna che uno dei loro stessi tirapiedi abbia fatto il lavoro sporco per me.", "Eccellente... Non sono mai riuscita ad accedere a questo testo: era custodito in un'ala protetta della biblioteca, e sarebbe sembrato sospetto se mi fossi aggirata da quelle parti.\n\nBe', hai fatto un buon lavoro a procurartelo, e sono convinta che probabilmente sapresti gestire un imp tutto tuo, quindi non c'è motivo per non mostrarti come evocarne uno.", 0x88b1dee6, 0x8e23bc14, 0x4748064a, 0xdb594d3a, 0x048d8e41, "....." },
  [1599] = { "Primi passi", "Porta 3 Feather Charm ad Alamar Grimm a ⟦Anvilmar=Forgiamara⟧.", "Devi essere tu la nuova recluta tra gli stregoni di cui tutti parlano sottovoce. Evidentemente qualcuno ti ha preso in simpatia, se mi hanno chiesto di sottrarre tempo alle mie ricerche per cominciare il tuo addestramento.\n\nNon preoccuparti, non te ne farò una colpa.\n\nIl più semplice degli incantesimi di evocazione che imparerai è quello dell'imp. Prima di trasmettertelo, però, devi dimostrare di avere le capacità magiche e fisiche necessarie.\n\nPortami tre talismani di piume dei novizi Mantogelido della caverna a sud-ovest.", "Quei talismani di piume che portano i novizi hanno una specie di potere magico. Sarà interessante studiarli. Non me lo sarei aspettato dai troll.", "Molto bene, molto bene! Hai fatto un buon lavoro, {name}. Forse l'interesse che stanno mostrando per te è meritato, dopotutto.\n\nQuesto lo decideranno gli altri, sempre che il tuo imp non abbia la meglio su di te e stronchi la tua carriera sul nascere. Per ora mi basta sapere che probabilmente sopravvivrai ai tuoi primi mesi da {class}.\n\nUna parola sull'imp, {name}. Come sa ogni {race}, non lasciarti ingannare dalle sue dimensioni: la sua magia può essere molto pericolosa.", 0xf98072ec, 0xf994bd58, 0xa842c92b, 0xeeb2dc13, 0xe52d5af0, "....." },
  [1618] = { "Equipaggiare ⟦Redridge=Crestarossa⟧", "Tormus Deepforge vuole che tu porti 4 Runed Copper Belt e 4 Heavy Copper Maul a Verner Osgood a ⟦Redridge=Crestarossa⟧.", "Non siamo solo noi nani a combattere. Anche i nostri alleati umani hanno il loro bel da fare!\n\nCrestarossa subisce attacchi periodici dagli orchi Roccianera, e le loro scorte di equipaggiamento sono sempre scarse. Se dessi loro una mano, sono sicuro che il loro fabbro, Verner Osgood, ti insegnerebbe un paio di trucchi.", "Spero che tu porti buone notizie da ⟦Ironforge=Forgiardente⟧. Perché non so più che pesci prendere!", "Grazie, {name}. Questo mi aiuterà tantissimo. Con gli orchi ⟦Blackrock=Roccianera⟧ che attaccano dal ⟦Stonewatch Keep=Mastio di Guardamasso⟧ e gli gnoll di ⟦Redridge=Crestarossa⟧ in agguato sulle colline a nord, devo continuamente riparare armature e forgiare nuove armi per le nostre truppe.\n\nLe provviste che hai portato mi daranno un attimo di pace. Avrò abbastanza tempo per insegnarti qualcosa...", 0x2d039f79, 0xf39d4ff5, 0x66c6d741, 0x49945919, 0x462fb187, "....." },
  [1638] = { "L'addestramento di un guerriero", "Parla con Harry Burlguard.", "Hai dimostrato di essere <un/una> <guerriero/guerriera> competente, {name}. Ma sei ancora giovane e hai molto da imparare.\n\nParla con Harry Burlguard: di solito sta alla taverna Pig and Whistle, nella Old Town di ⟦Stormwind=Roccavento⟧. Harry è un vecchio veterano e un buon maestro. Può mostrarti qualche mossa che ti terrà in vita più a lungo.", nil, "Oh oh! Bevi qualcosa con me, {name}. Fuori sembri tost<o/a>, ma vediamo se il tuo stomaco regge qualche boccale della roba più forte del Pig and Whistle!!\n\nOppure... eri qui per una lezione?", 0x93c881d5, 0x0aef52fa, 0x0ff82d16, nil, 0x11af52b0, "...m." },
  [1639] = { "Bartleby l'ubriacone", "Parla con Bartleby.", "Sì, posso insegnarti. Ma prima voglio vedere che mosse conosci già.\n\nVedi quell'ubriaco laggiù, in fondo al bancone? Bartleby? Voglio che tu gli prenda il boccale.\n\nAh, e se conosci Bartleby, sai che non te lo darà così facilmente.", nil, "Ehi, <ragazzo/ragazza> elegante! Che ci fa una creaturina schizzinosa come te al Pig and Whistle? Attent<o/a>, che potresti spezzarti un'unghia...", 0x1785381a, 0x423c9e83, 0x1cf66148, nil, 0x99442b95, "...m.", nil, nil, nil, nil, 0x4102c003 },
  [1640] = { "Sconfiggi Bartleby", "Sconfiggi Bartleby, poi parlagli.", "Vuoi cosa?? Sei matt<o/a>!\n\nL'unico modo per avere questo boccale è strapparlo dalle mie fredde dita morte...", "L'unico modo per avere questo boccale è strapparlo dalle mie fredde dita morte...", "Sei molto più tost<o/a> di quanto sembri!", 0x26ecfd0d, 0x3f5bb9b0, 0xe0771850, 0xa0dfd961, 0xdc83d2d5, "....." },
  [1641] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", nil, nil, nil, "Qui a ⟦Stormwind=Roccavento⟧ ho il compito di avviare i paladini sul cammino verso una virtù più alta, mentre si consacrano alla Luce e difendono Azeroth dal Flagello e da altre minacce.\n\nÈ giunto per te il momento di muovere il primo passo per diventare davvero virtuos<o/a>. Se accetti, ti darò un Libro della Divinità. Studiandolo imparerai qualcosa sulla Luce e su ciò che ci si aspetta da te. Se lo comprenderai e ne sarai capace, riuscirai a ottenere abilità più grandi.", 0xe91f21c0, nil, nil, nil, 0xde6e2d42, ".mmm." },
  [1642] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "In ogni cosa un paladino deve riflettere la Luce che sostiene la nostra forza. Per uno di noi, aspirare al divino non significa aspirare a diventare un dio: aspiriamo a essere buoni in ogni azione.\n\nAnche se in questi tempi duri siamo chiamati a colpire il male, devi sempre ricordare che è aiutare gli altri ciò che ti distinguerà davvero dai cittadini di Azeroth. Compassione, pazienza, coraggio: per un paladino queste cose contano quanto la forza in battaglia.\n\nImparalo bene, e non dimenticarlo mai.", nil, "Ben ritrovat<o/a>, {name}. Come procedono i tuoi studi del ⟦Tome of Divinity=Tomo della Divinità⟧?\n\nAllora dovresti essere pront<o/a> a sottoporti a una prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre: atti di compassione e comprensione, persone che hanno bisogno di aiuto, creature da abbattere.\n\nDimostrando di avere la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere al servizio della Luce e di avere una mente salda.", 0xe91f21c0, 0x0f3ca705, 0x0d5218fa, nil, 0x075c2620, "...m." },
  [1643] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Cerca Stephanie Turner nel ⟦Trade District=Quartiere del Commercio⟧ di ⟦Stormwind=Roccavento⟧.", "Il tuo compito, dunque, {name}, è trovare qui a ⟦Stormwind=Roccavento⟧ qualcuno che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenti. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, quella persona deve avere nobili intenzioni e contare sulla tua bontà.\n\nFa' questo, e torna da me quando avrai finito. Allora parleremo ancora del tuo cammino e di cosa significhi essere un paladino della Luce.", nil, "Oh, ciao, tesoro. Come vanno le tue avventure? Oh, sono così contenta di sentire che te la passi bene.\n\nOh, io? Grazie per avermelo chiesto: sto bene, tutto considerato.\n\nCon l'aumento dei mercanti la gente è meno disposta a separarsi da cuoio e stoffa di questi tempi, quindi è più difficile fare i vestiti per i bambini dell'orfanotrofio, ma ce la caveremo. Per \"noi\" intendo io e mio marito. È su a ⟦Ironforge=Forgiardente⟧ a cercare aiuto tra i cittadini di lì.", 0xe91f21c0, 0xce0e1021, 0x63f1ddfe, nil, 0x3d88e066, "...m." },
  [1644] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Porta 10 ⟦Linen Cloth=Tessuto di Lino⟧ a Stephanie Turner a ⟦Stormwind=Roccavento⟧.", "Poveri cari, quasi nessuno di loro ha una famiglia, per colpa degli attacchi del Flagello dell'ultimo decennio.\n\nMio marito John raccoglie il materiale con cui cucio camicie e pantaloni per i bambini, ma non ho avuto nemmeno il tempo di farlo. Ero troppo occupata a mettere cibo nei loro piatti e un tetto sopra le loro teste.\n\nCome dici? Saresti disposto ad aiutarmi? Oh, sia lodata la Luce, e grazie a te, {name}.\n\nSe potessi portarmi del tessuto di lino per cucire dei vestiti ai bambini, mi aiuteresti tantissimo.", "Spero che il mio John abbia più fortuna a ⟦Ironforge=Forgiardente⟧. Detesta quei viaggi perché lasciano soli me e i bambini, ma sa che vanno fatti. Ha un cuore d'oro.\n\nCerti anni sono stati più facili di altri, ma questo è stato di gran lunga il più duro. È quasi come se qualcosa nell'aria annunciasse un grande cambiamento. Ma chi può dirlo?", "Grazie, {name}, grazie mille!\n\nI bambini saranno così contenti, e mi hai fatto risparmiare un sacco di tempo. Ora potrò dedicarmi agli altri bisogni dei bambini, e speriamo che il mio John possa tornare a casa prima del previsto.\n\nGrazie ancora, {name}. Sapevo di poter contare sulla generosità degli altri. Che la Luce sia con te.", 0xe91f21c0, 0xf1310977, 0xb01329b2, 0x903a4103, 0x6226b5ac, "....." },
  [1645] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", nil, nil, nil, "Piacere di conoscerti, {name}. Ho il compito di avviare i paladini sul cammino verso una virtù più alta, mentre si consacrano alla Luce e difendono Azeroth dal Flagello e da altre minacce.\n\nÈ giunto per te il momento di muovere il primo passo per diventare davvero virtuos<o/a>. Se accetti, ti darò un Libro della Divinità. Studiandolo imparerai qualcosa sulla Luce e su ciò che ci si aspetta da te. Se lo comprenderai e ne sarai capace, riuscirai a ottenere abilità più grandi.", 0xe91f21c0, nil, nil, nil, 0xd28a44f8, ".mmm." },
  [1646] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧.", "In ogni cosa un paladino deve riflettere la Luce che sostiene la nostra forza. Per uno di noi, aspirare al divino non significa aspirare a diventare un dio: aspiriamo a essere buoni in ogni azione.\n\nAnche se in questi tempi duri siamo chiamati a colpire il male, devi sempre ricordare che è aiutare gli altri ciò che ti distinguerà davvero dai cittadini di Azeroth. Compassione, pazienza, coraggio: per un paladino queste cose contano quanto la forza in battaglia.\n\nImparalo bene, e non dimenticarlo mai.", nil, "Bentornat<o/a>, {name}. Spero che tu abbia passato del tempo a leggere il libro.\n\nAllora dovresti essere pront<o/a> a sottoporti a una prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre: atti di compassione e comprensione, persone che hanno bisogno di aiuto, creature da abbattere.\n\nDimostrando di avere la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere al servizio della Luce e di avere una mente salda.", 0xe91f21c0, 0x04be03fc, 0x0d5218fa, nil, 0x8e061755, "...m." },
  [1647] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Cerca John Turner nell'anello esterno di ⟦Ironforge=Forgiardente⟧.", "Il tuo compito, dunque, {name}, è trovare qui a ⟦Ironforge=Forgiardente⟧ qualcuno che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenti. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, quella persona deve avere nobili intenzioni e contare sulla tua bontà.\n\nFa' questo, e torna da me quando avrai finito. Allora parleremo ancora del tuo cammino e di cosa significhi essere un paladino della Luce. Resterò qui nel tempio ad attendere il tuo ritorno. Anche altri paladini avranno bisogno della mia guida.", nil, "L'ORFANOTROFIO DI ROCCA... oh, scusa, non volevo urlarti contro, <signore/signorina>.\n\nMi chiamo John Turner. Come stai?\n\nBene, bene, mi fa piacere che ti vada tutto bene. Ho già alle spalle una lunga giornata di lavoro e mia moglie mi manca da morire, ma è il prezzo da pagare quando ci sono bocche da sfamare e schiene da vestire.", 0xe91f21c0, 0xa7a38a3f, 0x6e4cdf70, nil, 0xd326865b, "...m.", nil, nil, nil, nil, 0xc090c1d5 },
  [1648] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Porta 10 ⟦Linen Cloth=Tessuto di Lino⟧ a John Turner a ⟦Ironforge=Forgiardente⟧.", "Io e mia moglie gestiamo un orfanotrofio a ⟦Stormwind=Roccavento⟧, soprattutto per bambini che hanno perso i genitori negli attacchi del Flagello dell'ultimo decennio. Vengo a ⟦Ironforge=Forgiardente⟧ più o meno ogni mese per raccogliere altre provviste dai cittadini di qui e parlare con i vari gruppi, per vedere se possono fare qualcosa per aiutarci.\n\nQuesto viaggio è stato di una lentezza esasperante, e non molto fruttuoso.\n\nSe solo riuscissi a trovare un altro po' di lino perché mia moglie possa cucire dei vestiti, potrei finalmente mandare un carico a casa.", "Con tutti questi mercanti che arrivano qui e in tutta Azeroth, c'è meno disponibilità del materiale che usiamo per fare i vestiti ai bambini del nostro orfanotrofio. Aiutarmi a raccogliere il lino perché mia moglie possa fare loro dei vestiti nuovi è molto nobile da parte tua, {name}. Grazie.\n\nSpero di poter tornare presto a casa da mia moglie.", "È davvero meraviglioso da parte tua, {name}. Grazie ancora.\n\nSei <un/una> <uomo/donna> nobile a fare questo per me. Non c'è da stupirsi che tu abbia scelto di seguire la Luce. Vorrei tanto poterti ripagare per tutto quello che hai fatto... come dici? È il minimo che potessi fare? Visto? È proprio di questo che parlo, {name}: nobile fino in fondo.\n\nSta' attent<o/a>, e che la Luce ti protegga nei tuoi viaggi.", 0xe91f21c0, 0xfd1fbfec, 0xabd207ba, 0xfcf718e1, 0x929bdf7f, ".....", nil, nil, nil, nil, 0xc7eef468 },
  [1649] = { "Il ⟦Tome of Valor=Tomo del Valore⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Il valore, e tutte le virtù che lo accompagnano, sono come minerali rari: devi custodirli quando li trovi, per il loro pregio, ma devi anche prenderti il tempo di estrarli... di raffinarli. Quando si mescolano nel modo giusto, formano una lega resistente, a volte infrangibile perfino dai colpi più potenti.\n\nQuesta forza, la tua fede, il tuo coraggio, devono essere messi alla prova. Devi imparare a non perdere mai la fede e a capire che, con il potere della Luce, puoi superare cose che la maggior parte degli altri non può.", nil, "Ah, desideri chiedermi una prova di valore. Splendido.\n\nCi sono molti compiti in città e nelle terre circostanti che offrono grandi sfide, e a loro farebbe comodo <un/una> <uomo/donna> con le tue capacità.\n\nQuesta prova non va presa alla leggera, {name}. Questa, come molte cose lungo il nostro cammino, potrebbe costarci la vita. La Chiesa desidera sempre rafforzare i suoi ranghi, ma comprende i sacrifici necessari per assicurarsi che i paladini al suo servizio ne siano degni.\n\nSei pront<o/a>?", 0xdaebf666, 0x0f3ca705, 0x19f0af5d, nil, 0x370b9c7b, "...m.", nil, nil, nil, nil, 0xeacd036c },
  [1650] = { "Il ⟦Tome of Valor=Tomo del Valore⟧", "Trova Daphne Stilwell nelle ⟦Westfall=Marche Occidentali⟧.", "Bene! La tua mancanza di esitazione è un segno sicuro che sei <pronto/pronta> e <desideroso/desiderosa> di metterti alla prova. E così sia.\n\nAll'estremità di ⟦Longshore=Rivalunga⟧, nelle Marche Occidentali, una casetta si affaccia sull'oceano. Lì vive una coppia, gli Stilwell. Jordan è un fabbro straordinario, ed è andato a ⟦Ironforge=Forgiardente⟧ per incontrare i nani per un po'. Ma questo ha lasciato Daphne, sua moglie, sola e senza protezione.\n\nSecondo i rapporti, i Defias hanno quasi preso il controllo della zona, e Daphne potrebbe aver bisogno di protezione da quei furfanti. Va' laggiù.", nil, "Salve, {name}. Immagino, da tutta quell'armatura e da quell'arma che porti, che tu sia qui per cercare di prenderti la mia terra, oppure che la Chiesa abbia finalmente mandato qualcuno a proteggermi mentre il mio Jordan è via.\n\nBe', lascia che mi presenti: sono Daphne Stilwell. Piacere.\n\nAllora, non sei in ritardo... ho ucciso solo una mezza dozzina di quei farabutti dall'alba di ieri. Sono stati un po' lenti a girare la curva lassù, ma probabilmente ti hanno vist<o/a> arrivare, il che significa che probabilmente saranno qui da un momento all'altro.", 0xdaebf666, 0xcafbffbb, 0x9e791513, nil, 0xd85dbe60, "...m." },
  [1651] = { "Il ⟦Tome of Valor=Tomo del Valore⟧", "Difendi Daphne Stilwell dall'attacco dei Defias.\n\nPer riuscire, nessuno dei vostri spiriti deve abbandonare le sue spoglie mortali.\n\nQuando ce l'avrai fatta, parla di nuovo con Daphne Stilwell.", "Ora, scommetto che torneranno presto, quindi preparati.\n\nIn casa ho un fucile. Lo prendo e sarò pronta a darti una mano, ma per lo più te la dovrai cavare da sol<o/a>.\n\nNon ho idea di quanti ne manderanno, ma sono sicura che saranno più dei pochi che hanno mandato prima.\n\nChiedi alla Luce tutte le benedizioni che puoi, perché... hai sentito? Credo che stiano arrivando.\n\nResistiamo vicino alla casa!", "Resisteremo alla casa!", "Ce l'abbiamo fatta, {name}! Grazie per il tuo aiuto. Sei stat<o/a> davvero straordinari<o/a> là fuori. Non avrei mai pensato che un paladino potesse tenere testa a tanti nemici insieme.\n\nHai davvero dimostrato coraggio di fronte a forze soverchianti.", 0xdaebf666, 0x891ebe27, 0xa90e2959, 0x52f37378, 0x0f46273c, "....." },
  [1652] = { "Il ⟦Tome of Valor=Tomo del Valore⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Ti prego, torna da Duthorian e fagli sapere che per ora sono al sicuro. Devo ringraziare te e la Chiesa per questo.\n\nManderà un messaggio a ⟦Ironforge=Forgiardente⟧ per far sapere al mio Jordan che non ha nulla da temere.\n\nOh, quanto mi manca mio marito. Non vedo l'ora che torni.", nil, "Dunque ci incontriamo di nuovo, {name}, e vedo che sei di ottimo umore.\n\nLa casa degli Stilwell sarà al sicuro per un altro giorno, e dal tuo racconto vedo che i pericoli non sono certo mancati. Ben fatto.\n\nDaphne e Jordan hanno aiutato molto la Chiesa, e farti proteggere la loro proprietà, e le loro stesse vite, era il minimo che potessimo fare per loro.\n\nPer il tuo valore sarai ricompensat<o/a>.", 0xdaebf666, 0x0f3ca705, 0xc192be15, nil, 0xccb181a9, "...m." },
  [1653] = { "La prova della rettitudine", "Parla con Jordan Stilwell a ⟦Ironforge=Forgiardente⟧", "A dire il vero, non ho dubbi che Jordan stesso vorrebbe ringraziarti, e visto che mi serve un messaggero per fargli sapere che sua moglie è al sicuro, credo che tu sia la scelta perfetta.\n\nJordan doveva diventare un paladino della Luce, prima che la dedizione al mestiere di suo padre lo portasse su un'altra strada: conosce a fondo il nostro modo di vivere ed è considerato tra i più fedeli.\n\nDovrebbe essere ancora a ⟦Ironforge=Forgiardente⟧: di giorno gli piace lavorare fuori dalle porte, per via dell'aria fresca di montagna o qualcosa del genere.", nil, "Buongiorno, {name}. La Luce è con te, confido?\n\nCome dici? Ti manda Duthorian!? Mia moglie, come sta? Sapevo che ci sarebbero stati guai, se fossi partito. Ti prego, dimmi che è... oh, grazie al cielo. Sono così felice che sia al sicuro. I Defias erano una minaccia molto prima di questi attacchi, ma ora i consiglieri del re non possono più negarlo.\n\nCos'altro aveva da dire Duthorian?\n\nSei tu che hanno mandato a proteggere mia moglie? Allora ti ringrazio di nuovo, {name}. Non avrei potuto immaginare una prova di valore migliore.", 0xcdb318ba, 0x81a2ff9b, 0x9423b858, nil, 0xcf755a7e, "...m." },
  [1654] = { "La prova della rettitudine", "Seguendo le ⟦Jordan's Weapon Notes=Note sulle Armi di Jordan⟧, trova una ⟦Whitestone Oak Lumber=Catasta di Legname di Quercia Scorzasecca⟧, la Bailor's Refined Ore Shipment, il ⟦Jordan's Smithing Hammer=Martello da Forgiatore di Jordan⟧ e una Gemma Kor, e portali a Jordan Stilwell a ⟦Ironforge=Forgiardente⟧.", "Vorrei ricompensarti, se sei <disposto/disposta> ad accettare una cosa simile. Non fraintendermi: la mia generosità dipende da quanto potrai essermi d'aiuto, ma vedo un grande vantaggio per entrambi in un'alleanza del genere.\n\nForgerò per te un'arma degna di ciò che hai compiuto, un simbolo dei paladini e della Luce, ma dovrai raccogliere gli oggetti che mi servono per crearla. Ho già cominciato a prendere appunti sugli oggetti: serve solo qualcuno abbastanza coraggioso e abile da recuperarli. Che ne dici, {class}?", "Gli oggetti che cerchi saranno difficili da trovare, ma ti assicuro che l'arma che forgerò per te varrà la fatica.\n\nSarà il mio miglior lavoro finora, e solo un piccolo compenso per il servizio che mi hai reso.", "È meraviglioso! Hai trovato tutti gli oggetti.\n\nCon questi non avrò problemi a forgiarti un'arma grandiosa. A dire il vero ho i progetti da parecchio tempo. Solo che non ho mai avuto l'occasione di procurarmi il materiale. Grazie, {name}.\n\nÈ bello riavere il martello di mio padre... e una Gemma Kor. Non avrei mai pensato di vederne una con i miei occhi.", 0xcdb318ba, 0xc7646423, 0xfb00e058, 0x7e9cab3a, 0x803f6796, "....." },
  [1655] = { "Il carico di minerale di Bailor", "Porta la ⟦Jordan's Ore Shipment=Spedizione di Minerali di Jordan⟧ a Bailor Stonehand a Loch Modan.", "Accidenti, m'hai fatto prendere un colpo, <amico/amica>! Non vedi che ero perso nei miei pensieri?\n\nCome dici? La spedizione di Jordan... per ⟦Ironforge=Forgiardente⟧. Ahhh, sì, so di cosa parli. Gli ogre dei Mo'grosh... son loro che han preso il carico di minerale del mio vecchio amico. La carovana veniva qui dalle ⟦Wetlands=Paludi Grigie⟧ e l'hanno assalita. La guardia che è sopravvissuta all'attacco è morta giusto qualche giorno fa: il guaritore non è arrivato in tempo.\n\nSe vuoi la spedizione, dovrai andare a nord-est, dall'altra parte del lago. Dev'essere da qualche parte laggiù.", "Allora, qualche fortuna? Ah ah, quegli ogre non ti hanno ancora messo sotto, eh?", "Sì sì, è proprio questo. Ah! Se avessi saputo che saresti <andato/andata> davvero laggiù a combattere quegli ogre, t'avrei dato una lista di cose da prendere invece di questa sola. Ma non sei qui a fare affari per me, vero?\n\nI patti son patti: Jordan voleva un carico della mia lega, ed è quello che avrà.\n\nSalutamelo, e abbi cura di te, {class}.", 0xa7b78c4d, 0x20c7415e, 0x9cf966dc, 0x0aa0afd3, 0xfa19665f, ".....", nil, nil, 0xc6e76059, nil, nil },
  [1656] = { "Un compito incompiuto", "Porta il ⟦Bundle of Furs=Mucchio di Pellicce⟧ al locandiere Kauth, al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "{name}, ti prego, ti supplico, puoi aiutarmi? Non ho finito i miei compiti qui sulla Mesa (sono a metà del mio Rito della Forza) e mio padre mi ha chiesto di consegnare queste pellicce alla locanda di Bloodhoof.\n\nNon sono abbastanza riposato per completare sia il mio rito sia questo incarico per mio padre. Ti dispiacerebbe andare al posto mio?\n\nLa locanda è piacevole, il posto perfetto per riposare durante i tuoi lunghi viaggi. Sono sicuro che sarai d'accordo quando la vedrai.", "Sì, giovane? Cosa può fare Kauth per te?\n\nIl viaggio dalla Mesa fin qui può essere un peso tremendo per alcuni, ma una vista gradita per altri. Per te quale dei due è, mi chiedo?", "Ah, le pellicce che aspettavo. Grazie.\n\nSono arrivate prima di quanto pensassi. Diventeranno ottime coperte per chiunque voglia fermarsi qui.\n\nResta pure quanto vuoi. La mia locanda è sempre aperta e tutta la nostra gente è benvenuta. E non sottovalutare una buona notte di riposo: può fare una grande differenza quando sei in viaggio.", 0xc958b12f, 0x96f2a5d5, 0xd339afba, 0xcd32ef45, 0xd1fe2ab2, "....." },
  [1661] = { "Il Tome of Nobility", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Ti saluto ancora una volta, {name}. Sono più orgoglioso che mai di chiamarti <fratello/sorella>: la tua dedizione è un omaggio a tutti noi.\n\nÈ giunto il momento che io ti conceda un grande dono. Ma sappi questo: per ora te lo do liberamente, ma in futuro, quando il tempo lo permetterà, sarà una sfida molto più grande per tutti i paladini che sceglieranno di intraprendere la mia missione.\n\nParlami di nuovo e ti concederò un grande beneficio.", nil, "Congratulazioni, e che la Luce ti protegga.", 0x2923ea98, 0x0f3ca705, 0xb8e31e55, nil, 0x72ae1e80, "...m.", nil, nil, 0xe0eeab96, nil, nil },
  [1665] = { "Il ⟦Bartleby's Mug=Boccale di Bartleby⟧", "Porta il ⟦Bartleby's Mug=Boccale di Bartleby⟧ a Burlguard.", "Va bene, ecco il mio boccale. Aspetta! Prima lasciami finire quello che c'è dentro... ecco fatto.", "Ho visto il tuo scontro con Bartleby. Ben fatto! Hai preso il suo boccale?", "Eccolo! Di certo non voleva separarsene, ma sei <stato/stata> convincente. Ben fatto.\n\nOra, la tua lezione...", 0x02b31d24, 0x1a2aa8fa, 0xbe9a356b, 0xc1276dca, 0xd416acd3, "....." },
  [1666] = { "Il maresciallo Haggard", "Parla con il maresciallo Haggard.", "Hai imparato qualche mossa, ma ti servirebbe ancora un'arma decente. Scommetto che il maresciallo Haggard potrebbe aiutarti, se gli parlassi.\n\nIl maresciallo Haggard vive in una tenuta nella ⟦Elwynn Forest=Foresta di Elwynn⟧, presso il Campo di Taglio di Vallevante. Ora è in pensione, ma durante la sua carriera ha raccolto parecchio equipaggiamento.\n\nDigli che ti mando io, e con un po' di fortuna avrà un'arma di scorta da offrirti.", nil, "Chi è là?\n\nBurlguard, sei tu?\n\nDevi avvicinarti un po'. I miei occhi non sono più quelli di una volta.\n\nA vederti arrivare così, ti avevo preso per uno gnoll!", 0x0f30a247, 0x28259910, 0x2a45bdb6, nil, 0x9c239c26, "...m." },
  [1667] = { nil, "Recupera il Distintivo del Maresciallo Haggard dall'accampamento di Dead-tooth Jack e torna dal maresciallo Haggard.", "Ti manda Burlguard, eh? Sì, ho delle armi di scorta qui intorno, ma prima ho un compito per te...\n\nTempo fa un furfante dei Defias, Dead-tooth Jack, mi ha ingannato. Era buio, lui indossava un tabarda di ⟦Stormwind=Roccavento⟧ e io l'ho scambiato per il maresciallo Dughan. Mi ha detto che gli serviva il mio vecchio distintivo da maresciallo di ⟦Stormwind=Roccavento⟧ e io gliel'ho dato... e poi è scappato ridendo prima che potessi acchiapparlo!\n\nRiprenditi il mio distintivo! Probabilmente Dead-tooth Jack lo tiene nascosto nel suo accampamento, a sud.", "Hai il mio distintivo? Non voglio nemmeno pensare ai guai che Dead-tooth Jack potrebbe combinare con quello.", "Fantastico, l'hai trovato! Temevo che fosse perso per sempre, usato dai Defias per spacciarsi per un ufficiale di ⟦Stormwind=Roccavento⟧. Beh, ora non succederà, grazie a te.\n\nEcco alcune armi che usavo quando ero maresciallo. Le ho tenute in ottimo stato: scegli pure!", 0x3fd751ee, 0xe3968aa6, 0x35913d6c, 0x0dd5019b, 0xaa14a96f, "e...." },
  [1678] = { nil, "Porta la ⟦Vejrek's Head=Testa di Vejrek⟧ a Muren Stormpike, a ⟦Ironforge=Forgiardente⟧.", "Se vuoi salire di grado tra i guerrieri, è meglio che tu sia <tosto/tosta>. Posso insegnarti nuove mosse, ma prima dimostrami che sai cavartela contro nemici veri.\n\nVejrek è il troll più duro che troverai da queste parti, ed è lui che devi battere. Ha una capanna sulle colline appena a sud del ⟦Frostmane Hold=Covo dei Mantogelido⟧.\n\nPortami la testa di Vejrek e saprò che hai fegato.", "Sei <stato/stata> alla capanna di Vejrek, {name}? È puzza di {race} quella che sento addosso a te?", "Vejrek era proprio brutto, eh? Ben fatto, {name}! Hai la stoffa giusta, ora cominciamo la lezione...\n\nForse non lo sai, ma una buona difesa è molto importante per <un/una> {class}. Ti tiene in piedi contro nemici che abbatterebbero chiunque altro, ed è proprio ciò di cui hanno bisogno i tuoi alleati.", 0x79ac8618, 0x8eeb8a4d, 0x97c7fda5, 0xbfd8004a, 0x4056a577, "e...." },
  [1679] = { nil, "Parla con Muren Stormpike.", "Salve, <guerriero/guerriera>! Sei molto promettente, ma devi ancora imparare qualche trucco, e Muren Stormpike è proprio il nano che fa per te.\n\nTroverai Muren nella Hall of Arms, nel Military Ward di ⟦Ironforge=Forgiardente⟧. Parlagli quando sarai pront<o/a> a imparare cosa significa essere un guerriero.", nil, "Ah, {name}. Ho sentito i guerrieri di Dun Morogh fare il tuo nome in giro. Spero che tu non abbia passato tutto il tempo nelle birrerie!", 0xd9ddd0b2, 0xdec45bd4, 0x8fd9e632, nil, 0x01c660f9, "e..m." },
  [1680] = { nil, "Parla con Tormus Deepforge.", "Ora che hai imparato qualche mossa, è tempo di procurarti un'arma decente. Parla con Tormus Deepforge. Può forgiarti un'arma che di sicuro ti piacerà.\n\nTroverai Tormus qui a ⟦Ironforge=Forgiardente⟧, alla ⟦Great Forge=Grande Forgia⟧.", nil, "Ti ha mandato Muren, eh? Sì, posso forgiarti una bella arma... ma prima ho un favore da chiederti.\n\nNon preoccuparti. È parecchio pericoloso e potrebbe costarti la vita: è esattamente il tipo di lavoro che piace a <un/una> {class}.", 0x9d447a97, 0xc2199bac, 0x02618112, nil, 0xf292e320, "e..m." },
  [1681] = { "⟦Ironband's Compound=Presidio di Ferrocollo⟧", "Porta un carico di ⟦Umbral Ore=Minerale Ombrale⟧ a Tormus Deepforge, a ⟦Ironforge=Forgiardente⟧.", "Il mio mentore, Sturgy Ironband, aveva un presidio a sud del ⟦Helm's Bed Lake=Lago di Lettofreddo⟧, nel Dun Morogh orientale. Lì insegnava l'arte del fabbro, ed era il migliore.\n\nMa un giorno uno dei suoi allievi gli portò un carico di uno strano minerale. Mastro Ironband lo chiamò minerale ombrale ed era impaziente di lavorarlo, ma poco dopo il suo arrivo... una banda di nani ⟦Dark Iron=Ferroscuro⟧ attaccò il suo presidio. Uccisero tutti!\n\nEntra nel Presidio di Ferrocollo, {name}, e vendica la morte del mio maestro. E portami il carico di minerale ombrale che l'ha causata.", "Sei <entrato/entrata> nel ⟦Ironband's Compound=Presidio di Ferrocollo⟧? Hai trovato il minerale ombrale?", "L'hai trovato! Ben fatto!\n\nSpero che tu abbia ucciso un bel po' di nani ⟦Dark Iron=Ferroscuro⟧ durante la ricerca. Temo che il Presidio di Ferrocollo non sarà l'ultimo posto in cui li vedremo.\n\nMa grazie per il minerale, {name}. Non vedo l'ora di lavorarlo e scoprirne le proprietà.", 0x2a3780d0, 0x4a772cf1, 0x9c8b9801, 0xb61614dd, 0xbd6d2250, "....." },
  [1682] = { "Armi di ferro grigio", nil, nil, nil, "Ecco alcune armi, appena uscite dall'incudine e fatte con il nuovo minerale umbratile che mi hai portato!\n\nTe ne prego, {name}, scegli pure!", 0x73849205, nil, nil, nil, 0x676432e2, ".mmm." },
  [1683] = { nil, "Porta il ⟦Horn of Vorlus=Corno di Vorlus⟧ a Elanaria, a Darnassus.", "Prima che io possa insegnarti, devi mostrarmi la tua determinazione.\n\nIl satiro Vorlus Vilehoof ha trovato uno dei nostri pozzi lunari più isolati, a sud-est dell'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧. Ora sguazza al suo interno, contaminandone le acque pure con la sua sozzura.\n\nTrova Vorlus al pozzo lunare e distruggilo. Portami il suo corno come prova e inizierò il tuo addestramento avanzato da guerriero.\n\nIl sentiero per il pozzo lunare è ben nascosto, {name}, ma resta concentrat<o/a> e vigile e lo troverai.", "Hai il corno, {name}? Il nostro pozzo lunare è libero dal demone Vorlus?", "Ben fatto, {name}. È bello sapere che Vorlus è stato sconfitto e il nostro pozzo lunare purificato, ed è bello vedere giovani guerrieri desiderosi di mantenere la nostra amata Teldrassil libera dalla corruzione.\n\nOra cominciamo il tuo addestramento...", 0xd401ffda, 0x5adfba87, 0x8fb16149, 0x049695c0, 0x512c5bec, "e...." },
  [1684] = { nil, "Parla con Elanaria.", "Salute, <guerriero/guerriera>. La tua abilità cresce, ma nella tua professione c'è più di quanto tu possa credere. Per progredire ancora, dovrai presto trovare un maestro.\n\nLa guerriera Elanaria dimora a Darnassus, presso la ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧. Lei può istruirti.", nil, "Ti porgo i miei saluti, {name}. Il tuo nome risuona forte a Darnassus, perché sei promettente. Ma presto vedremo se possiedi la forza di volontà per seguire la via del {class}.", 0x521e2628, 0x1d103619, 0xe3640e54, nil, 0xee8cf141, "e..m." },
  [1685] = { "La convocazione di Gakin", "Presentati a Gakin the Darkbinder nel ⟦Mage Quarter=Quartiere dei Maghi⟧ di ⟦Stormwind=Roccavento⟧.", "Non va sempre così? Ti ho cercato tutto il giorno senza trovarti, e ora che non me lo aspetto mi vieni incontro dritto dritto.\n\nHo già perso abbastanza tempo a cercarti, quindi non ti tratterrò oltre. Il maestro Gakin ti ha convocato per un ulteriore addestramento. Secondo me dovresti andare da lui il prima possibile.\n\nLo troverai nel seminterrato della taverna Slaughtered Lamb. A proposito, forse è meglio che tu tenga per te quel posto. Non vogliamo che se ne sparga la voce.", nil, "Era ora che ti facessi vedere. Anche se forse avrei dovuto mandare qualcuno più capace di Remen a cercarti.\n\nPoco importa.\n\nSei rimast<o/a> troppo a lungo senza addestramento, e uno stregone senza addestramento difficilmente tiene la testa sulle spalle a lungo.", 0xafbad200, 0xd830dab8, 0x7de17495, nil, 0x9da53ed7, "...m." },
  [1686] = { nil, "Porta 8 carichi di ⟦Elunite Ore=Minerale d'Elunite⟧ e il Medaglione di Elura a Elanaria, a Darnassus.", "Hai imparato molto, {name}. Ora ti forgeremo un'arma. Un'arma da guerriero.\n\nPer farlo, devi recarti a ⟦Darkshore=Rivafosca⟧.\n\nTanto tempo fa una nave si schiantò sugli scogli vicino al faro di Auberdine, disperdendo molte casse di minerale d'elunite sul fondo dell'oceano.\n\nPrima devi sconfiggere la guardiana dell'elunite, la Shade of Elura. Un tempo era il capitano della nave, e si è condannata a vagare negli abissi per proteggere il suo carico per l'eternità. Sconfiggila, prendi il suo medaglione e raccogli le casse di elunite perdute.", "Hai sconfitto la Shade of Elura, {name}? E hai il minerale d'elunite perduto?", "Coraggiosamente fatto, {name}.\n\nHai dato alla Shade of Elura la pace che meritava, e useremo l'elunite raccolta per forgiarti un'arma pregiata.", 0x8040e914, 0x47fcac4e, 0x0ae1f260, 0x77ddb931, 0xe02c3ab9, "e...." },
  [1688] = { nil, "Recupera il ⟦Surena's Choker=Girocollo di Surena⟧ per Gakin the Darkbinder, a ⟦Stormwind=Roccavento⟧.", "Avevo un'allieva di nome Surena Caledon. Stava dove ora stai tu, desiderosa di imparare la magia degli stregoni, e con un talento non da poco. Inoltre era giovane e piacevole alla vista. Se solo l'avessi capito allora, quella sgualdrina traditrice!\n\nQuella ladra è scappata con uno dei Defias, Erlan Drudgemoor. La sua perdita conta poco, ma le avevo regalato un girocollo con sanguinite che devo riavere.\n\nLa sua vita ormai non significa nulla per me. La troverai al ⟦Brackwell Pumpkin Patch=Campo di Zucche dei Pozzonero⟧. Recupera ciò che è mio.", "Anche i più anziani e saggi possono perdere la testa per le lusinghe della giovinezza e della bellezza, {name}. Un consiglio che faresti bene a ricordare per tutta la vita.", "Surena aveva talento, ma non abbastanza per padroneggiare da sola la magia degli stregoni. È un peccato veder sprecato del talento, ma a volte è necessario.\n\nSpero che il mio investimento su di te dia risultati diversi.", 0x9384a1d7, 0xbd6285ef, 0x7fe37381, 0x1aeacf64, 0x26838f1f, "e...." },
  [1689] = { "Il vincolo", "Usando il ⟦Bloodstone Choker=Girocollo con Sanguinite⟧, evoca e sottometti un'ombra del Vuoto, poi riporta il ⟦Bloodstone Choker=Girocollo con Sanguinite⟧ a Gakin the Darkbinder a ⟦Stormwind=Roccavento⟧.", "Recuperando il mio girocollo e battendo Surena, hai dimostrato di essere capace almeno quanto lei.\n\nDetto questo, vedo che hai un disperato bisogno di addestramento. Sai gestire i flussi della magia, certo, ma essere <uno/una> <stregone/strega> è molto più di questo.\n\nTi mostrerò come comandare un'ombra del Vuoto, ma prima devi evocarne una presso un cerchio d'evocazione e sottometterla con tutte le armi, fisiche e magiche, che hai a disposizione. Usa la magia di questo girocollo nel cerchio d'evocazione qui sotto.", "Non posso mostrarti come controllare un'ombra del Vuoto finché non ne avrai sottomessa una.", "Hai fatto meglio di quanto mi aspettassi, {name}, e bene quanto speravo. Ora puoi imparare a comandare l'ombra del Vuoto che hai soggiogato, un alleato che troverai prezioso nelle prove che di certo ti attendono.\n\nPer ora non ho altro da insegnarti, ma con te sono ben lontano dall'aver finito, {name}.", 0x5926988f, 0x4d76bd4b, 0xe97faec4, 0xe581a55d, 0xfecce601, "....." },
  [1692] = { "Il fabbro Mathiel", "Porta la ⟦Case of Elunite=Scatola di Elunite⟧ al fabbro Mathiel.", "Ho messo l'elunite che hai raccolto in una scatola. Portala al fabbro Mathiel e forgerà per te un'arma di elunite.\n\nMathiel si trova a sud, dall'altra parte di questo edificio.", "Salute, giovane {class}. Come possono servirti le mie abilità?", "Ah, minerale di elunite. È un ottimo metallo da lavorare, perché è benedetto dalla dea Elune in persona. Sarà un onore forgiare armi con esso.\n\nAttendi, ti prego, mentre lavoro...", 0xfd66549a, 0x228e326e, 0x6be6ff55, 0x8c6ab610, 0xf4a34bbc, "....." },
  [1693] = { "Armi di elunite", nil, nil, nil, "{name}, ho forgiato queste armi con l'elunite che mi hai portato. Ti prego, prendi quella che ti si addice di più.\n\nE devo ringraziarti. Lavorare l'elunite è al tempo stesso un onore e un piacere.", 0x0ad2a7a8, nil, nil, nil, 0xf1481cc9, ".mmm." },
  [1698] = { nil, "Parla con Yorus Barleybrew.", "Yorus Barleybrew ha lanciato una sfida a tutti i guerrieri capaci dell'⟦Alliance=Alleanza⟧. Aspetta alla locanda di ⟦Lakeshire=Borgolago⟧, a ⟦Redridge=Crestarossa⟧, e promette una grande ricompensa a chiunque riesca a superare la sua prova.", nil, "Ah! Allora hai sentito della mia sfida, eh?\n\nBe', siediti e ascolta. Bevi qualcosa, e goditelo... perché potrebbe essere l'ultimo.", 0xcd09cdbf, 0x341329a1, 0x3bd4b7dc, nil, 0xf107d207, "e..m." },
  [1699] = { "La sfida di Rethban", "Entra nelle ⟦Rethban Caverns=Caverne di Rethban⟧, raggiungi il primo bivio e torna da Yorus Barleybrew entro il tempo concesso.\n\nNon devi morire né liberare il tuo spirito.", "La mia sfida la chiamo la Sfida di Rethban. Per superare la prova, tutto ciò che devi fare è entrare nelle ⟦Rethban Caverns=Caverne di Rethban⟧, arrivare al primo bivio e tornare qui. Facile! Solo che ci sono un paio di intoppi...\n\nDevi tornare entro un'ora.\n\nSulla strada ci sono mucchi interi di Redridge Gnoll.\n\nPrima di partire, devi buttare giù un sorso della bevanda tipica della mia famiglia: l'⟦Barleybrew Scalder=Ustionante dei Maltorzo⟧!\n\nAllora, che ne dici? Le ⟦Rethban Caverns=Caverne di Rethban⟧ sono sulle colline a nord di ⟦Lakeshire=Borgolago⟧. Sei <pronto/pronta> ad affrontare la Sfida di Rethban?", "Il tempo stringe, {name}. Fossi in te, mi muoverei...", "Ce l'hai fatta! Ben fatto! Tre urrà per {name}!", 0xd10a48fe, 0xa8194546, 0xfd08c428, 0x9b73f4f5, 0x9fe48580, "....." },
  [1700] = { nil, "Porta la ⟦Furen's Notes=Lettera di Furen⟧ a Grimand Elmore.", "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre forgiavo la tua armatura, e devo farli avere a Grimand Elmore. È qui nel Dwarven District, nella bottega d'armi.\n\nE abbassati quando glieli consegni. È orgogliosissimo della sua abilità e non gli piacerà l'idea di imparare qualcosa da me...", "Salve, ben trovat<o/a>. Come posso esserti utile?", "L'ha scritto Furen? Come osa! Ma se gli ho insegnato tutto quello che sa! Pensare che possa insegnarmi qualcosa è oltraggioso! Oltraggioso!\n\nMm... però nei suoi appunti c'è qualcosa che vorrei provare...", 0x32eacdf3, 0x7caa129c, 0x4e71336d, 0xe126afd2, 0x9f7c1433, "e...." },
  [1701] = { "Maglia indurita col fuoco", "Raccogli i materiali che servono a Furen Longbeard e portaglieli a ⟦Stormwind=Roccavento⟧.", "Allora, ti ho dato un bello scudo, ma non dobbiamo fermarci qui. Conosco i segreti per fare armature di maglia durissime. Non è facile e servono materiali molto rari, ma se sei dispost<o/a> a fare la parte faticosa, te ne farò un pezzo.\n\nChe ne dici, {name}? Se te la senti di accettare la sfida, ti darò una lista di cosa procurarti e dove trovarlo.", "Come procede la caccia al tesoro, {name}? Hai i materiali?", "Hai preso tutto? Incredibile! Avevo paura che quelle chimere ti mangiassero di sicuro!\n\nBe', mettiamoci al lavoro su quell'armatura...", 0x63d079d1, 0x17005a3a, 0x3f524efb, 0x9d29594a, 0x8da07437, "....." },
  [1702] = { "Il fabbro di scudi", "Porta la ⟦Cask of Scalder=Cassa di Ustionante⟧ a Furen Longbeard.", "Hai proprio dimostrato di che pasta sei <fatto/fatta> quando hai affrontato la Sfida di Rethban, {name}. E io mantengo la parola. Ti farò avere la ricompensa che ti ho promesso...\n\nSolo che è a ⟦Stormwind=Roccavento⟧.\n\nParla con il mio amico Furen Longbeard, nel Dwarven District di ⟦Stormwind=Roccavento⟧. È il miglior fabbro di scudi che incontrerai mai, e mi deve un grosso favore.\n\nEcco, porta a Furen questa cassa di ⟦Barleybrew Scalder=Ustionante dei Maltorzo⟧ e chiedigli uno scudo. Te ne darà uno bello.", "Salve! Che siccità di questi tempi, non trovi?", "Ah, ⟦Barleybrew Scalder=Ustionante dei Maltorzo⟧. Roba fantastica! Allora sei <passato/passata> da Yorus, eh?\n\nUno scudo te lo procuro, eccome! Non ne troverai uno migliore, e non è una bugia!", 0x798b8e48, 0xa9d5c007, 0x121a2fd8, 0x9fc39f0a, 0x9c18ee37, "....." },
  [1703] = { nil, "Porta la ⟦Furen's Notes=Lettera di Furen⟧ a Mathiel.", "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre forgiavo la tua armatura, e devo farli avere al fabbro Mathiel. Vive a Darnassus, che è parecchio lontana, ma sono sicuro che sarà molto grato di imparare ciò che ho imparato io.", "Ti porgo i miei saluti, {class}.", "Interessanti, davvero molto interessanti. Il mio collega nano Furen ha fatto una scoperta notevole!\n\nGrazie, {name}. Sarà un onore applicare le sue nuove tecniche alle mie creazioni.", 0xa9224821, 0x7d69410a, 0x9cfdd510, 0xc0241fbe, 0xe16816d1, "e...." },
  [1704] = { nil, "Porta la ⟦Furen's Notes=Lettera di Furen⟧ a Klockmort Spannerspan.", "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre forgiavo la tua armatura, e mi serve qualcuno che li porti a Klockmort Spannerspan. È un fabbro gnomo di ⟦Ironforge=Forgiardente⟧ e quando scoprirà ciò che ho scoperto io... scommetto che si strapperà la barba dall'emozione.", "Buona giornata, o buon mattino, o buonasera. Da quaggiù non si capisce. Allora, hai affari da propormi?", "Oh, cielo! Questi appunti sono fantastici! E non solo... sono incredibili e stupefacenti e mi fanno tremare tutte le ginocchia!\n\nFuren ha fatto una scoperta rivoluzionaria! Una vera scoperta! Non vedo l'ora di provare la sua nuova tecnica!", 0xe7370e5c, 0x8704fda0, 0x6072da24, 0x40580185, 0xcf60d068, "e...." },
  [1705] = { "⟦Burning Blood=Sangue Bruciante⟧", "Porta 20 fiale di ⟦Burning Blood=Sangue Bruciante⟧ e 1 ⟦Burning Rock=Roccia Ardente⟧ a Grimand Elmore, a ⟦Stormwind=Roccavento⟧.", "Mi secca ammetterlo, ma forse Furen ha scoperto davvero qualcosa. Però, per esserne sicuro, dovrò provare le sue tecniche su una nuova armatura. Se mi aiuti con i materiali, {name}, l'armatura sarà tua.\n\nPer fare questa armatura mi servono dei campioni di sangue bruciante e una roccia ardente.\n\nL'unico posto che conosco dove trovarli è ⟦Duskwood=Boscovespro⟧. I worgen Nightbane che si sono stabiliti nella miniera della ⟦Roland's Doom=Rovina di Roland⟧ hanno il sangue bruciante, e il loro capo, Gutspill, avrà la roccia.\n\nChe la fortuna ti renda rapid<o/a>, {name}.", "{name}, hai il sangue bruciante e la roccia? Mi servono per completare l'armatura.", "Ottimo lavoro! Ora, se vuoi scusarmi, ho del lavoro da fare anch'io...", 0xf84ba6ef, 0x5a863d44, 0xd546c7a8, 0x78e76958, 0x46cd6b29, "....." },
  [1706] = { "L'armatura di Grimand", nil, nil, nil, "Stento a crederci! La tecnica di Furen è stata un successo, e quest'armatura dovrebbe resistere a sollecitazioni enormi.\n\nEccola, {name}. E grazie. Non avrei creduto alla scoperta di Furen se tu non avessi raccolto i materiali che mi servivano per verificarla di persona.", 0x1b21ef14, nil, nil, nil, 0x8a3cf8c0, ".mmm." },
  [1708] = { "Corallo di ferro", "Porta 20 carichi di ⟦Searing Coral=Corallo Rovente⟧ a Klockmort Spannerspan, a ⟦Ironforge=Forgiardente⟧.", "Voglio provare le nuove tecniche di Furen Longbeard su un'armatura tutta mia. E visto che tu hai aiutato Furen e lui ha aiutato me, l'armatura sarà tua quando l'avrò finita!\n\nPer completarla mi serve un corallo speciale, il corallo rovente. Cresce in un solo posto: lungo la costa a sud di ⟦Menethil Harbor=Porto di Menethil⟧, nelle ⟦Wetlands=Paludi Grigie⟧.\n\nPortami abbastanza corallo rovente e mi metterò subito al lavoro sull'armatura. E sbrigati, {name}. Sono così impaziente di cominciare che mi si attorcigliano le dita dei piedi!", "Ciao ciao, {name}! Hai il corallo rovente? Non vedo l'ora di mettermi al lavoro!", "Questa sì che è roba buona! Ben fatto! Ora lascia che lo fonda e lo martelli, così posso applicare la tecnica di Furen insieme alla mia e poi vediamo cosa succede!\n\nOh, cielo, oh, cielo! Me lo sento che l'armatura sarà molto molto molto resistente!", 0x95d46a3a, 0x3e28241a, 0x08ca6259, 0xa8ff5a9d, 0x51171b46, "....." },
  [1709] = { "La creazione di Klockmort", nil, nil, nil, "Ecco la tua armatura, {name}. Il procedimento di Furen ha funzionato in modo brillante! Perfetto! Davvero meraviglioso!\n\nPotresti passarci sopra con una macchina d'assedio e tornerebbe subito in forma!", 0xe53f77d4, nil, nil, nil, 0xaafc1252, ".mmm." },
  [1710] = { "Conchiglie Sbiancate dal Sole", "Porta 20 Sunscorched Shell a Mathiel a Darnassus.", "Il mio collega, Furen Longbeard, ha fatto una scoperta che non vedo l'ora di mettere alla prova. Voglio provarla su una nuova armatura che sto studiando, perché credo che le tecniche di Furen daranno risultati superiori.\n\nMi aiuterai? Se raccogli ciò che mi serve per fabbricare l'armatura, ne farò un pezzo in più per te.\n\nMi servono i gusci d'uovo bruciati dal sole delle viverne che vivono a ⟦Highperch=Covoalto⟧, nei ⟦Thousand Needles=Millepicchi⟧. Cerca i gusci sotto i loro nidi e torna da me quando ne avrai raccolti abbastanza.", "Hai i gusci, {name}? Sono molto resistenti, e se ne può ricavare una lacca con cui rivestirò gli anelli della mia nuova cotta di maglia.", "Ah, grazie. Andranno benissimo!\n\nComincerò subito a lavorare all'armatura...", 0xd80ce525, 0x5c836a66, 0x41c7b49e, 0x76aded81, 0x8386f94f, "....." },
  [1711] = { "L'armatura di Mathiel", nil, nil, nil, "Ho finito il tuo pezzo d'armatura, e ne sono molto soddisfatto. Le nuove tecniche di Furen si sono sposate alla perfezione con le mie, e sono certo che quest'armatura si dimostrerà molto resistente.\n\nGrazie, {name}. Che possa servirti bene nelle battaglie future.", 0xf31b6b88, nil, nil, nil, 0x39be4aab, ".mmm." },
  [1715] = { nil, "Presentati a Gakin the Darkbinder nel ⟦Mage Quarter=Quartiere dei Maghi⟧ di ⟦Stormwind=Roccavento⟧.", "Hmph. Un tempo tutti gli stregoni di Khaz Modan venivano addestrati sotto l'egida dei maestri di Gnomeregan, ma ora che siamo stati tutti costretti a trasferirci in questa tana di topi a ⟦Ironforge=Forgiardente⟧, e Magni ha deciso di tenerci d'occhio, dobbiamo mandare i nostri novizi a ⟦Stormwind=Roccavento⟧ per l'addestramento.\n\nPer fortuna Gakin non è uno sprovveduto, quindi imparerai comunque quello che ti serve, ma mi fa ribollire il sangue!\n\nComunque, troverai Gakin nello scantinato dello Slaughtered Lamb, a ⟦Stormwind=Roccavento⟧.", nil, "Ti manda Blackwrench, eh? Quei maledetti stregoni di ⟦Ironforge=Forgiardente⟧ devono rimettere ordine nelle loro cose. Lo spazio e gli insegnanti a ⟦Stormwind=Roccavento⟧ sono quelli che sono. Con tutto questo via vai, prima o poi attireremo l'attenzione.", 0x0d4e536f, 0xd830dab8, 0x5dec5e50, nil, 0x6dd03c2b, "e..m." },
  [1716] = { "Divoratore di anime", "Parla con Takar il Veggente nelle ⟦Barrens=Savane⟧.", "Un sayaad è un divoratore di anime, un dominatore di volontà e un tentatore di cuori. Non conosce altro che il male.\n\nI racconti licenziosi chiamano il demone con il suo nome comune: succube per le femmine, incubo per i maschi.\n\nPer richiamare la creatura serve un'esca. Con un simbolo d'amore come esca, risponderà di certo alla tua chiamata. Sconfiggila e rendila il tuo strumento.\n\nPerò sarà difficile trovare una cosa del genere. Dovresti parlare con Takar il Veggente. Lo troverai nelle ⟦Barrens=Savane⟧ di Kalimdor, vicino a Camp Taurajo.", nil, "La traversata è stata difficile, {name}? Hai fatto molta strada per parlare con me. Ma non temere, so perché Gakin ti ha mandato, e ha fatto bene, perché posso aiutarti nella tua ricerca.", 0xc90e9da6, 0x5802ee48, 0xc237a24d, nil, 0xcb33ee38, "...m." },
  [1717] = { "La convocazione di Gakin", "Presentati a Gakin the Darkbinder nel ⟦Mage Quarter=Quartiere dei Maghi⟧ di ⟦Stormwind=Roccavento⟧.", "{name}! Non mi aspettavo di vederti da queste parti, ma mi era stato ordinato di tenere gli occhi aperti nel caso passassi.\n\nÈ ora che tu riceva altro addestramento, quindi la prossima volta che sei a ⟦Stormwind=Roccavento⟧ passa da Gakin. Ti starà aspettando.", nil, "Sono contento che qualcuno sia riuscito a rintracciarti, {name}. Cominciavo a temere il peggio. Sarebbe un peccato perderti, dopo tutto il tempo che abbiamo investito su di te.\n\nPerò possiamo parlare più tardi. Ora conta solo il tuo addestramento.", 0xafbad200, 0xd830dab8, 0x596c7292, nil, 0x2d466a24, "...m." },
  [1718] = { "L'isolano", "Parla con Klannoc Macleod.", "La tua fama di <guerriero/guerriera> cresce, {name}. Ora è tempo di misurarti con i tuoi pari e vedere quanto vali.\n\nAl largo della costa delle ⟦Barrens=Savane⟧, a sud di ⟦Ratchet=Porto Paranco⟧, c'è un'isola. Si chiama ⟦Fray Island=Isola della Contesa⟧, ed è un luogo dove i guerrieri s'incontrano.\n\nS'incontrano, e si battono.\n\nParla con il capo dei guerrieri dell'⟦Fray Island=Isola della Contesa⟧, Klannoc Macleod. Se ti riterrà degn<o/a>, Klannoc ti guiderà più avanti sul sentiero del guerriero.\n\nPer raggiungere l'⟦Fray Island=Isola della Contesa⟧, cerca le secche del banco di sabbia lungo la Costa dei Mercanti.", nil, "Salve, <guerriero/guerriera>. Mi fa piacere vedere che sei <arrivato/arrivata> sull'⟦Fray Island=Isola della Contesa⟧. Spero che ti piaccia...", 0xc6cccc89, 0x59e047a6, 0xb37036cb, nil, 0x08e60fb9, "...m." },
  [1719] = { "La Rissa", "Uccidi Big Will, poi parla con Klannoc Macleod sull'⟦Fray Island=Isola della Contesa⟧.", "Se vuoi imparare da me, prima devi superare la Rissa. È una prova che noi dell'⟦Fray Island=Isola della Contesa⟧ offriamo ai guerrieri emergenti che si credono duri, e se riesci a superarla saprò che lo sei davvero.\n\nPer cominciare, entra in mezzo a quella folla laggiù e sali sulla grata. Così Twiggy Flathead saprà che sei pront<o/a>, e ti manderà contro degli sfidanti.\n\nBatti tutti gli sfidanti e lui chiamerà Big Will. Uccidi Big Will e torna da me entro il tempo concesso.", "Hai superato la tua sfida?", "Ben fatto, {name}. Hai superato la Rissa!\n\nSei <un/una> <guerriero/guerriera> degn<o/a>, e per me è un onore istruirti...", 0x71a4d209, 0x1003a249, 0x7ffe012e, 0x518944b1, 0xbf82ca14, "....." },
  [1738] = { "Cuordilegno", "Recupera il Cuordilegno a ⟦Ashenvale=Valtetra⟧ e portalo a Gakin the Darkbinder, nel ⟦Mage Quarter=Quartiere dei Maghi⟧ di ⟦Stormwind=Roccavento⟧.", "In preparazione del tuo arrivo, ho usato la mia vista per scrutare il mondo e le nebbie del tempo. Ho trovato ciò che cerchi.\n\nDurante la Guerra degli Antichi, due amanti caddero insieme in battaglia. Dove esalarono l'ultimo respiro crebbe un albero noto come cuordilegno, simbolo del loro amore eterno.\n\nDovrebbe bastare a tentare una succube. Lo troverai nelle Rovine di Ordil'aran, nella parte nord-occidentale della foresta di ⟦Ashenvale=Valtetra⟧.", "La tua ricerca ha avuto successo, {name}?", "Sì, vedo che andrà benissimo, lascia solo che ci lavori un momento...\n\nTakar è un tipo pieno di risorse, non trovi? Se solo riuscissi a convincerlo a tornare alla civiltà.", 0x3723b35c, 0x83326afc, 0x89350d42, 0xe8536f8f, 0x78395298, "....." },
  [1739] = { "Il vincolo", "Usando il ⟦Heartswood Core=Nucleo di Cuordilegno⟧, evoca e sottometti una succube, poi riporta il ⟦Heartswood Core=Nucleo di Cuordilegno⟧ a Gakin the Darkbinder, nello Slaughtered Lamb.", "Con il nucleo di cuordilegno potrai lanciare un incantesimo sul cerchio di evocazione nella cripta qui sotto, per aprire un portale da cui la succube possa passare.\n\nFai attenzione, {name}: le succubi hanno sopraffatto anche le menti più forti.\n\nUna volta che l'avrai battuta e rimandata nel Vuoto, torna da me e ti mostrerò come richiamarla e controllarla.", "A volte mi chiedo se Surena non fosse una succube sotto mentite spoglie, mandata a deformare e distorcere la mia mente... Ah! Credo di darle troppo credito.", "Ben fatto, ben fatto, {name}. Vedo che abbiamo fatto bene a decidere di addestrarti. Le tue prestazioni di certo non deludono.\n\nNon ho alcuna remora a mostrarti come controllare la succube che hai appena vincolato. Osserva attentamente.", 0x5926988f, 0xc70dfe93, 0x0b92f947, 0x111f48b5, 0xc7d74427, "....." },
  [1740] = { "Il ⟦Orb of Soran'ruk=Globo di Soran'ruk⟧", "Trova 3 Frammenti di Soran'ruk e 1 ⟦Large Soran'ruk Fragment=Frammento Grande di Soran'ruk⟧ e riportali a Doan Karhan nelle ⟦Barrens=Savane⟧.", "Quando i demoni della Legione cadono in disgrazia, i loro spiriti vengono imprigionati in globi e distribuiti ai loro maghi e stregoni.\n\nMolti erano portati dai loro servitori su Azeroth. Anche in frammenti, possiedono ancora i poteri dei demoni intrappolati all'interno.\n\nIl globo di Soran'ruk fu spezzato in due parti: una fu ulteriormente frantumata per essere usata dagli accoliti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. L'altra, il pezzo più grande, era in possesso di uno stregone nel ⟦Shadowfang Keep=Forte di Zannascura⟧. Trovali e potrò ricomporlo.", "Mi ci sono voluti molti anni per raccogliere i pezzi del globo di Zargain, ma mi ha servito bene, come sono certo che il globo di Soran'ruk servirà te.", "Sì... Il globo non era molto frammentato, e quasi tutti i pezzi sono qui. È semplice ricomporli, per rendere di nuovo intero Soran'ruk.\n\nHo dedicato la mia vita allo studio dei globi della Legione Infuocata e alla loro ricostruzione. Mi hai fatto un favore raccogliendo questi pezzi da studiare, e te li restituirò, completamente ricostruiti, nella forma che preferisci.", 0x331f56fd, 0xad372c46, 0x452768a2, 0x04ccd818, 0xafeadf79, "....." },
  [1758] = { "Il ⟦Tome of the Cabal=Tomo della Cabala⟧", "Parla con Krom Stoutarm a ⟦Ironforge=Forgiardente⟧.", "Ci vorrà più di un semplice cerchio d'evocazione per far comparire un felhunter da sfidare.\n\nIo e i miei tre accoliti ti aiuteremo a creare i cerchi magici. Ti serve una copia del ⟦Tome of the Cabal=Tomo della Cabala⟧, che abbiamo perduto da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un felhunter senza aiuto.\n\nForse Krom Stoutarm può aiutarti. Ormai è uno stregone itinerante: passa le giornate ad accumulare testi antichi e ad aggirarsi furtivo nella biblioteca di ⟦Ironforge=Forgiardente⟧.", nil, "Il ⟦Tome of the Cabal=Tomo della Cabala⟧? Mmh... mi dice qualcosa. Però qui non l'ho mai visto, e credimi, ricordo ogni libro che leggo.\n\nMmh...\n\nAh, sì! Ne ho visto citazioni nei cataloghi delle biblioteche.", 0x03d040dc, 0x6185a67d, 0x0a3411a2, nil, 0xeb681de0, "...m." },
  [1778] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧.", "Vedrò di organizzarmi per tornare presto a casa. Spero che Stephanie stia bene, laggiù a ⟦Stormwind=Roccavento⟧. Non vedo l'ora di rivederla. Alla prossima, {class}.", nil, "Allora, sei già tornat<o/a>, eh? E di grazia, cosa hai concluso nel tempo che hai passato lontano da qui?\n\nSei riuscit<o/a> ad aiutare una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come... Notevole, {name}, queste sono senza dubbio le azioni di chi segue la Luce.\n\nUn simile sacrificio sarà sempre ricompensato, col tempo.", 0xe91f21c0, 0x04be03fc, 0x7d700dcc, nil, 0x26c0f0e8, "...m." },
  [1779] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Prendi il ⟦Symbol of Life=Simbolo della Vita⟧ e parla con Muiredon Battleforge a ⟦Ironforge=Forgiardente⟧.", "Voglio che tu prenda questo, {name}. Si chiama ⟦Symbol of Life=Simbolo della Vita⟧.\n\nHai dato prova di carità e pazienza, e ora voglio che tu dimostri quanto sei diventat<o/a> abile, sia nel combattimento che nel potere.\n\nMio marito Muiredon è tornato da poco da uno scontro con alcuni nani ⟦Dark Iron=Ferroscuro⟧, ed è scampato per un pelo: è laggiù, a farsi curare le ferite da uno dei nostri sacerdoti.\n\nPrendi il Simbolo e parla con lui. Se riuscirai ad aiutarlo, ci rivedremo presto. Che la Luce risplenda su di te.", nil, "*coff*\n\nBuondì a te, {class}. Non badare alle mie ferite, il buon sacerdote qui si prenderà cura del vecchio Muiredon a tempo debito. Non mi serve ancora il potere di quel ⟦Symbol of Life=Simbolo della Vita⟧ che hai lì.\n\nAllora, mia moglie t'ha mandato a parlare con me, eh? Va bene. Mi prenderò il tempo di parlarti: ti racconterò per filo e per segno cos'è successo a Muiredon e al suo migliore amico Narm, un paladino proprio come te.", 0xe91f21c0, 0x2d923b1f, 0xa605745e, nil, 0x1dd454cc, "...m." },
  [1780] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Porterò questi ai bambini oggi stesso. Ti prego, sta' attent<o/a>, buon {class}. Non capita spesso che <uomini/donne> della tua tempra si facciano vedere in città, ma hai dimostrato che i paladini qui a ⟦Stormwind=Roccavento⟧ non volteranno mai le spalle a chi è nel bisogno.\n\nAddio.", nil, "Sei già tornat<o/a>, {name}. E cosa hai concluso nel tempo che hai passato lontano dalla Cathedral?\n\nHai aiutato una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come... Be', sono colpito, {name}: queste sono senza dubbio le azioni di chi segue la Luce e mette gli altri prima di sé.\n\nUn simile sacrificio sarà sempre ricompensato, col tempo.", 0xe91f21c0, 0x0f3ca705, 0xa762da4f, nil, 0xe78d8da6, "...m.", nil, nil, 0xc898f87d, nil, nil },
  [1781] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Porta il ⟦Symbol of Life=Simbolo della Vita⟧ a Gazin Tenorm a ⟦Stormwind=Roccavento⟧.", "Prendi questo, {name}. Si chiama ⟦Symbol of Life=Simbolo della Vita⟧.\n\nHai dato prova di carità e pazienza, e ora è giunto il momento di vedere se sei abbastanza potente da incanalare uno dei più grandi doni della Luce.\n\nIl mio amico Gazin è tornato da poco da uno scontro con alcuni Defias a Elwynn, vicino alla ⟦Heroes' Vigil=Veglia degli Eroi⟧, ed è scampato per un pelo. È vicino all'altare, a farsi curare le ferite dai nostri sacerdoti.\n\nPrendi il Simbolo e parla con lui. Se riuscirai ad aiutarlo, ci rivedremo presto. Che tu possa crogiolarti nella gloria della Luce.", nil, "*coff*\n\nPiacere di conoscerti, {class}. Non badare alle mie ferite, il buon sacerdote qui stavolta può prendersi cura del vecchio Gazin. Non avrò bisogno del potere di quel ⟦Symbol of Life=Simbolo della Vita⟧ che hai con te... non ancora, almeno.\n\nAllora, Duthorian ti ha mandato a parlare con me, eh? Va bene. Ti racconterò per filo e per segno cos'è capitato a me e al mio amico Henze. E con un po' di fortuna, e un po' di abilità da parte tua, forse puoi ancora aiutarci tutti.", 0xe91f21c0, 0xdb6e8f90, 0x25218c29, nil, 0x4ea87484, "...m." },
  [1782] = { "L'armatura di Furen", nil, nil, nil, "Ecco la tua armatura, {name}. Reggerà agli assalti più violenti, o non mi chiamo Furen Longbeard!\n\nE devo ringraziarti. Ho imparato molto lavorando con i materiali\n\nche mi hai portato. Credo che un giorno farò un'altra scoperta!\n\nManderò ciò che ho imparato ad altri\n\nfabbri dell'⟦Alliance=Alleanza⟧.\n\nDirò loro che mi sei stat<o/a> di grande aiuto, e magari vorranno ricambiare il favore.", 0xe60f030a, nil, nil, nil, 0x2efb420d, ".mmm." },
  [1783] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Prendi il ⟦Symbol of Life=Simbolo della Vita⟧ e resuscita Narm Faulk nel Dun Morogh.", "Stavamo spiando un po' di nani ⟦Dark Iron=Ferroscuro⟧ che si son rintanati a sud del ⟦Helm's Bed Lake=Lago di Lettofreddo⟧. Sapevamo che tramavano qualcosa, così io e Narm abbiam pensato di dare un'occhiata più da vicino... e abbiam visto il loro capo dare ordini a qualcuno dei suoi.\n\nIo e Narm ne abbiam approfittato per farne fuori qualcuno, ma eran più tosti di quel che pensavamo, e altri ci son piombati addosso. Narm m'ha detto di scappare a cercare aiuto, e così eccomi qua.\n\nNarm ha bisogno d'aiuto, e non mi darò pace finché non lo riceve.\n\nCi puoi aiutare, {name}?", nil, "Non so come ringraziarti, <fratello/sorella>.\n\nSe porti il ⟦Symbol of Life=Simbolo della Vita⟧, posso solo supporre che siano stati Tiza e Muiredon a mandarti ad aiutarmi.\n\nÈ vero, sono caduto per mano dei ⟦Dark Iron=Ferroscuro⟧ mentre cercavo di prendere uno dei documenti: ho resistito abbastanza da permettere a Muiredon di fuggire, ma la Luce mi aveva quasi del tutto accolto quando sei <arrivato/arrivata> tu. Il fatto che tu sia <stato/stata> abbastanza potente da usare il Simbolo promette grandi cose per te, ma ne parleremo più tardi.", 0xe91f21c0, 0x0f3fb381, 0x604e878c, nil, 0xb325f61b, "...m.", nil, nil, nil, nil, 0xccfa623a },
  [1784] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Recupera un ⟦Dark Iron Script=Documento dei Ferroscuro⟧ dai nani ⟦Dark Iron=Ferroscuro⟧ vicino a Lettofreddo e torna da Muiredon Battleforge a ⟦Ironforge=Forgiardente⟧.", "Prima che cadessi in battaglia, io e Muiredon avevamo quasi sconfitto una delle spie ⟦Dark Iron=Ferroscuro⟧ vicino a quella casetta. Avevamo visto il loro capitano passargli degli ordini e volevamo ucciderlo e prendere quegli ordini.\n\nAlcuni membri del consiglio di ⟦Ironforge=Forgiardente⟧ non credono ancora che ci siano nani ⟦Dark Iron=Ferroscuro⟧ nel Dun Morogh. Con uno di quei documenti non solo avremo la prova dei loro movimenti, ma forse anche un'idea di cosa stanno tramando.\n\nProcurati uno di quei documenti e portalo a Muiredon, {name}.", "Sei <tornato/tornata>! Che piacere vederti, {name}. Le mie ferite sono guarite e son quasi pronto a tornare al Lago di Lettofreddo, appena riesco a convincere mia moglie che starò bene.", "Ahah! Ce l'hai fatta! Hai salvato Narm e hai trovato la prova che mia moglie deve portare al consiglio. Sei una benedizione della Luce, se mai ne ho vista una... a parte mia moglie, s'intende.\n\nGrazie ancora, {name}.", 0xe91f21c0, 0x552cfc26, 0x107e3082, 0x1db426a0, 0x9d225682, "....." },
  [1785] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧.", "Vedo mia moglie laggiù che già sprizza orgoglio. Faresti meglio a portarci le chiappe alla svelta. Scommetto che ha qualcosa da dirti.\n\nChe la Luce sia con te, possente {class}. Ti cercherò sul campo di battaglia contro il Flagello e quei Ferroscuro, quando sarà il momento.", nil, "Oggi hai reso un grande favore a tutta ⟦Ironforge=Forgiardente⟧, {name}. Sono fiera di contarti tra noi e, se ti senti <pronto/pronta>, vorrei benedirti con questa pergamena. Il ⟦Symbol of Life=Simbolo della Vita⟧ avrebbe funzionato solo nelle mani di un paladino pronto per una delle più grandi benedizioni della Luce: il potere di riportare in vita i morti.\n\nTi insegnerò l'abilità di resuscitare i tuoi compagni. Usala con saggezza, {name}, e grazie, da parte mia, di mio marito e di ⟦Ironforge=Forgiardente⟧.", 0xe91f21c0, 0x04be03fc, 0xa2b7f13a, nil, 0xf9eb3df3, "...m." },
  [1786] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Prendi il ⟦Symbol of Life=Simbolo della Vita⟧ e resuscita Henze Faulk a Elwynn.", "Io e Henze eravamo arrivati alla ⟦Heroes' Vigil=Veglia degli Eroi⟧, un'isola in mezzo al ⟦Stone Cairn Lake=Lago del Memoriale⟧, nel nord-est di Elwynn. Avevamo sentito che i Defias si erano infiltrati entro i nostri confini e volevamo delle prove da portare ai consiglieri del re.\n\nAbbiamo visto un paio di quei farabutti che esaminavano dei documenti e li abbiamo attaccati. Purtroppo siamo stati subito sopraffatti da altri maghi.\n\nHenze li ha trattenuti mentre io scappavo... quello sciocco, a fare l'eroe.\n\nÈ ancora là fuori, Henze. Puoi aiutarci, {name}?", nil, "Grazie, <fratello/sorella>.\n\nVisto che impugni il ⟦Symbol of Life=Simbolo della Vita⟧, posso supporre che ti abbiano mandato Duthorian o Gazin?\n\nSono caduto per mano degli incantatori Defias mentre io e Gazin cercavamo di sottrarre loro i piani: ho resistito abbastanza da permettere a Gazin di fuggire, ma alla fine la loro magia mi ha sopraffatto.\n\nMa tu sei <riuscito/riuscita> a riportarmi indietro: la capacità di usare il Simbolo non è data a chiunque, {name}. È di buon auspicio che tu sia <riuscito/riuscita> a infondergli potere con la tua fede.", 0xe91f21c0, 0x4eb84a7e, 0xddf00bb3, nil, 0xd0b687e0, "...m.", nil, nil, nil, nil, 0xe3b33add },
  [1787] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Recupera un ⟦Defias Script=Documento dei Defias⟧ dai Defias Rogue Wizard a Elwynn e torna da Gazin Tenorm a ⟦Stormwind=Roccavento⟧.", "Avremo tempo di parlare ancora del Simbolo più avanti. Ora la cosa importante è recuperare i documenti che abbiamo visto esaminare dai Defias. Se riusciamo a metterci le mani sopra, potremo dimostrare che i Defias si sono infiltrati a Elwynn e, speriamo, capire qualcosa dei loro piani.\n\nPer ora non sono in condizione di combattere, {name}. Credi di essere abbastanza forte da prendere quei documenti ai Defias qui sull'isola?\n\nSe riesci a prenderli, portali a Gazin e digli che sto bene.", "Henze è salvo, {name}? Ci sei <riuscito/riuscita>?\n\nTra la tua abilità con le armi e il potere della Luce, immagino che la ⟦Heroes' Vigil=Veglia degli Eroi⟧ sia al sicuro da qualunque minaccia dei Defias, ma spetta al re e ai suoi consiglieri dirlo.", "Magnifico! Ce l'hai fatta, e hai salvato Henze. La Luce è di certo con te, {name}!", 0xe91f21c0, 0x09e322c6, 0xb07e8693, 0x78c1898e, 0x3eda4356, "....." },
  [1788] = { "Il ⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Porterò il documento ai consiglieri del re dopo che Duthorian gli avrà dato un'occhiata, ma nel frattempo dovresti andare subito a parlare con Duthorian. Di sicuro vorrà darti una pacca sulla spalla!\n\nGrazie ancora, {name}. Spero che ci rivedremo. Sono fiero di avere al mio fianco qualcuno come te e di chiamarti <amico/amica>.", nil, "Oggi hai fatto un ottimo lavoro, {name}. Dovresti essere <orgoglioso/orgogliosa> di ciò che hai compiuto.\n\nE ancor di più dovresti essere <orgoglioso/orgogliosa> delle tue capacità. Non tutti possono usare il potere del ⟦Symbol of Life=Simbolo della Vita⟧. Invocare la Luce per riportare in vita i morti significa che sei <pronto/pronta> per uno dei più grandi onori di un paladino: il potere della resurrezione.\n\nAvrai il potere di riportare indietro i compagni caduti, proprio come hai fatto con Henze.\n\nStammi bene, {name}. La Luce risplende su di te e dovresti accoglierla pienamente.", 0xe91f21c0, 0x0f3ca705, 0xd2692364, nil, 0xaecaeccf, "...m." },
  [1789] = { "Il ⟦Symbol of Life=Simbolo della Vita⟧", nil, nil, nil, "Affrettati, {name}: se fallisci, è in gioco più di una vita.\n\nSe per qualche motivo non riuscirai ad aiutare Muiredon e Narm, torna da me e ti darò un altro ⟦Symbol of Life=Simbolo della Vita⟧ per il tuo viaggio.\n\nNon scambiare il mio aiuto per semplice carità: devi dimostrarti degn<o/a> come qualunque altro {class}, e i fallimenti ripetuti potrebbero ricadere su di te in futuro.", 0x69ed2c55, nil, nil, nil, 0xf2e6ba1d, ".mmm." },
  [1790] = { "Il ⟦Symbol of Life=Simbolo della Vita⟧", nil, nil, nil, "Affrettati, {name}: se fallisci, è in gioco più di una vita.\n\nSe per qualche motivo non riuscirai ad aiutare Gazin e Henze, torna da me e ti darò un altro ⟦Symbol of Life=Simbolo della Vita⟧ per il tuo viaggio.\n\nNon scambiare il mio aiuto per semplice carità: devi dimostrarti degn<o/a> come qualunque altro {class}, e i fallimenti ripetuti potrebbero ricadere su di te in futuro.", 0x69ed2c55, nil, nil, nil, 0x3f42f7b3, ".mmm." },
  [1791] = { "L'osservatore dei venti", "Parla con Bath'rah the Windwatcher.", "Ora che hai imparato la Postura da Berserker, vorrai una bella arma con cui usarla.\n\nParla con Bath'rah the Windwatcher, un eremita troll che vive tra le ⟦Alterac Mountains=Montagne d'Alterac⟧ e le ⟦Western Plaguelands=Terre Infette Occidentali⟧. È un abile fabbricante d'armi e un potente sciamano.\n\nPer trovare Bath'rah, raggiungi il fiume che scorre lungo il fianco orientale del Mulino di Tarren. Seguilo verso nord: Bath'rah è accampato vicino alle rovine che sorgono sulla riva orientale del fiume.", nil, "Hai viaggiato molto, giovane <guerriero/guerriera>. Vedo il fuoco nei tuoi occhi. Cerchi un'arma di grande potere, vero?\n\nPosso aiutarti nella tua impresa. E tu puoi aiutare me nella mia.", 0xb6038666, 0x3cac39b3, 0xea9f0083, nil, 0xbb0930b4, "...m." },
  [1793] = { "Il ⟦Tome of Valor=Tomo del Valore⟧", nil, nil, nil, "È stato dimostrato che la Luce è con te, {name}, ma con tempi sempre più pericolosi diventa importante sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?\n\nIl coraggio, in qualunque situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella ⟦Cathedral of Light=Cattedrale della Luce⟧.", 0xdaebf666, nil, nil, nil, 0x66a0b620, ".mmm." },
  [1794] = { "Il ⟦Tome of Valor=Tomo del Valore⟧", nil, nil, nil, "È stato dimostrato che la Luce è con te, {name}, ma con tempi sempre più pericolosi diventa importante sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?\n\nIl coraggio, in qualunque situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella ⟦Cathedral of Light=Cattedrale della Luce⟧.", 0xdaebf666, nil, nil, nil, 0x66a0b620, ".mmm." },
  [1795] = { "Il vincolo", "Usando il ⟦Tome of the Cabal=Tomo della Cabala⟧, evoca e sottometti un vilsegugio, poi riporta il ⟦Tome of the Cabal=Tomo della Cabala⟧ a Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "Se sei <pronto/pronta> a sufficienza, allora cominciamo. Lascia che ti spieghi il procedimento.\n\nInizierò creando il cerchio di evocazione di base. Quando avrò finito, i miei accoliti useranno le verghe di incanalamento per creare il cerchio maggiore.\n\nFatto questo, leggi l'incantesimo dal ⟦Tome of the Cabal=Tomo della Cabala⟧ e il vilsegugio verrà richiamato. Fa' attenzione, {name}. Un vilsegugio è un avversario potente, e mi piacerebbe vederti con la testa ancora sulle spalle.", "Ogni stregone dovrebbe avere un vilsegugio al suo comando. Per quanto sia difficile da domare, i poteri che conferisce al suo padrone ne valgono ampiamente il prezzo.", "Devo dire che sono colpito, {name}. Quando ho affrontato il mio vilsegugio, ne sono uscito a malapena vivo. Sento che hai il potenziale per diventare uno degli stregoni più potenti di quest'epoca.", 0x5926988f, 0x90eb7a27, 0x5d293135, 0x6582b8e7, 0x2ff39446, "....." },
  [1798] = { "In cerca di Strahad", "Parla con Strahad Farsan nelle ⟦Barrens=Savane⟧.", "È ora che tu impari a evocare il felhunter, {name}. Qui non ho i reagenti e gli oggetti necessari per insegnartelo, quindi dovrai cercare un altro membro della nostra cerchia ristretta, Strahad Farsan.\n\nRisiede nel porto goblin di ⟦Ratchet=Porto Paranco⟧. Manderò un messaggio prima di te per avvisarlo del tuo arrivo.", nil, "{name}? Ah, certo. Il nostro ultimo prodigio. La realtà non è mai all'altezza della leggenda, temo.\n\nPoco importa, sei qui per imparare, non per sentirmi fare battute a me stesso.", 0x884bfbbe, 0xe2b6e98e, 0xd43a3b1f, nil, 0x5156dbd9, "...m." },
  [1801] = { "Il ⟦Tome of the Cabal=Tomo della Cabala⟧", "Parla con Jorah Annison a ⟦Undercity=Sepulcra⟧.", "Ci vorrà più di un semplice cerchio d'evocazione per far comparire un felhunter da sfidare.\n\nIo e i miei tre accoliti ti aiuteremo a creare i cerchi magici. Ti serve una copia del ⟦Tome of the Cabal=Tomo della Cabala⟧, che abbiamo perduto da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un felhunter senza aiuto.\n\nForse Jorah Annison può aiutarti. Oggi lavora come cartografo a ⟦Undercity=Sepulcra⟧, ma conosce i testi antichi meglio di chiunque altro io conosca.", nil, "Cartografia! Immagini, stime della realtà. Non so che farmene.\n\nNei libri, nella narrazione, nella descrizione! È lì che sta la verità. Darei tutte le mappe di questo negozio per un solo libro sull'ascesa della negromanzia, o per un racconto del trionfo della Dama Oscura.", 0x03d040dc, 0x9994065e, 0x3090f470, nil, 0x8e93fa06, "...m." },
  [1802] = { "Il ⟦Tome of the Cabal=Tomo della Cabala⟧", "Recupera il ⟦Moldy Tome=Tomo Ammuffito⟧ e il ⟦Tattered Manuscript=Manoscritto Cencioso⟧ per Krom Stoutarm a ⟦Ironforge=Forgiardente⟧.", "È andato perduto, ma si ha qualche idea di dove potrebbe trovarsi.\n\nNe fu fatta una sola copia, che a un certo punto venne vandalizzata: gran parte delle pagine fu strappata dalla rilegatura. Si dice che in qualche modo sia finita nelle mani dei centauri dei ⟦Thousand Needles=Millepicchi⟧.\n\nIl resto andò perduto al largo della costa a ovest di ⟦Southshore=Riva del Sud⟧, mentre veniva trasportato via nave a ⟦Menethil Harbor=Porto di Menethil⟧. Non arrivò mai.\n\nIn cambio di queste informazioni ti chiedo solo una cosa: se lo trovi, portamelo, così potrò vederlo.", "Le voci si sono rivelate vere, {name}?", "Fantastico! Ora potrò unirmi alla schiera dei pochi che ne hanno visto il contenuto.\n\nNon vedo l'ora di studiare meglio questo testo. È un gran giorno, {name}! Permettimi solo di dargli un'occhiata prima che tu riparta. Sono sicuro che Strahad sarà disposto a mandarmene una copia.", 0x03d040dc, 0x10b05201, 0x03736d31, 0xe389e673, 0x24a83959, "....." },
  [1803] = { "Il ⟦Tome of the Cabal=Tomo della Cabala⟧", "Recupera il ⟦Moldy Tome=Tomo Ammuffito⟧ e il ⟦Tattered Manuscript=Manoscritto Cencioso⟧ per Jorah Annison a ⟦Undercity=Sepulcra⟧.", "Ah! Vedo che sei <uno/una> <stregone/strega> con gusti simili ai miei. Davvero, procurarsi il ⟦Tome of the Cabal=Tomo della Cabala⟧ è un'aspirazione degna. Sapevi che un tempo era custodito tra le mura di Lordaeron? Però fu vandalizzato, e quasi metà delle pagine fu strappata. Chi commetterebbe un atto così infame?\n\nQuella metà è perduta, anche se si dice che sia finita nelle mani dei centauri dei ⟦Thousand Needles=Millepicchi⟧.\n\nIl resto del testo doveva essere trasferito a ⟦Ironforge=Forgiardente⟧, ma andò perduto durante il viaggio, sulla costa a ovest di ⟦Southshore=Riva del Sud⟧.", "Forse stai inseguendo delle favole, {name}, ma anche nel cuore delle voci più assurde si può trovare la verità.", "Bene bene bene! Che cosa abbiamo qui?\n\nÈ impressionante, {name}. Non l'avrei creduto possibile, eppure eccolo qui, proprio tra le mie mani: il ⟦Tome of the Cabal=Tomo della Cabala⟧ completo.\n\nPermettimi di sfogliarne le pagine solo per un momento, prima che tu riparta.", 0x03d040dc, 0x7c0192c1, 0x75503650, 0x7b7b1d9c, 0x47a791b4, "....." },
  [1804] = { "Il ⟦Tome of the Cabal=Tomo della Cabala⟧", "Porta il ⟦Reconstructed Tome=Tomo Ricostruito⟧ e 3 Rod of Channeling a Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "Be', ehm, è difficile separarsene. Ma l'hai trovato tu, e di certo hai cose più importanti da farci. Solo, per favore, ricordati di dire a Strahad che ne volevo una copia.\n\nMentre eri via, ti ha mandato un messaggio. Voleva che ti dicessi che, perché i suoi accoliti ti aiutino con l'evocazione, dovrai procurarti tre verghe della canalizzazione.\n\nLui forse non sa dove trovarle, ma io sì! L'ultima volta le usavano gli orchi del clan delle Fauci di Drago, nelle ⟦Wetlands=Paludi Grigie⟧. Io controllerei i loro incantatori!", "È da un po' che non ti si vede da queste parti. Hai trovato il tomo e le verghe?", "Ben fatto! Il ⟦Tome of the Cabal=Tomo della Cabala⟧ e tre verghe della canalizzazione intatte... be', un po' graffiate, direi.\n\nSarà interessante. È da un po' che un giovane stregone non affronta un felhunter per farlo suo.", 0x03d040dc, 0x9ef106aa, 0x55a37205, 0x5476cf47, 0x6c5768db, "....." },
  [1805] = { "Il ⟦Tome of the Cabal=Tomo della Cabala⟧", "Porta il ⟦Reconstructed Tome=Tomo Ricostruito⟧ e 3 Rod of Channeling a Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "È uno dei testi più interessanti che abbia esaminato negli ultimi anni. Qui la scelta è scarsa, quasi solo libri di geografia, e li ho già letti tutti. Spero che Strahad mi mandi una copia di questo tomo quando ne avrà l'occasione.\n\nA proposito, mi ha mandato un messaggio mentre eri via. Per il tuo compito devi procurarti tre verghe della canalizzazione.\n\nPer avermi permesso di guardare questo testo, ti svelerò un segreto: troverai le verghe addosso agli orchi del clan delle Fauci di Drago, nelle ⟦Wetlands=Paludi Grigie⟧.", "Sì, {name}? In cosa posso esserti utile?", "Ben fatto! Il ⟦Tome of the Cabal=Tomo della Cabala⟧ e tre verghe della canalizzazione intatte... be', un po' graffiate, direi.\n\nSarà interessante. È da un po' che un giovane stregone non affronta un felhunter per farlo suo.", 0x03d040dc, 0x9ef106aa, 0x30425814, 0x88bc1a02, 0x6c5768db, "....." },
  [1806] = { "La prova della rettitudine", "Aspetta che Jordan Stilwell finisca di forgiare un'arma per te.", "Perché non andiamo alla forgia e cominciamo? Mi preparo al tuo arrivo da un po', quindi non dovrebbe volerci molto.\n\nQuando avremo finito, sarai molto più <pronto/pronta> a difendere la Luce di prima: questo te lo giuro.\n\nSarò sincero, almeno in parte, {name}: vedere i frutti delle tue imprese mi rende un po' invidioso. Ma sapere di poter contribuire alle tue avventure a modo mio, e non poco, mi dà una certa gioia.", nil, "Eccola, {name}. Un'arma degna di un campione della Luce come te. Le ho dato il nome di un grande paladino nanico che era mio amico. Si chiamava Verigan... Bosch Verigan.\n\nTi prego, prendila a nome mio e di mia moglie. Abbiamo con te un grande debito, e il mondo sarà un posto più sicuro con qualcuno della tua abilità in giro per le terre.", 0xcdb318ba, 0xe85d14f5, 0x581863b3, nil, 0x3f6f787f, "...m." },
  [1818] = { "Parla con Dillinger", "Parla con la Guardia della Morte Dillinger a Brill.", "Mi hanno detto che la Guardia della Morte Dillinger ha un lavoro per qualcuno come te. Se vuoi dimostrare il tuo valore alle forze della Dama Oscura, presentati subito a Dillinger.\n\nLa postazione della Guardia della Morte Dillinger è all'estremità occidentale di Brill, vicino al cimitero.", nil, "Sei qui per una missione? Bene. Ne ho una importante, che metterà alla prova la tua abilità in combattimento... e la tua determinazione nel difendere i Reietti.", 0xf02ed521, 0x1be1f22e, 0x6a039674, nil, 0x7aa141fe, "...m." },
  [1819] = { nil, "Uccidi Ulag the Cleaver, poi parla con la Guardia della Morte Dillinger.", "Quando il Flagello dilagò nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧, ne catturammo uno per studiarlo. Aveva una mente libera e si faceva chiamare Ulag the Cleaver. Ma, sebbene la sua volontà fosse libera, era ancora soggiogato dal Re dei Lich.\n\nSperavamo di trovare un modo per spezzare il controllo del re su Ulag, ma abbiamo fallito. Ora, finalmente, è tempo di liberarlo.\n\nLiberalo, e uccidilo.\n\nAttiva il congegno della pietra a teschio vicino al mausoleo a nord. Questo solleverà il sigillo magico che lo tiene prigioniero.\n\nPoi... tieniti pront<o/a>, {name}.", "Il tuo compito non è ancora portato a termine, {name}. Non è saggio per un guerriero mostrare paura...", "Ben fatto, {name}. Ulag non era un agente qualsiasi del Flagello. Hai dimostrato alle Guardie della Morte, e quindi alla Dama Oscura, di essere <un/una> <guerriero/guerriera> abile e risolut<o/a>, e degn<o/a> di un ulteriore addestramento.", 0xbc5fb5c0, 0x50a8ff39, 0x7f95b19b, 0xf733d594, 0x10babf8b, "e...." },
  [1820] = { "Parla con Coleman", "Parla con Coleman Farthing.", "Hai dimostrato il tuo valore alla Dama Oscura; ora forse puoi dimostrarlo a uno dei suoi sudditi.\n\nColeman Farthing attende un guerriero disposto a essere lo strumento della sua vendetta contro i nemici dei Reietti.\n\nLo troverai nella Gallow's End Tavern, nella parte orientale di Brill.", nil, "Sì, è vero. Ho bisogno della tua abilità in combattimento. I miei mezzi sono modesti, ma il mio compito aiuta sia me sia la causa dei Reietti. Portalo a termine e la tua ricompensa sarà doppia.", 0xdc3a5265, 0xb6fc3d41, 0xfe952d6f, nil, 0x8ccd524f, "...m." },
  [1821] = { "I cimeli degli Agamand", "Porta a Coleman Farthing l'⟦Agamand Family Axe=Ascia della Famiglia Agamand⟧, la ⟦Agamand Family Sword=Spada della Famiglia Agamand⟧, la ⟦Agamand Family Mace=Mazza della Famiglia Agamand⟧ e il pugnale della famiglia Agamand.", "La famiglia Agamand mi dava lavoro quando ero in vita, e fu la causa della mia morte! È giusto che ora gli Agamand siano servitori senza mente del Re dei Lich.\n\nOra voglio le ultime vestigia del loro onore. Entra nella loro cripta di famiglia e sottrai loro i cimeli di famiglia: una spada, un'ascia, un pugnale e una mazza. Portameli!\n\nLa cripta degli Agamand si trova all'estremità nord dei mulini degli Agamand, protetta dal Flagello in agguato e dagli Agamand morti.", "Hai i cimeli, {name}?", "Ah! Li hai recuperati! Ora l'ultima parvenza di onore e di memoria è stata strappata alle maledette terre degli Agamand. La famiglia non esiste davvero più!", 0xc2d69d26, 0x0089ab46, 0x20fc1b75, 0x5bb4ceec, 0x9190acbd, "....." },
  [1822] = { "L'arma di famiglia", nil, nil, nil, "Terrò tre delle armi che mi hai riportato, a ricordo del mio dolore e della mia perdita. Ma ti prego, {name}, scegli il cimelio che preferisci e tienilo per te.\n\nChe ti serva meglio di quanto abbia servito i suoi maledetti proprietari di un tempo.", 0x4b8a763f, nil, nil, nil, 0x46f59d1b, ".mmm." },
  [1823] = { "Parla con Ruga", "Parla con Ruga Ragetotem.", "Sei <un/una> <guerriero/guerriera> abile e sempre più famos<o/a>. Forse sei pront<o/a> per la prova di Ruga Ragetotem? Se è così, cerca Ruga a Camp Taurajo, nelle ⟦Barrens=Savane⟧.\n\nAspetta i guerrieri che rispondono alla sua chiamata.", nil, "Sei qui per la mia prova, {name}?", 0x0d81c230, 0xfe1dd616, 0x7cd5b742, nil, 0x565a3dc1, "...m." },
  [1824] = { "Prova al Field of Giants", "Porta 5 antenne frementi a Ruga Ragetotem, a Camp Taurajo", "Per superare questa prova devi andare a sud, al Field of Giants. Lì troverai un'orda di creature striscianti, simili a insetti. Sono nuove nelle ⟦Barrens=Savane⟧ e non mi piace ciò che annunciano.\n\nPortami le loro antenne ancora frementi, e non perdere tempo, {name}, perché le antenne raccolte non fremono a lungo. Portami le antenne entro il tempo stabilito e avrai superato la prova.", "Hai le antenne? Se le hai, dammele in fretta, perché le antenne frementi non fremono per sempre...", "Ben fatto, {name}! Superando la prova al Field of Giants, compi un altro passo sul cammino del {class}.", 0x0163ae6e, 0x4e25533d, 0xd15e450b, 0x257de42a, 0x90078856, "....." },
  [1825] = { "Parla con Thun'grim", "Parla con Thun'grim Firegaze nelle ⟦Barrens=Savane⟧.", "Thun'grim Firegaze, un rinomato fabbro orco, ha saputo delle tue continue imprese di valore al servizio dell'⟦Horde=Orda⟧. Vorrebbe forgiarti un'armatura completa e ti chiede di parlargli subito.\n\nThun'grim è accampato a est di ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧.", nil, "Sì, sei venut<o/a>. Bene, perché abbiamo molto di cui discutere, io e te.", 0x33f6853a, 0xb0a44244, 0xd434d1d8, nil, 0xe81873e0, "...m." },
  [1838] = { "Armatura brutale", "Porta a Thun'grim Firegaze 15 Smoky Iron Ingot, 10 ⟦Powdered Azurite=Azurite Polverosa⟧, 10 Iron Bar e una ⟦Vial of Phlogiston=Fiala di Flogisto⟧.", "Ho sentito racconti sulla tua forza e sul tuo valore, e desidero forgiare per te un'armatura completa, una compagna che ti aiuti mentre crescono i racconti delle tue grandi gesta.\n\nMa fabbricare quest'armatura sarà un'impresa a sé, {name}. Avrò bisogno del tuo aiuto, e dell'aiuto di altri fabbri dell'⟦Horde=Orda⟧.\n\nEcco, prendi questa pergamena. Ho passato molte notti, lottando con occhi quasi ciechi, a scrivere ciò che mi serve per l'armatura. Portami gli oggetti elencati sulla pergamena e creerò per te il primo pezzo dell'armatura.", "Hai gli oggetti elencati sulla mia pergamena, {name}?", "Hai portato tutto ciò che ti ho chiesto. Ora farò la mia parte...", 0xe5b472c9, 0x27dfd441, 0xb954c562, 0xe662a37f, 0xd8db3e5a, "....." },
  [1839] = { "Ula'elek e i ⟦Brutal Gauntlets=Guanti Lunghi Brutali⟧", "Parla con Ula'elek in Durotar.", "Il fabbro troll Ula'elek forgerà per te i Guanti Lunghi Brutali. Vive in Durotar, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧ con i suoi fratelli ⟦Darkspear=Lanciascura⟧, e attende il tuo arrivo.", nil, "Salute, {name}. Il vecchio Thun'grim mi ha avvisato del tuo arrivo, ma anche se avesse taciuto la tua presenza qui non mi avrebbe sorpreso.\n\nGli spiriti seguono i tuoi progressi, giovane {class}, e mi dicono che molti nemici sono caduti davanti a te.", 0xa8ffb2ac, 0x75ae49c1, 0x7397cc32, nil, 0xd519cab7, "...m." },
  [1840] = { "Orm Stonehoof e l'⟦Brutal Helm=Elmo Brutale⟧", "Parla con Orm Stonehoof a ⟦Thunder Bluff=Picco del Tuono⟧.", "Orm Stonehoof è molto rispettato per la sua abilità. Forgerà per te l'Elmo Brutale.\n\nCercalo a ⟦Thunder Bluff=Picco del Tuono⟧, vicino alla pozza accanto al grande totem al centro della città.", nil, "Salute, {class}. Io sono Orm, e Thun'grim mi dice che vuoi farti forgiare un elmo?", 0x370291ee, 0x52dd8f49, 0xc87c3f2d, nil, 0xd0a23079, "...m." },
  [1841] = { "Velora Nitely e i ⟦Brutal Legguards=Gambali Foderati Brutali⟧", "Parla con Velora Nitely a ⟦Undercity=Sepulcra⟧.", "Si dice che, prima di morire, Velora Nitely fosse una delle migliori armaiole di Lordaeron. La morte, a quanto pare, non ha intaccato il suo talento. Parla con Velora: forgerà i tuoi Gambali Foderati Brutali.\n\nVelora esercita il suo mestiere a ⟦Undercity=Sepulcra⟧, sotto Lordaeron, nel Quartiere del Commercio.", nil, "Sei qui per dei gambali? Ottimo!\n\nEhm... sono io che forgio l'armatura per te, o sei tu che la forgi per me?\n\nEra una battuta. Faceva ridere? Non riesco a capirlo... Ho perso il senso dell'umorismo insieme all'olfatto. Più o meno quando ho smesso di respirare.", 0x5920766a, 0x9b67f952, 0x1f3d9dcd, nil, 0x8b154887, "...m." },
  [1842] = { "Zoccoli di satiro", "Porta 7 Uncloven Satyr Hoof a Ula'elek al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, in Durotar.", "Posso forgiarti un paio di Guanti Lunghi Brutali, e racchiuderanno una grande magia. Ma prima devi raccogliere questa magia e portarmela.\n\nI satiri vivono nel nord-est di ⟦Ashenvale=Valtetra⟧ per via del potere della foresta. Si nutrono della sua purezza, la succhiano e la corrompono. Puoi riconoscere i satiri che hanno assorbito più magia di ⟦Ashenvale=Valtetra⟧ dai loro zoccoli gonfi e non fessi.\n\nQuesti zoccoli racchiudono un grande potere. Mi serviranno per forgiare i tuoi guanti.", "Hai gli zoccoli, {name}? La magia che racchiudono è potente.", "Ah, li hai! Ora, proprio come i satiri hanno succhiato la forza di ⟦Ashenvale=Valtetra⟧, io succhierò il potere racchiuso in questi zoccoli e lo imbriglierò nel mio lavoro...", 0x2ffc2005, 0xb9892d83, 0x2118fb87, 0x16fa27c8, 0x78102431, "....." },
  [1843] = { "⟦Brutal Gauntlets=Guanti Lunghi Brutali⟧", nil, nil, nil, "Grazie, {name}. Questi guanti sono il mio lavoro migliore. Prendili. Indossandoli, porterai onore a me e ai miei antenati.", 0x7fe2d3c0, nil, nil, nil, 0x0724c79b, ".mmm." },
  [1844] = { "Corno di chimera", "Porta un ⟦Galvanized Horn=Corno Galvanizzato⟧ a Orm Stonehoof a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ti forgerò l'elmo, ma devi dimostrarmi di esserne degn<o/a>.\n\nAnnidata nelle propaggini nord-occidentali delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ si trova la ⟦Charred Vale=Valle Bruciata⟧. Un tempo era un luogo verdeggiante, ma ora è profanata e coperta di cenere, e le creature rimaste sono impazzite per il dolore e la disperazione.\n\nÈ lì che ti mando, {name}.\n\nDevi andare nella ⟦Charred Vale=Valle Bruciata⟧ e trovare una matriarca chimera. Uccidila, liberala dalla sua miseria. Portami il suo corno galvanizzato come prova, e io forgerò per te l'elmo.", "Hai il corno? La matriarca è libera dal dolore?", "Hai portato a termine il tuo compito, {name}, e mi hai dimostrato il tuo valore e la tua determinazione. L'elmo sarà tuo...", 0xb8512596, 0x6968948f, 0xc8418ace, 0xc0be4480, 0xb6d733e6, "....." },
  [1845] = { "⟦Brutal Helm=Elmo Brutale⟧", nil, nil, nil, "Ti dono quest'elmo.\n\nGrandi gesta ti hanno condotto da me, {name}, e se la Madre Terra vorrà... gesta ancora più grandi ti attendono.", 0x21f20070, nil, nil, nil, 0x85a88fa6, ".mmm." },
  [1846] = { "Ossa delle Fauci di Drago", "Porta 8 Sturdy Dragonmaw Shinbone a Velora Nitely a ⟦Undercity=Sepulcra⟧.", "Per fare i Gambali Foderati Brutali mi serve un paio di stinchi robusti. Gli orchi Fauci di Drago delle ⟦Wetlands=Paludi Grigie⟧ hanno degli stinchi belli spessi. Mi serviranno i loro.\n\nMa devono essere robusti. Assicurati di metterli alla prova mentre li raccogli. Se riesci a spezzarli a mani nude, non saranno abbastanza robusti per lavorarci.", "Sto aspettando quegli stinchi, {name}. Saranno un'ottima struttura per i tuoi gambali.", "Ben fatto! Sembrano tutti robusti. Credo che andranno benissimo. Agli orchi è dispiaciuto che ti prendessi i loro stinchi, {name}? Si sono lamentati molto?\n\nEra un'altra battuta. Non ridi.\n\nNon sono molto divertente ultimamente, vero...", 0x4a563a64, 0x6f4838f8, 0xd449bda0, 0xa935bc7e, 0xfd8b7f21, "....." },
  [1847] = { "⟦Brutal Legguards=Gambali Foderati Brutali⟧", nil, nil, nil, "Ecco i tuoi gambali, {name}. Fammi sapere come ti stanno o se servono modifiche. Il mio scopo è accontentare! Almeno, lo era.\n\nOggi il mio mestiere non m'importa granché. Ma è sempre meglio che essere un servo senza cervello del Flagello!\n\nCredo.", 0x46ca525e, nil, nil, nil, 0xef27dfd1, ".mmm." },
  [1848] = { "⟦Brutal Hauberk=Usbergo Brutale⟧", nil, nil, nil, "Sono certo che hai sopportato molte fatiche e versato molto sangue per il mio compito, {name}. Ecco il frutto del tuo lavoro.\n\nChe tu possa indossarlo con onore, e un giorno tornare qui con le storie dei servigi che ti ha reso.", 0x152a43f9, nil, nil, nil, 0xf852a004, ".mmm." },
  [1858] = { "La Shattered Hand", "Ruba la chiave di Tazan, poi usala per aprire la sua valigetta e consegnane il contenuto a Therzok nel Cleft of Shadow, a Orgrimmar.", "Lascio a te il compito di aprire la valigetta di Tazan e di tornare da me con il suo contenuto. Il meccanismo di chiusura è complesso, quindi probabilmente la cosa più semplice sarebbe procurarti la chiave.\n\nVisto che non l'hai trovata sul corpo di Tazan, posso solo supporre che l'abbia affidata a qualcun altro... Ah, sì, giusto. Aveva un assistente di nome Gamon. Un ubriacone: con ogni probabilità lo troverai alla taverna. Forse potresti alleggerirlo della chiave senza dare nell'occhio.", "Non è irritante avere l'oggetto del proprio desiderio a portata di mano, ma nessun modo per arrivarci?", "Mmm, ora sì che è interessante. Con questo hai più che dimostrato il tuo valore, {name}. Sono piuttosto colpito. Considerati il membro più recente della Shattered Hand. E prendi questo: credo che ti sarà di grande aiuto in futuro.", 0xaa823b93, 0x4790c9c0, 0xad0f9af3, 0xfafd7288, 0x38c43aa8, "....." },
  [1859] = { nil, "Parla con Therzok nel Cleft of Shadow, a Orgrimmar.", "Abbassa la voce, {name}. Sì, so come ti chiami. Mi hanno detto di tenere d'occhio chi, tra gli orchi, corrisponde alla tua descrizione.\n\nDa quel che abbiamo sentito su di te, sai cavartela in combattimento e non disdegni un po' di furtività ogni tanto.\n\nHo ragione?\n\nComunque, dovresti andare da Therzok a Orgrimmar. Ha un'offerta da farti.", nil, "Molto bene, sono contento che Kaplak sia riuscito a trovarti.\n\nAbbiamo alcune cose di cui parlare, non ultima il tuo futuro con la Mano.", 0x74b10f51, 0x1b7efc2d, 0x5ee00801, nil, 0xacd1469f, "e..m." },
  [1860] = { "Parla con Jennea", "Parla con Jennea Cannon a ⟦Stormwind=Roccavento⟧.", "Noi maghi abbiamo un compito da svolgere. Un compito vitale per la sicurezza di ⟦Stormwind=Roccavento⟧ e della Foresta di Elwynn.\n\nJennea Cannon ha i dettagli. Studia nel santuario dei maghi, nel Quartiere dei Maghi di ⟦Stormwind=Roccavento⟧. Dovresti raggiungerla al più presto.", nil, "Ti hanno mandat<o/a> ad aiutarmi nel mio compito, {name}? Bene. È confortante vedere giovani maghi desiderosi di aiutare la nostra causa...\n\nQuale causa, chiedi? A tempo debito, giovane. Lo saprai... a tempo debito.", 0x7b586e0a, 0x17610de7, 0x833e5a0d, nil, 0x5a63396f, "...m." },
  [1861] = { "⟦Mirror Lake=Lago Riflesso⟧", "Porta un campione d'acqua del ⟦Mirror Lake=Lago Riflesso⟧ a Jennea Cannon a ⟦Stormwind=Roccavento⟧.", "Questo mondo è stato vittima di immense lotte mistiche, che hanno strappato le correnti magiche da canali un tempo stabili. Ci sforziamo di capire quali effetti abbiano causato questi cambiamenti, e alcuni di noi temono il peggio!\n\nMa ti rivelerò di più in seguito. Adesso abbiamo bisogno che tu raccolga informazioni.\n\nEcco, prendi questa fiaschetta. Va' ai piedi della cascata del ⟦Mirror Lake=Lago Riflesso⟧, a sud-ovest delle porte di ⟦Stormwind=Roccavento⟧, e preleva un campione dell'acqua. Riportamelo, così potrò analizzarlo in cerca di contaminazioni magiche.", "Hai il campione, {name}? Il flusso della magia a ⟦Stormwind=Roccavento⟧ e a Elwynn è stato alterato, e devo sapere se sta filtrando nell'acqua.", "Grazie, {name}. Analizzerò quest'acqua per verificarne le proprietà magiche. Speriamo che non ne abbia, altrimenti potremmo scoprire che chi beve troppo a lungo dal ⟦Mirror Lake=Lago Riflesso⟧ ne subirà effetti nocivi.\n\nEcco, {name}. Prendi questo globo o questo bastone come segno del tuo servizio. Che possa servirti bene.", 0x8c5d3612, 0x299fa3ef, 0x14519806, 0x40ceafc2, 0x6ddff8d3, "....." },
  [1879] = { "Parla con Bink", "Parla con Bink a ⟦Ironforge=Forgiardente⟧.", "{name}! Bink, la mia collega gnoma di ⟦Ironforge=Forgiardente⟧, manda a dire che ha un compito da svolgere e non vuole affidarlo a nessuno che non sia un mago! Sei tu <quel/quella> <mago/maga>, {name}?\n\nSe è così, parla con Bink. Passa il suo tempo nella Hall of Mysteries, nel Mystic Ward di ⟦Ironforge=Forgiardente⟧.", nil, "Oh, vedo che hai del potenziale, sì che ce l'hai! Ma ci vuole più del potenziale per essere <un/una> brav<o/a> <mago/maga>. E se non sei <un/una> brav<o/a> <mago/maga>, allora sei <un/una> cattiv<o/a> <mago/maga>. E i cattivi maghi fanno parte del problema, sì che ne fanno parte!\n\nOps, sto correndo troppo. Cominciamo dall'inizio!", 0x0b59c7b3, 0x88f317f6, 0x9decdd73, nil, 0x88e0f9f8, "...m." },
  [1880] = { nil, "Porta a Bink il suo Mage-tastic Gizmonitor.", "Noi maghi non ci limitiamo ad agitare le dita e a fare belle scintille! Noi controlliamo la magia, il tessuto stesso del nostro mondo! E questo richiede grande cura e determinazione. E conoscenza... tantissima conoscenza!\n\nUno dei miei congegni, il Mage-tastic Gizmonitor, raccoglie e conserva quella conoscenza in quantità enormi! Ma l'ho perso! Quando siamo fuggiti dalla nostra casa di Gnomeregan, l'ho lasciato in un forziere in una delle nostre capanne fuori dalla città, e ora il posto brulica di gnomi lebbrosi!\n\nTi prego, {name}, recupera il mio gizmonitor!", "Hai trovato il gizmonitor? Devo averlo prima che la sua riserva di energia si esaurisca!", "Oh, che giornata splendida! Quando ho costruito il gizmonitor non avevo idea di quanto ne sarei diventata dipendente. Ora posso ricominciare i miei studi!\n\nGrazie, {name}! Ed ecco: questi sono stati i miei primi strumenti da maga. Sono un po' graffiati, ma sono ben collaudati. Scegli pure: sono sicura che l'uno o l'altro ti sarà utile.", 0x7e1133b0, 0x694f2e68, 0x57d62cf0, 0x0ab359eb, 0x9bceb030, "e...." },
  [1881] = { "Parla con Anastasia", "Parla con Anastasia Hartwell.", "{name}, Anastasia Hartwell ha un compito per qualcuno con il tuo talento. Parla con lei nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧ e preparati alla tua prima missione per i maghi dei Reietti.", nil, "Salute, {name}. Hai fatto bene a rispondere alla mia chiamata, e farai ancora meglio se darai ascolto a ciò che sto per dirti...", 0xc4711561, 0x6490e08e, 0x892f7df9, nil, 0x8b45b1c1, "...m." },
  [1882] = { "La ⟦Balnir Farmstead=Cascina dei Balnir⟧", "Porta le ⟦Balnir Snapdragons=Dragolose di Balnir⟧ ad Anastasia Hartwell nel ⟦Mage Quarter=Quartiere dei Maghi⟧ di ⟦Undercity=Sepulcra⟧.", "Le ⟦Plaguelands=Terre Infette⟧ a est sono un'aberrazione. Concepite dal Re dei Lich, diffondono la loro magia nel suolo, corrompendo e uccidendo tutto ciò che vive. Sebbene le forze distruttive della piaga abbiano un certo fascino, noi, i maghi dei Reietti, crediamo che sia indisciplinata e vada contenuta.\n\nMa prima dobbiamo misurare quanto si sia diffusa a Tirisfal. Va' alla ⟦Balnir Farmstead=Cascina dei Balnir⟧, nella parte orientale di Tirisfal. Nel giardino ci sono dei fiori: dragolose. Raccoglile e torna qui.", "Hai le dragolose? Quel tipo di fiore è molto ricettivo alle energie magiche, e studiare le dragolose così vicino alle ⟦Plaguelands=Terre Infette⟧ può dirci se la piaga è entrata nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Ah, che bell'esemplare. Lo manderò ai nostri speziali perché lo studino e stabiliscano fin dove si estende la contaminazione delle Terre Infette.\n\nBen fatto, {name}. Per i tuoi servigi ti offro questa scelta: un globo o un bastone. Qualunque sceglierai, ti sarà molto utile.", 0x8e22f419, 0xc51d5d3b, 0x91501431, 0x79fac00f, 0x8fa46f65, "....." },
  [1883] = { "Parla con Un'thuwa", "Parla con Un'thuwa.", "Un'thuwa, mago tribale del ⟦Sen'jin Village=Villaggio di Sen'jin⟧, percepisce un'anomalia nelle correnti magiche di Durotar e chiede aiuto. Parla con Un'thuwa e fa' ciò che puoi per aiutarlo.\n\nFallo, e col tempo ti saranno rivelati altri segreti.", nil, "Salute, {name}. Sia lode a te, perché la mia richiesta d'aiuto ha ora una risposta. Speriamo che tu sia all'altezza del compito...", 0x9f1fb4f6, 0x6d399ba5, 0x6b38ce29, nil, 0x5b11fa4b, "...m." },
  [1884] = { "I cumuli ju-ju", "Distruggi 4 Ju-Ju Heap, poi torna da Un'thuwa al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Lo stregone Zalazane delle ⟦Echo Isles=Isole dell'Eco⟧ ha sconvolto il normale flusso della magia a Durotar. Lo fa tramite feticci contaminati, i cumuli ju-ju, che ha disposto tra le sue capanne sulla principale delle ⟦Echo Isles=Isole dell'Eco⟧.\n\nQuesti cumuli corrompono la fauna selvatica e danno potere agli stregoni e alle creature infernali che si nascondono negli angoli oscuri di questa terra.\n\nDevi distruggere i cumuli ju-ju, {name}, prima che il flusso della magia sia alterato per sempre.", "Devi sbrigarti, {name}. Distruggi i cumuli ju-ju!", "Sento che i cumuli ju-ju di Zalazane sono stati distrutti e, con il tempo e un po' di fortuna, il flusso della magia a Durotar tornerà normale.\n\nHai compiuto una grande impresa per la tua gente, {name}. E hai dimostrato il tuo valore a noi, i maghi dell'⟦Horde=Orda⟧.", 0x565e7ac5, 0x966d5c6b, 0xbc0c0b65, 0xaae3b630, 0xcb8fa40d, "....." },
  [1885] = { nil, "Parla con Mennet Carkad nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧ di ⟦Undercity=Sepulcra⟧.", "{name}? Non proprio quello che mi aspettavo, visto che Carkad in persona si è interessato a te. Ma l'apparenza inganna, giusto?\n\nIn ogni caso, dovresti andare da lui il prima possibile. Non vorresti sapere cos'è successo agli ultimi che hanno scelto di ignorare la sua convocazione.", nil, "Mm. Senza dubbio sei venut<o/a> qui appena hai saputo della mia convocazione, vero? Ma certo. Non mi aspetterei niente di meno da <un/una> aspirante ⟦Deathstalker=Inseguitore della Morte⟧.", 0xe1e85fb2, 0x9601ae12, 0x2bbbbe4a, nil, 0xbfdff15c, "e..m." },
  [1886] = { "Gli ⟦Deathstalkers=Inseguitori della Morte⟧", "Procurati la ⟦Astor's Letter of Introduction=Lettera di Presentazione di Astor⟧ e portala a Mennet Carkad nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧.", "Se vuoi unirti agli ⟦Deathstalkers=Inseguitori della Morte⟧, la guardia scelta di lord Varimathras, dovrai dimostrare il tuo valore.\n\nNon ti mentirò, {name}: questo compito potrebbe costarti la vita.\n\nHo alcune faccende da sistemare. Mi servono gli effetti personali di Astor Hadren, un messaggero che fa la spola tra ⟦Silverpine=Pinargento⟧ e ⟦Undercity=Sepulcra⟧. Lascio a te la scelta del modo in cui procurarteli.\n\nSarà meglio per te sapere poco della natura di questa faccenda. Riesci, e ti dirò di più.", "Hai successi da riferire?", "Ben fatto, {name}. Hai superato la prima parte di questa prova. Speriamo che Andron non abbia avuto sentore delle tue attività, così potremo convincerlo che sei davvero il messaggero che aspetta.", 0x188cbd51, 0xbbe5324e, 0x2203cce3, 0xfd970964, 0x00fc1721, "....." },
  [1898] = { "Gli ⟦Deathstalkers=Inseguitori della Morte⟧", "Parla con Andron Gant a ⟦Undercity=Sepulcra⟧.", "La lettera di presentazione dovrebbe bastare a convincere Andron che sei il messaggero che stava aspettando. Ho già conosciuto Andron: non ha la capacità mentale per essere così sospettoso.\n\nLord Varimathras sospetta che Andron stia aiutando un altro gruppo. Vuole sapere di che organizzazione si tratta e ne esige le prove.\n\nVoglio che tu parli con Andron e ottenga queste informazioni. Lo troverai nella sua bottega vicino all'Apothecarium.", "Salve. Posso fare qualcosa per te?", "Ah, sì, ti stavo aspettando. Non ho dubbi che i nostri comuni conoscenti siano soddisfatti delle informazioni che ho fornito finora, vero?\n\nImmagino sia inutile chiederlo a te, dubito che ti carichino del peso di queste conoscenze. Perché riporre tanta fiducia nel messaggero, eh?", 0x188cbd51, 0xa89dca7e, 0x46557e99, 0xb58298f8, 0x918a8f91, "....." },
  [1899] = { "Gli ⟦Deathstalkers=Inseguitori della Morte⟧", "Porta Astor's Ledger a Mennet Carkad nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧ di ⟦Undercity=Sepulcra⟧.", "Il libro mastro con le informazioni che cercano i tuoi committenti è sullo scaffale dietro di me. Consegnalo con i miei omaggi, e di' loro che preferirei che mandassero te, se lo ritengono abbastanza utile da voler continuare il nostro accordo.", "Ci sei <riuscito/riuscita>, {name}?", "Be', queste sono di certo più informazioni di quante pensassi di ricavare da Andron. Dammi un momento per esaminarle, prima di affidarti il prossimo compito.", 0x188cbd51, 0x4d912e62, 0xed39f886, 0x8d80cd20, 0xf297cc15, "....." },
  [1918] = { "L'elemento contaminato", "Porta il ⟦Befouled Water Globe=Globo d'Acqua Contaminata⟧ a Mastok Wrilehiss, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "L'elementale ucciso ha prodotto un globo d'acqua che brilla intensamente. Il contenuto del globo è, nel migliore dei casi, disgustoso. È lecito supporre che qualunque cosa abbia contaminato le acque del ⟦Mystral Lake=Lago Mystral⟧ sia molto probabilmente presente anche nell'acqua del globo.\n\nNon è proprio chiaro a chi potrebbe interessare una simile scoperta; forse chi ti ha mandato al lago in origine, Mastok Wrilehiss, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, potrebbe avere un'idea.", "Sì, che ti serve?", "Trovi una disgustosa palla d'acqua e decidi di portarla a me? Chi sono io, l'Earthen Ring o qualcosa del genere?\n\nA dire il vero, questo mi dà un'idea... forse per questa faccenda ti serve proprio l'Earthen Ring. Voglio dire, se aiuta a risolvere una volta per tutte la situazione al lago, sono d'accordo.\n\nSai chi sono quelli dell'Earthen Ring, {name}?", 0x21873bc1, 0x3bae8df7, 0x322816ba, 0x25eef297, 0x74f9b004, "....." },
  [1919] = { "Rapporto a Jennea", "Parla con Jennea Cannon a ⟦Stormwind=Roccavento⟧.", "La tua conoscenza dell'arte cresce, giovane {name}. Sei pront<o/a> a cominciare le tue vere lezioni? Sei pront<o/a> a prendere il tuo posto nella guerra segreta che combattiamo?\n\nSe è così, parla con Jennea Cannon, nel santuario dei maghi del Quartiere dei Maghi di ⟦Stormwind=Roccavento⟧. Ha un compito per te che ti aprirà la prima finestra sul mondo invisibile.", nil, "{name}, ho una missione per te, qui nel Quartiere dei Maghi. Ascolta attentamente, perché non c'è tempo da perdere.", 0xc2dfd63b, 0x17610de7, 0xfe7e6834, nil, 0x5ae736c8, "...m." },
  [1920] = { "Indagine al Blue Recluse", "Prendi un ⟦Cantation of Manifestation=Canto della Manifestazione⟧ e un Forziere di Casse di Contenimento da dietro Jennea Cannon. Porta 3 Forziere di Contenimento Pieno a Jennea al Wizard's Sanctum.", "È stato segnalato un disturbo alla taverna Blue Recluse, nel ⟦Mage Quarter=Quartiere dei Maghi⟧. Strane creature invisibili ora vagano per la taverna, e temo che lì si sia aperta una frattura di mana.\n\nVoglio che indaghi nella taverna e catturi quelle creature. Usa il canto della manifestazione nella taverna per renderle visibili, sottomettile e poi usa un forziere di contenimento per catturarle. Quando ne avrai abbastanza, torna da me con i forzieri pieni, quelli vuoti e il canto.", "Hai catturato le creature, {name}? Devono essere studiate per capire il motivo del loro arrivo.", "Ottimo lavoro! Studierò queste creature e, con diligenza e fortuna, scoprirò come sono scivolate nel nostro mondo.\n\nIl tuo valore per la società dei maghi cresce, {name}.", 0x99ff705d, 0x444df4da, 0x4b931a51, 0x411e2ef3, 0x4083ef42, "....." },
  [1921] = { "Raccolta di materiali", "Porta 10 pezze di lino e le 6 Charged Rift Gem a Wynne Larson, a ⟦Stormwind=Roccavento⟧.", "Hai servito bene i tuoi compagni maghi, e ora è il momento di indossare la tua tonaca da mago. Wynne Larson può confezionarla, ma devi portarle i materiali necessari.\n\nLa tonaca sarà fatta di lino, che è facile da trovare, ma dovrai procurarti anche delle gemme della faglia cariche, e l'unico luogo noto dove trovarle è la ⟦Silver Stream Mine=Miniera Vena d'Argento⟧ di Loch Modan, lasciate nelle casse dalla lega dei minatori nani.\n\nRaccogli il lino e le gemme e portali a Wynne Larson, alla Larson Clothiers, nel Quartiere dei Maghi.", "Salve, {name}. Jennea mi aveva detto che saresti venut<o/a>. Hai qualcosa per me?", "Sì, sono ottime pezze di lino. Posso farci una bella tonaca. E dopo averci intessuto le gemme della faglia, avremo un abito degno di un mago!", 0x2c5cc185, 0xcd459eaf, 0x8bb64794, 0xf3259f6b, 0xbad1677b, "....." },
  [1938] = { "⟦Ur's Treatise on Shadow Magic=Trattato di Ur sull'Ombra⟧", "Porta il ⟦Ur's Treatise on Shadow Magic=Trattato di Ur sull'Ombra⟧ all'alto stregone Andromath, a ⟦Stormwind=Roccavento⟧.", "Molto tempo fa, tre maghi studiavano in questa torre, finché uno di loro cedette alle arti oscure. Fu esortato ad allontanarsi da quella magia malvagia, ma non seppe resistere. E così fu bandito.\n\nIl nuovo dominio del mago caduto è la Torre di Ilgalar, a ⟦Redridge=Crestarossa⟧, e ha portato con sé un libro potente: il ⟦Ur's Treatise on Shadow Magic=Trattato di Ur sull'Ombra⟧.\n\nNoi, i maghi di ⟦Stormwind=Roccavento⟧, vogliamo che quel libro ci venga restituito. Entra nella Torre di Ilgalar, trova il tomo nella sua biblioteca e portamelo.", "Hai il libro, {name}? I suoi segreti non sono fatti per chi non ha preparazione, e scandagliarne le profondità può portare a rovina e distruzione.", "Temevo che Morganth avesse nascosto il libro altrove, o che avesse trovato un modo per aprirlo e leggerne il contenuto.\n\nÈ bello vedere che non è così, e che i sigilli che abbiamo posto sul ⟦Ur's Treatise on Shadow Magic=Trattato di Ur sull'Ombra⟧ reggono ancora.", 0x3eab5ca9, 0x5da24331, 0x84778b51, 0xc0beaebd, 0x6a7c0b88, "....." },
  [1939] = { "L'alto stregone Andromath", "Parla con l'alto stregone Andromath.", "L'alto stregone Andromath desidera parlarti, {name}. Si trova in cima al Wizard's Sanctum, nel Quartiere dei Maghi di ⟦Stormwind=Roccavento⟧.\n\nFaresti bene a parlargli, perché Andromath è uno dei maghi più potenti che non siano rinchiusi a Dalaran. Un consiglio da lui è davvero un consiglio prezioso.", nil, "Salute, {name}. Sono lieto di vederti, e spero che tu abbia tempo per ascoltare le parole di un vecchio...", 0xade0a64e, 0xc9d25e42, 0xb1ce8c24, nil, 0x10407ead, "...m." },
  [1940] = { "⟦Pristine Spider Silk=Seta di Ragno Intatta⟧", "Porta 8 ⟦Pristine Spider Silk=Seta di Ragno Intatta⟧ a Wynne Larson, a ⟦Stormwind=Roccavento⟧.", "Il tuo servizio è stato irreprensibile, {name}. Credo che forse sia giunto il momento che tu abbia una veste più raffinata, più adatta al tuo rango di <mago/maga> espert<o/a>. Se raccoglierai i materiali necessari, faremo confezionare la tonaca.\n\nDevi entrare a ⟦Duskwood=Boscovespro⟧ e cacciare i ragni Carrion Recluse. Estrai la loro seta, ma andrà bene solo la seta più fine e intatta. Quando ne avrai abbastanza, portala a Wynne Larson, qui nel Quartiere dei Maghi, alla Larson Clothiers. Sarà lei a confezionare la tua tonaca.", "Ah, sì. I maghi del Wizard's Sanctum mi avevano detto che saresti venut<o/a> a parlarmi. Hai la seta richiesta?", "Begli esemplari, questi. Mi metto subito al lavoro!", 0x0ae2c7a3, 0x2674cfe7, 0x31b76a02, 0x5407cd18, 0x48d28ffb, "....." },
  [1941] = { "⟦Manaweave Robe=Tonaca di Manatrama⟧", nil, nil, nil, "Ecco la tua tonaca. È una delle migliori che abbia mai fatto! Indossala con orgoglio, e quando te lo chiedono... di' che l'hai presa alla Larson Clothiers!", 0xc492652c, nil, nil, nil, 0xf4dc234a, ".mmm." },
  [1942] = { "Veste Logora Astrale", nil, nil, nil, "La tua veste è pronta! E quella seta che hai raccolto era così bella... non ti dispiace se l'ho fatta un pochino più corta per tenere un po' di seta per me, vero?\n\nSto solo scherzando. Ti starà benissimo, ed è perfetta sia per l'avventura sia per le cene eleganti. Goditela!", 0xd423e365, nil, nil, nil, 0x7bdf4eeb, ".mmm." },
  [1943] = { "Parla con Deino", "Parla con Deino.", "La maga troll Deino ha bisogno del tuo aiuto, {name}. Vive a Orgrimmar, nella Darkbriar Lodge.", nil, "Bene, sei venut<o/a>. Il mio compito non è facile, ma è vitale per la società dei maghi. Se mi aiuterai, di certo ne varrà la pena anche per te.", 0xf18219b3, 0x9593292e, 0x3f3b729c, nil, 0x7f8e7e01, "...m." },
  [1944] = { "Le acque di Xavian", "Porta il ⟦Xavian Water Sample=Campione d'Acqua di Xavian⟧ a Deino, a Orgrimmar.", "La leggendaria città di Xavian sorge nascosta nel cuore della parte orientale di ⟦Ashenvale=Valtetra⟧, e i racconti sulla sua antica sapienza sono ben noti tra i dotti. Si dice che le acque di Xavian racchiudano immensi poteri magici.\n\nVorrei un campione di quelle acque, preso alla sorgente.\n\nPrendi questa fiaschetta e va' a Xavian. Raccogli l'acqua ai piedi della sua cascata più alta e torna da me. E fa' attenzione mentre attraversi quell'antica città: ora le rovine sono in mano ai satiri, che non amano i maghi che ficcano il naso nei loro affari.", "Mi fa piacere che tu sia tornat<o/a> con la pelle intatta, {name}. Hai il campione d'acqua? Non vedo l'ora di studiarne le proprietà.", "Ah, molto bene. Immagino che i satiri di Xavian non ti abbiano dato troppi problemi?\n\nGrazie, {name}. Studierò subito questo campione d'acqua di Xavian.", 0x25a8fb6b, 0x69a196d3, 0x453fec0e, 0xc1429ad4, 0x925c63b7, "....." },
  [1945] = { "Le Sorelle Ridenti", "Porta 12 Laughing Sister's Hair a Kil'hala, al ⟦Crossroads=Crocevia⟧.", "Per i tuoi servigi ho fatto in modo che vengano confezionate le tue nuove vesti, purché tu raccolga i materiali necessari...\n\nPer queste vesti devi tornare a ⟦Ashenvale=Valtetra⟧ a prendere le ciocche di capelli delle sorelle ridenti, driadi che si radunano vicino al ⟦Raynewood Retreat=Rifugio di Legnovivo⟧.\n\nQuando avrai i loro capelli, portali a Kil'hala, un sarto troll al ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧. Ti aspetta e confezionerà le tue vesti.", "Salute, {name}. Deino mi aveva detto che saresti venut<o/a> e che avresti portato i capelli delle sorelle ridenti. Li hai?", "Ah, con questi capelli si tesserà una bella tonaca, {name}. Peccato che le sorelle ridenti siano dovute morire per separarsene, anche se dubito che li avrebbero mai ceduti spontaneamente.\n\nUn peccato, ma solo un piccolo peccato.", 0x483fd0b4, 0x404d3b5c, 0x16557f4c, 0x2b62536e, 0x76d06fc5, "....." },
  [1946] = { "Veste di pizzo del Nether", nil, nil, nil, "Ecco il tuo pizzo del Nether, {name}. È comodo e resistente, e racchiude la magia dei capelli delle sorelle ridenti.\n\nGoditelo, e se ti piace, ti prego di dirlo a Deino. È una maga di cui voglio restare nelle grazie...", 0x47a79219, nil, nil, nil, 0xb7ac8288, ".mmm." },
  [1950] = { "A caccia di informazioni", "Trova la frase che apre il forziere di Tirth, poi torna da Tirth.", "Posso aiutarti con il libro, ma prima devi aiutare me!\n\nIl tomo che cerchi è nel mio forziere chiuso con la magia. Per aprirlo bisogna pronunciare una frase speciale, e io non me la ricordo! Di solito è il mio assistente che mi aiuta a ricordare queste cose, ma è sparito.\n\nSe vuoi il mio libro, trova il mio apprendista! Chiedi in giro intorno alla pista: se ti va bene, qualcuno l'avrà visto. Trascinalo qui, o almeno fatti dire da lui la mia frase magica, così potremo aprire il forziere!", "Cosa aspetti? Mi serve la mia frase magica!", "Ah, ora ricordo...\n\nMi ero dimenticato di quella piccola maledizione che ho lanciato su Johnson. Non ricordo perché l'ho fatto, ma sono sicuro che se l'è meritata, quel piccolo ingrato!", 0x5a6e9070, 0xff721e76, 0x81aae872, 0xe0b09124, 0xf89c07ae, "....." },
  [1959] = { "Rapporto ad Anastasia", "Parla con Anastasia Hartwell.", "I maghi di ⟦Undercity=Sepulcra⟧ hanno notato un'anomalia magica all'interno della città e hanno chiesto ai maghi dell'⟦Horde=Orda⟧ di indagare.\n\nAnastasia Hartwell può dirti di più. Parla con lei nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧.", nil, "È vero. Nella nostra città è stata rilevata un'anomalia magica. Non sappiamo ancora quale sia la sua origine, né se sia maligna o benigna. Prima dobbiamo raccogliere altre informazioni...\n\nE questo, {name}, ci porta al tuo compito.", 0xa475d463, 0x6490e08e, 0x63fa5d80, nil, 0x27c6603d, "...m." },
  [1960] = { "Indagine nella bottega d'alchimia", "Prendi un ⟦Cantation of Manifestation=Canto della Manifestazione⟧ e un ⟦Chest of Containment Coffers=Forziere di Casse di Contenimento⟧ da dietro Anastasia Hartwell. Porta 3 Forziere di Contenimento Pieno, il ⟦Chest of Containment Coffers=Forziere di Casse di Contenimento⟧ e il ⟦Cantation of Manifestation=Canto della Manifestazione⟧ ad Anastasia a ⟦Undercity=Sepulcra⟧.", "La bottega d'alchimia di Algernon, nell'Apothecarium, è il centro di uno strano disturbo. Creature invisibili, fatte solo di magia, vagano per la bottega: dev'esserci una ragione, e dobbiamo scoprirla!\n\nIndaga sul disturbo e cattura quelle creature. Prendi un forziere di casse e una pergamena da dietro di me. Usa la pergamena nella bottega per rendere visibili le creature, sottomettile con i tuoi incantesimi, poi getta a terra una cassa per catturarle. Torna con le casse piene, quelle vuote e il canto.", "Hai indagato sul disturbo, {name}? Hai catturato le creature?", "Molto bene, {name}. Le creature in questi forzieri di contenimento saranno studiate dalle nostre menti migliori, e scopriremo il motivo della loro presenza a ⟦Undercity=Sepulcra⟧.\n\nSe la loro comparsa è causata da una frattura nel flusso naturale della magia, dobbiamo stabilire se la frattura sia stata casuale. Se non lo è stata, ma si è trattato invece di un attacco da parte di qualche forza magica, dobbiamo prepararci a disturbi futuri, e più gravi.", 0x3d00ed2a, 0x782743e8, 0x8a0f9c02, 0xf5165c0b, 0x2724ebaf, "....." },
  [1961] = { "Raccolta di materiali", "Porta 10 pezze di lino e 6 Dalaran Mana Gem a Josef Gregorian.", "È il momento di indossare le tue prime vesti da mago, {name}. Sono un segno del tuo rango e una testimonianza del tuo valore.\n\nPer ottenerle devi raccogliere le gemme del mana dai maghi di Dalaran a ⟦Silverpine=Pinargento⟧. Le loro convinzioni sono simili alle nostre, quindi ucciderli è piuttosto sgradevole, ma se non hanno la forza di resisterci, allora non meritano di vivere.\n\nPorta le gemme e una scorta di lino a Josef Gregorian, nella sartoria del Quartiere della Magia.", "Anastasia mi aveva detto che saresti venut<o/a> da me, e sono pronto a confezionare le tue vesti. Hai le gemme e il lino?", "È un materiale molto buono, e anche se non ho il talento per giudicare la qualità di queste gemme del mana, presto sapremo se possiedono il potere necessario per creare le Spellfire Robes...", 0x2c5cc185, 0x01f81e3a, 0x31421ea5, 0xf26b5dc2, 0x7b0078e9, "....." },
  [1962] = { nil, nil, nil, nil, "Ecco le tue vesti, {name}. Portale con onore.", 0xd0e883d2, nil, nil, nil, 0x1484d0c1, "emmm." },
  [1963] = { "La Shattered Hand", "Uccidi Tazan e porta la sua valigetta a Therzok nel Cleft of Shadow, a Orgrimmar.", "Il Capoguerra è troppo cauto nei suoi metodi. Esita a scatenare la potenza dell'⟦Horde=Orda⟧. Un tempo eravamo più forti, tutti possenti conquistatori. Dobbiamo riconquistare quell'orgoglio, e la Shattered Hand lo farà.\n\nCresciamo in forza nell'ombra e colpiamo chi è scoperto, abbattendo in segreto i nostri nemici. Devi portare a termine un compito per me, per dimostrare il tuo valore.\n\nIl troll Tazan commercia con i pirati vicino a ⟦Ratchet=Porto Paranco⟧. Ha informazioni che devo avere. Uccidilo e portami la sua valigetta.", "Solo uno stolto crede che una carica con l'ascia sguainata sia più pericolosa di un coltello nel buio.", "Mm, anche se sono lieto di sapere che Tazan non è più tra noi, una valigetta chiusa a chiave non ci serve a nulla. Ci servono le informazioni che contiene.\n\nQuesta dovrebbe essere una seconda prova degna per chi vuole unirsi alla Shattered Hand.", 0xaa823b93, 0x5a2a4bc5, 0x000efca9, 0x8d47ba3b, 0xddd506ad, "....." },
  [1978] = { "Gli ⟦Deathstalkers=Inseguitori della Morte⟧", "Consegna il ⟦Andron's Ledger=Libro Mastro di Andron⟧ a Varimathras nella Hall of the Dark Lady, a ⟦Undercity=Sepulcra⟧.", "La ⟦Syndicate=Lega dei Tagliagole⟧? Non l'avrei mai sospettato. Pare che i signori di Alterac siano caduti molto in basso negli anni dopo il loro tradimento.\n\nLord Varimathras sarà lieto di saperlo e, visto che sei <stato/stata> così determinante in questa scoperta, è giusto che sia tu a consegnargliela.\n\nAh, e come potevo dimenticarlo?\n\n<Benvenuto/Benvenuta> tra gli ⟦Deathstalkers=Inseguitori della Morte⟧.", "Sì?", "Mmm, questo è interessante. Gli ⟦Deathstalkers=Inseguitori della Morte⟧ hanno svolto il loro compito in modo ammirevole nello scovare tutto questo.\n\nA quanto capisco, anche tu meriti un encomio per il tuo operato. Spero che per te diventi un'abitudine, {name}: ai miei ⟦Deathstalkers=Inseguitori della Morte⟧ serve sempre qualcuno di valore.", 0x188cbd51, 0xe84bf2aa, 0x06c42722, 0x0c07a888, 0x6f0b3033, ".....", nil, nil, nil, nil, 0x9dd8ce85 },
  [1998] = { nil, "Uccidi Fenwick Thatros e riporta la sua testa a Mennet Carkad nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧ di ⟦Undercity=Sepulcra⟧.", "Lord Varimathras mi ha appena inviato un messaggio su una minaccia per i Reietti che va eliminata subito. Si chiama Fenwick Thatros ed è, secondo lord Varimathras, uno dei capi dei non morti che hanno messo radici nella ⟦Silverpine Forest=Selva Pinargento⟧.\n\nIl tuo nome mi è venuto in mente all'istante, {name}. Ho abbastanza fiducia nelle tue capacità da sapere che porterai a termine questa missione alla perfezione.\n\nGli ultimi rapporti degli ⟦Deathstalkers=Inseguitori della Morte⟧ a ⟦Silverpine=Pinargento⟧ indicano che Thatros si trova vicino al molo in rovina sul Lago Lordamere.", "Ho riposto la massima fiducia in te perché svolgessi questo servizio per lord Varimathras.", "Hai fatto un buon lavoro, {name}. Mi rendo conto che hai reso molti servigi agli ⟦Deathstalkers=Inseguitori della Morte⟧, dimostrando il tuo valore, e che forse è tempo di approfondire il tuo addestramento nelle arti dell'ombra.", 0x781cfb68, 0x4baac6d9, 0xb8ed3a72, 0xab7b0537, 0xdd812daf, "e...." },
  [1999] = { "Gli attrezzi del mestiere", "Trova il ⟦Dalaran Status Report=Rapporto sulla Situazione di Dalaran⟧ e riportalo a Mennet Carkad, nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧ di ⟦Undercity=Sepulcra⟧.", "I maghi del Kirin Tor a ⟦Ambermill=Mulino d'Ambra⟧ hanno nascosto documenti importanti sulla situazione attuale di Dalaran. Lo sappiamo dalle confessioni di uno dei nostri prigionieri. Lord Varimathras ha affidato agli ⟦Deathstalkers=Inseguitori della Morte⟧ il compito di recuperarli.\n\nQuesto compito spetta a te, {name}. Però ti servirà dell'attrezzatura, e la conoscenza dello scasso. Parla con Estelle Gendry, la nostra fornitrice, e chiedile un set di attrezzi prima di partire.", "Hai trovato i documenti, {name}?", "Molto bene, {name}! Hai imparato bene la raffinata arte dello scasso, e più in fretta di quanto potessi mai aspettarmi.\n\nVedo che ho fatto bene a fidarmi di te. Credimi, <ragazzo/ragazza>, prevedo che farai molta strada in questo mestiere.", 0x47f8e1ca, 0xcb3a5841, 0x4a4717c8, 0xf5e3d303, 0x327c0ba9, ".....", nil, nil, nil, nil, 0xce9cbc9b },
})
